def _wait_for_network(ping_host='8.8.8.8', check_interval=30, max_wait_min=180):
    """
    Blocks until network connectivity is restored.

    Sends a simple TCP connection attempt to ping_host:80 every
    check_interval seconds (no ICMP needed, works without root).

    Args:
        ping_host:      IP to probe (default: Google DNS 8.8.8.8)
        check_interval: Seconds between probes
        max_wait_min:   Give up after this many minutes (0 = wait forever)

    Returns:
        True  – network restored
        False – timed out (max_wait_min exceeded)
    """
    import socket, time as _time
    deadline = _time.time() + max_wait_min * 60 if max_wait_min > 0 else None
    attempt  = 0

    print(f"\n  ⚠  Network unreachable – waiting for connection to return...")
    print(f"     Probing {ping_host} every {check_interval}s "
          f"(timeout: {'∞' if not deadline else f'{max_wait_min} min'})")

    while True:
        attempt += 1
        try:
            sock = socket.create_connection((ping_host, 80), timeout=5)
            sock.close()
            elapsed = int(_time.time() - (deadline - max_wait_min * 60)) if deadline else 0
            print(f"\n  ✓  Network restored after ~{elapsed}s (attempt {attempt})")
            return True
        except OSError:
            pass

        if deadline and _time.time() >= deadline:
            print(f"\n  ✗  Network still down after {max_wait_min} min – giving up")
            return False

        # Show a dot every check_interval seconds so the console isn't frozen
        remaining = f"  (max wait: {int((deadline - _time.time()) / 60)}m left)" if deadline else ""
        print(f"     [{attempt}] No connection{remaining} – retrying in {check_interval}s...",
              end='\r', flush=True)
        _time.sleep(check_interval)


class PleaseWaitError(Exception):
    """Raised when the API returns a 'please wait' / rate-limit response."""
    pass


class TyrantCommander:
    """Main class for API operations - Standalone Version"""

    JS_INLINE = """
<script src="jquery-latest.js"></script>
<script src="jquery_tablesorter.js"></script>
<script>
$(document).ready(function(){
  $("table.sortable").tablesorter({
    sortList: [[1,1]], widgets: ['zebra'],
    headers: {1:{sorter:'digit'},2:{sorter:'digit'},3:{sorter:'digit'},
              4:{sorter:'digit'},5:{sorter:'digit'},6:{sorter:'digit'},
              7:{sorter:'digit'},8:{sorter:'digit'},9:{sorter:'digit'},
              10:{sorter:'digit'},11:{sorter:'digit'}}
  });
  $('#export-pdf-btn').on('click', function(){ window.print(); });
  // Fallback: also set onclick directly in case jQuery failed to load
  var btn = document.getElementById('export-pdf-btn');
  if (btn) btn.onclick = function(){ window.print(); };
});
</script>"""
    
    def __init__(self, settings_path):
        """
        Initializes the API connection.

        Args:
            settings_path: Path to the settings JSON file
        """
        self.api = TyrantAPI(settings_path)
        self.settings_path = settings_path   # needed for persisting blacklist etc.
        self.init_data = None
        self._card_data_cache  = None
        self._card_data_with_rarity_cache = None  # Rarity-aware cache (used by buyback)
        self._last_sp_needed = 0                  # Set by _build_single_card_info on SP failure
        self.tuo_threads = 12  # TUO -t flag (thread count), configurable via settings
        self.tuo_order_mode = 'ordered'  # default play mode
    # ── Mission Blacklist (persisted in settings_N.json) ──────────────────────

    def _load_mission_blacklist(self):
        """Load mission blacklist from settings file. Returns a set of ints."""
        try:
            with open(self.settings_path, 'r') as f:
                s = json.load(f)
            return set(int(x) for x in s.get('mission_blacklist', []))
        except Exception:
            return set()

    def _save_mission_blacklist(self, blacklist):
        """Persist mission blacklist (set of ints) back to settings file."""
        try:
            with open(self.settings_path, 'r') as f:
                s = json.load(f)
            s['mission_blacklist'] = sorted(blacklist)
            with open(self.settings_path, 'w') as f:
                json.dump(s, f, indent=2)
        except Exception as e:
            pass   # non-fatal – blacklist simply not saved


    
    def _print_api_error(self, result, context="API call"):
        """
        Helper method to print API error responses in a concise way
        
        Args:
            result: API response dict
            context: Description of what failed (e.g. "Buyback", "Save deck")
        """
        if not result:
            return
        
        # Only show relevant error fields, not the entire response
        relevant_keys = ['message', 'result', 'error', 'error_message', 'error_code']
        
        has_info = False
        for key in relevant_keys:
            if key in result:
                print(f"   {key}: {result[key]}")
                has_info = True
        
        # In debug mode, show the full response
        if DEBUG_MODE:
            print(f"\n   [DEBUG] Full {context} response:")
            import pprint
            pprint.pprint(result, indent=6, width=120)
        elif not has_info:
            # If no relevant keys found and not in debug mode, show a hint
            print(f"   (No error details available - run with --debug to see full response)")
    
    def initialize(self, verbose=False):
        """
        Loads initialization data
        
        Args:
            verbose: If True, shows connection messages (only on first start)
        """
        try:
            if verbose:
                print("⏳ Connecting to API...")
            self.init_data = self.api.call('init')
            if verbose:
                print("✓ API connection successfully initialized")
                print("✓ Login data is correct")
            # ── Cache guild name into settings file for proxy lookups ────
            _faction = self.init_data.get('faction')
            if _faction and isinstance(_faction, dict):
                _gname = _faction.get('name', '')
                if _gname and self.api.settings.get('_guild_cache') != _gname:
                    self.api.settings['_guild_cache'] = _gname
                    try:
                        import json as _jini
                        _sf_path = self.api.settings_file if hasattr(self.api, 'settings_file') else None
                        if _sf_path and os.path.isfile(_sf_path):
                            with open(_sf_path, 'r', encoding='utf-8') as _fini:
                                _scfg = _jini.load(_fini)
                            _scfg['_guild_cache'] = _gname
                            with open(_sf_path, 'w', encoding='utf-8') as _fini:
                                _jini.dump(_scfg, _fini, indent=2)
                    except Exception:
                        pass  # non-critical
            return True
        except ValueError as e:
            # Settings-file error
            print(f"✗ Settings file error: {e}")
            return False
        except ConnectionError as e:
            print(f"✗ Connection error: {e}")
            print("  -> Check your internet connection")
            return False
        except RuntimeError as e:
            # API-error (e.g. 400, 403, etc.)
            error_msg = str(e)
            print(f"✗ API error: {error_msg}")
            
            if "403" in error_msg or "401" in error_msg:
                print("  -> Login data is invalid or expired!")
                print("  -> Create a new settings file with current data")
            elif "404" in error_msg:
                print("  -> API endpoint not found")
                print("  -> Check the 'url' in the settings file")
            elif "500" in error_msg or "502" in error_msg or "503" in error_msg:
                print("  -> Server error")
                print("  -> Try again later")
            
            return False
        except Exception as e:
            print(f"✗ Unexpected error during initialization: {e}")
            print(f"  Error type: {type(e).__name__}")
            return False
    
    # ==================== ITEMS / SHARDS ====================

    # Known item IDs and their names
    # Only consumable shards the user wants to interact with
    SHARD_ITEMS = {
        2000: ("Epic Shard",        500),
        2001: ("Legendary Shard",  1000),
        2002: ("Vindicator Shard", 1000),
    }

    def use_shards(self, auto_confirm=False):
        """Use all available Epic / Legendary / Vindicator Shards until depleted"""
        self.initialize(verbose=False)

        user_items = self.init_data.get('user_items', {})
        card_data  = self._load_card_data()

        # Build list of available shards with counts
        available = []
        for item_id, (name, stack_size) in self.SHARD_ITEMS.items():
            info  = user_items.get(str(item_id), {})
            count = int(info.get('number', 0))
            stacks = count // stack_size
            available.append((item_id, name, stack_size, count, stacks))

        print("\n" + "="*55)
        print("USE ALL SHARDS")
        print("="*55)

        # Show what will be used
        total_stacks = sum(s for _, _, _, _, s in available)
        if total_stacks == 0:
            print("✗ No full stacks available")
            for _, name, stack_size, count, _ in available:
                if count > 0:
                    print(f"  {name}: {count}x (need {stack_size} for one stack)")
            return

        for item_id, name, stack_size, count, stacks in available:
            remainder = count % stack_size
            if stacks > 0:
                rem_str = f" + {remainder} leftover" if remainder else ""
                print(f"  {name:<22} {count:>6}x  ->  {stacks} stack{'s' if stacks != 1 else ''}{rem_str}")
            else:
                print(f"  {name:<22} {count:>6}x  ->  ✗ not enough for a stack ({stack_size} needed)")

        print(f"\n  Total: {total_stacks} stack{'s' if total_stacks != 1 else ''} to use")

        if auto_confirm:
            print("  [AUTO] Using all stacks automatically...")
        elif not confirm_action(f"\nUse all {total_stacks} stacks now?"):
            print("Canceled")
            return False

        # Loop through all shards
        grand_total_cards = []
        grand_errors = 0

        _BAR_W = 30
        for item_id, name, stack_size, count, stacks in available:
            if stacks == 0:
                continue

            shard_cards = []

            for i in range(stacks):
                # Overwriting progress bar for this shard type
                _filled = int(_BAR_W * i / stacks)
                _bar    = '█' * _filled + '░' * (_BAR_W - _filled)
                print(f"\r  {name}: [{_bar}] {i}/{stacks}", end='', flush=True)

                result = self.api.call('consumeItem', item_id=item_id)

                if result and result.get('result') in (True, 1, "1", "true"):
                    new_cards = result.get('new_cards', [])
                    shard_cards.extend(new_cards)
                else:
                    print()   # end bar line before error
                    grand_errors += 1
                    self._print_api_error(result, "consumeItem")
                    break

                if i < stacks - 1:
                    time.sleep(0.5)

            # Final bar state (full) + summary
            _bar = '█' * _BAR_W
            print(f"\r  ✓ {name}: [{_bar}] {stacks}/{stacks}  ->  {len(shard_cards)} cards")
            grand_total_cards.extend(shard_cards)

        # Final summary
        print(f"\n{'='*55}")
        print(f"✓ All shards used  ->  {len(grand_total_cards)} cards total")
        print(f"{'─'*55}")

        for card_id in grand_total_cards:
            try:
                cid   = int(str(card_id).strip())
                info  = card_data.get(cid, {})
                cname = info.get('name', f"ID {cid}") if isinstance(info, dict) else (str(info) or f"ID {cid}")
                print(f"  + {cname}")
            except Exception:
                print(f"  + ID {card_id}")

        print(f"{'='*55}\n")

    # ==================== QUESTS & ACHIEVEMENTS ====================

    def fuse_all_maxed_cards_all_accounts(self):
        """Runs fuse_all_maxed_cards for all play_enabled accounts."""
        import glob as _glob, json as _json

        settings_dirs  = [SCRIPT_DIR, os.path.join(SCRIPT_DIR, 'settings')]
        settings_files = []
        for sd in settings_dirs:
            settings_files += _glob.glob(os.path.join(sd, 'settings_*.json'))
        settings_files = [f for f in settings_files
                          if not os.path.basename(f).startswith('settings_TEMPLATE')]
        settings_files = sorted({os.path.normpath(f): f for f in settings_files}.values())

        print(f"\n{'='*65}")
        print(f"  FUSE ALL MAXED CARDS – ALL ACCOUNTS")
        print(f"{'='*65}")

        ok = 0; skipped = 0; failed = 0
        for sf in settings_files:
            nick = os.path.basename(sf).replace('settings_', '').replace('.json', '')
            try:
                with open(sf, 'r', encoding='utf-8') as fh:
                    cfg = _json.load(fh)
                if not cfg.get('play_enabled', True):
                    skipped += 1
                    continue
            except Exception:
                skipped += 1
                continue

            print(f"\n{'─'*65}")
            print(f"  [{nick}]")
            try:
                tmp = TyrantCommander(sf)
                if not tmp.initialize(verbose=False):
                    print(f"  ✗ Login failed")
                    failed += 1
                    continue
                tmp.fuse_all_maxed_cards()
                ok += 1
            except Exception as e:
                print(f"  ✗ {e}")
                failed += 1

        print(f"\n{'='*65}")
        print(f"  Done — {ok} ✓  {failed} ✗  {skipped} skipped")

