    def _detect_loyal_challenge_step(self):
        """Returns (step_number, meta_achievement, challenge_table) or (None, None, None).
        Prefers time-limited challenges (Forever Loyal); falls back to Extreme PVP Challenge."""
        achievements = self.init_data.get('user_achievements', {})
        import time as _time2
        _now2 = int(_time2.time())

        # 1st priority: time-limited type-12 with 'loyal'/'forever' in name
        meta_loyal = meta_loyal_expired = None
        # 2nd priority: Extreme PVP Challenge (no end_time)
        meta_extreme = None

        for aid, a in achievements.items():
            if int(a.get('type', 0)) != 12:
                continue
            nm    = a.get('name', '').lower()
            end_t = int(a.get('end_time', 0))
            if 'loyal' in nm or 'forever' in nm:
                if end_t > _now2:
                    meta_loyal = a
                elif meta_loyal_expired is None:
                    meta_loyal_expired = a
            elif 'extreme' in nm:
                if meta_extreme is None:
                    meta_extreme = a

        # Pick best candidate
        meta  = meta_loyal or meta_loyal_expired
        table = self.LOYAL_CHALLENGES
        if not meta and meta_extreme:
            meta  = meta_extreme
            table = self.EXTREME_CHALLENGES

        if not meta:
            return None, None, None
        prog = int(meta.get('progress', 0))
        mx   = int(meta.get('max_progress', len(table)))
        if prog >= mx:
            return None, None, None
        step = prog + 1
        if step > len(table):
            return None, None, None
        return step, meta, table

    def _find_card_id_by_name(self, name, card_data):
        """Return base card_id (lowest level) for a card name, or None."""
        name_lower = name.lower()
        for cid, info in card_data.items():
            if not isinstance(info, dict):
                continue
            if info.get('name', '').lower() == name_lower and info.get('level', 1) == 1:
                return int(cid)
        return None

    def _resolve_to_max_level_id(self, base_cid, card_data):
        """Find the max-level card_id for a given card by searching all cards
        with the same base_id and returning the one with the highest xml_level."""
        base_cid = int(base_cid)
        info = card_data.get(base_cid, {})
        if not isinstance(info, dict):
            return base_cid
        # Get the base_id to search by (all levels share the same base_id)
        base_id_ref = info.get('base_id', base_cid)
        best_id  = base_cid
        best_lvl = info.get('xml_level') or info.get('level', 1) or 1
        for cid, cinfo in card_data.items():
            if not isinstance(cinfo, dict):
                continue
            if cinfo.get('base_id') != base_id_ref:
                continue
            lvl = cinfo.get('xml_level') or cinfo.get('level', 1) or 1
            if lvl > best_lvl:
                best_lvl = lvl
                best_id  = cid
        return int(best_id)

    def _upgrade_card_to_max(self, base_cid, card_data):
        """Delegate to build_card which handles buyback, restore, fusion chain."""
        info = card_data.get(int(base_cid), {})
        name = info.get('name', '') if isinstance(info, dict) else ''
        if not name:
            return None
        return self._ensure_card_at_max_level(name, card_data)

    def _ensure_card_at_max_level(self, name, card_data):
        """Ensure card is at max level. Upgrades if owned at any level, builds from scratch if not owned.
        Returns max-level card_id or None on failure."""
        base_id = self._find_card_id_by_name(name, card_data)
        if not base_id:
            print(f"  ✗ Card not found in card_data: {name}")
            return None
        max_id  = self._resolve_to_max_level_id(base_id, card_data)
        max_info = card_data.get(max_id, {})
        max_xml  = (max_info.get('xml_level') or max_info.get('level', 6)
                    if isinstance(max_info, dict) else 6)
        base_id_ref = (card_data.get(base_id, {}).get('base_id', base_id)
                       if isinstance(card_data.get(base_id, {}), dict) else base_id)

        # ── Find highest level we own ─────────────────────────────────────
        user_cards  = self.init_data.get('user_cards', {})
        owned_id    = None
        owned_xml   = 0
        for cid, cinfo in card_data.items():
            if not isinstance(cinfo, dict):
                continue
            if cinfo.get('base_id') != base_id_ref:
                continue
            if str(cid) not in user_cards:
                continue
            cnt = int((user_cards[str(cid)] or {}).get('num_owned', 0))
            if cnt <= 0:
                continue
            lvl = cinfo.get('xml_level') or cinfo.get('level', 1) or 1
            if lvl > owned_xml:
                owned_xml = lvl
                owned_id  = cid

        if owned_id and owned_xml >= max_xml:
            return int(max_id)   # already at max level

        if owned_id:
            # Card owned at lower level — call build_card with explicit L6 target
            # so the Gold→SP workflow triggers automatically if SP is insufficient
            print(f"  ⚙  Upgrading {name} from L{owned_xml} to L{max_xml} via build_card...")
            try:
                result = self.build_card(f"{name}-{max_xml}")
                if result is False:
                    print(f"  ✗ build_card upgrade failed for {name}")
                    return None
            except Exception as ex:
                print(f"  ✗ build_card upgrade exception for {name}: {ex}")
                return None
            self.initialize(verbose=False)
            user_cards = self.init_data.get('user_cards', {})
            if str(max_id) in user_cards:
                print(f"  ✓ {name} at L{max_xml} (id={max_id})")
                return int(max_id)
            print(f"  ✗ {name} still not at L{max_xml} after upgrade")
            return None

        # Not in inventory at all — use build_card
        print(f"  ⚙  Building {name} from scratch via build_card...")
        try:
            result = self.build_card(name)
            if result is False:
                print(f"  ✗ build_card failed for {name}")
                return None
        except Exception as ex:
            print(f"  ✗ build_card exception for {name}: {ex}")
            return None

        self.initialize(verbose=False)
        user_cards = self.init_data.get('user_cards', {})
        if str(max_id) in user_cards:
            print(f"  ✓ {name} built to L{max_xml} (id={max_id})")
            return int(max_id)
        print(f"  ✗ {name} still not at L{max_xml} after build_card")
        return None

    def _loyal_log_issue(self, account_nick, step, reason):
        """Append an issue entry to export/loyal_challenge_issues.txt."""
        import datetime as _dt
        log_path = os.path.join(SCRIPT_DIR, 'export', 'loyal_challenge_issues.txt')
        os.makedirs(os.path.dirname(log_path), exist_ok=True)
        ts = _dt.datetime.now().strftime('%Y-%m-%d %H:%M:%S')
        with open(log_path, 'a', encoding='utf-8') as _f:
            _f.write(f"[{ts}]  Account: {account_nick}  Step {step}: {reason}\n")
        print(f"  ⚠  Logged issue to {log_path}")

    def _apply_loyal_deck_adjustments(self, step, card_data, deck_slot=1, challenge_table=None):
        """Adjust slot-1 deck for the current challenge step.
        Returns (original_deck_cards, original_commander_id) for restore, or (None, None) on error."""
        table = challenge_table if challenge_table is not None else self.LOYAL_CHALLENGES
        if step < 1 or step > len(table):
            return None, None

        ch = table[step - 1]
        print(f"  ♟  Challenge step {step}: {ch['name']}")

        nick = (self.api.settings.get('request_data', {}).get('kong_name', '')
                or self.api.settings.get('kong_name', ''))

        needs_change = bool(ch['commander'] or ch['required'] or ch['pool_min'] > 0)
        if not needs_change:
            print(f"     No deck changes needed for this step.")
            return None, None

        # ── PHASE 0: Snapshot original deck BEFORE any builds ────────────
        user_decks_snap = self.init_data.get('user_decks', {})
        deck_info_snap  = user_decks_snap.get(str(deck_slot), {})
        orig_cmdr_snap  = deck_info_snap.get('commander_id', '') if isinstance(deck_info_snap, dict) else ''
        orig_card_ids   = []
        if isinstance(deck_info_snap.get('cards'), dict):
            for cid, cnt in deck_info_snap['cards'].items():
                orig_card_ids.extend([str(cid)] * int(cnt))
        elif isinstance(deck_info_snap.get('cards'), list):
            for cid in deck_info_snap['cards']:
                orig_card_ids.append(str(cid))

        # ── PHASE 1: Pre-check Slot 1 for already-equipped cards ─────────
        user_decks = self.init_data.get('user_decks', {})
        deck_info  = user_decks.get(str(deck_slot), {})
        deck_cards = deck_info.get('cards', {}) if isinstance(deck_info, dict) else {}
        # Build name→(card_id, level) map for cards currently in the deck
        deck_card_names = {}
        for cid in (deck_cards.keys() if isinstance(deck_cards, dict) else deck_cards):
            info = card_data.get(int(cid), {})
            if isinstance(info, dict):
                base_name = info.get('name', '').lower()
                # strip level suffix
                import re as _re
                base_name = _re.sub(r'-\d+$', '', base_name).strip()
                lvl = info.get('xml_level') or info.get('level', 1)
                max_info  = card_data.get(self._resolve_to_max_level_id(int(cid), card_data), {})
                max_level = (max_info.get('xml_level') or max_info.get('level', 6)
                             if isinstance(max_info, dict) else 6)
                deck_card_names[base_name] = {
                    'card_id': int(cid), 'level': lvl, 'max_level': max_level}

        # ── PHASE 2: Build/upgrade required & pool cards ──────────────────
        required_ids = []
        for card_name in ch['required']:
            name_key = card_name.lower()
            in_deck  = deck_card_names.get(name_key)
            if in_deck:
                lvl = in_deck['level']
                max_lvl = in_deck['max_level']
                if lvl >= max_lvl:
                    print(f"     Required: {card_name} already at L{lvl} in deck")
                    required_ids.append(str(in_deck['card_id']))
                    continue
                else:
                    print(f"     Required: {card_name} in deck at L{lvl}, upgrading to L{max_lvl}...")
            cid = self._ensure_card_at_max_level(card_name, card_data)
            if cid:
                required_ids.append(str(cid))
                print(f"     Required: {card_name} ready (id={cid})")
            else:
                reason = f"Required card not available: {card_name}"
                print(f"  ✗ {reason}")
                self._loyal_log_issue(nick, step, reason)
                return None, None  # abort before modifying deck

        pool_ids = []
        remaining = ch['pool_min']

        # Build ordered list of (card_name, count_needed) preserving pool order
        seen_pool = {}
        pool_order = []
        for card_name in ch['pool']:
            if card_name not in seen_pool:
                seen_pool[card_name] = 0
                pool_order.append(card_name)
            seen_pool[card_name] += 1

        for card_name in pool_order:
            if remaining <= 0:
                break
            want = remaining  # use as many copies of this card as needed

            base   = self._find_card_id_by_name(card_name, card_data)
            if not base:
                print(f"  ✗ Pool card not in card_data: {card_name}")
                continue
            max_id = self._resolve_to_max_level_id(base, card_data)

            # Step A: equip from existing inventory
            self.initialize(verbose=False)
            uc    = self.init_data.get('user_cards', {})
            owned = int((uc.get(str(max_id)) or {}).get('num_owned', 0))
            equip_now = min(owned, want)
            for _ in range(equip_now):
                pool_ids.append(str(max_id))
                print(f"     Pool [{len(pool_ids)}]: {card_name} (from inventory, id={max_id})")
            remaining -= equip_now
            still_need = want - equip_now

            # Step B: build missing copies one by one via build_card directly
            for i in range(still_need):
                if remaining <= 0:
                    break
                print(f"     Pool: building {card_name} copy {i+1}/{still_need}...")
                try:
                    max_info2 = card_data.get(max_id, {})
                    max_lvl2  = (max_info2.get('xml_level') or max_info2.get('level', 6)
                                 if isinstance(max_info2, dict) else 6)
                    # Capture output to detect SP vs material failure; suppress prompts
                    import builtins as _bi, sys as _sys, io as _io
                    _orig_input = _bi.input
                    _bi.input = lambda _p='': (print(f"  [auto] {_p}YES"), 'yes')[1]
                    _orig_confirm = _sys.modules[__name__].__dict__.get('confirm_action')
                    _sys.modules[__name__].__dict__['confirm_action'] = lambda _p='': True
                    _cap = _io.StringIO()
                    _orig_stdout = _sys.stdout
                    _sys.stdout = _cap
                    try:
                        result = self.build_card(f"{card_name}-{max_lvl2}")
                    finally:
                        _sys.stdout = _orig_stdout
                        _build_output = _cap.getvalue()
                        print(_build_output, end='')  # show output normally
                        _bi.input = _orig_input
                        if _orig_confirm is not None:
                            _sys.modules[__name__].__dict__['confirm_action'] = _orig_confirm
                    if result is False:
                        print(f"  ✗ build_card failed for additional {card_name}")
                        break
                except Exception as ex:
                    print(f"  ✗ build_card exception for {card_name}: {ex}")
                    break
                # Re-read inventory fresh after each build
                self.initialize(verbose=False)
                uc2    = self.init_data.get('user_cards', {})
                owned2 = int((uc2.get(str(max_id)) or {}).get('num_owned', 0))
                if owned2 > owned + len([p for p in pool_ids if p == str(max_id)]) - equip_now:
                    pool_ids.append(str(max_id))
                    remaining -= 1
                    print(f"     Pool [{len(pool_ids)}]: {card_name} built (id={max_id})")
                else:
                    print(f"  ✗ No new copy detected for {card_name} — moving to next card")
                    if 'not enough sp' in _build_output.lower():
                        self._loyal_log_issue(nick, step, f"Insufficient SP to build additional {card_name} — fell through to next pool card")
                    break

        if len(pool_ids) < ch['pool_min']:
            reason = (f"Only {len(pool_ids)}/{ch['pool_min']} pool cards available "
                      f"(needed from: {', '.join(pool_order)})")
            print(f"  ✗ {reason} — proceeding with what we have")
            self._loyal_log_issue(nick, step, reason)

        # ── PHASE 3: Re-read deck AFTER all builds for new configuration ──
        self.initialize(verbose=False)
        user_decks = self.init_data.get('user_decks', {})
        deck_info  = user_decks.get(str(deck_slot), {})
        if not isinstance(deck_info, dict):
            reason = f"Could not read deck slot {deck_slot} after build"
            print(f"  ✗ {reason}")
            self._loyal_log_issue(nick, step, reason)
            return None, None

        orig_cmdr = orig_cmdr_snap  # use pre-build snapshot for restore
        new_card_ids = []
        if isinstance(deck_info.get('cards'), dict):
            for cid, cnt in deck_info['cards'].items():
                new_card_ids.extend([str(cid)] * int(cnt))
        elif isinstance(deck_info.get('cards'), list):
            for cid in deck_info['cards']:
                new_card_ids.append(str(cid))
        dom_id = str(deck_info.get('dominion_id') or '')

        # ── PHASE 4: Commander swap ───────────────────────────────────────
        new_cmdr_id = orig_cmdr
        if ch['commander']:
            cmdr_id = self._find_card_id_by_name(ch['commander'], card_data)
            if cmdr_id:
                new_cmdr_id = cmdr_id
                print(f"     Commander → {ch['commander']} (id={cmdr_id})")
            else:
                reason = f"Commander not found in card data: {ch['commander']}"
                print(f"  ✗ {reason}")
                self._loyal_log_issue(nick, step, reason)

        # Pad deck to maximum size (10) before replacement so challenge cards
        # don't reduce the deck size if the original had fewer than 10.
        while len(new_card_ids) < 10 and new_card_ids:
            new_card_ids.append(new_card_ids[0])

        # Deck order doesn't affect draw order (game randomises hand from full deck).
        # Just ensure required + pool cards are in the deck; TUO decides play order.
        all_new = required_ids + pool_ids

        if all_new:
            n = len(all_new)
            if n > len(new_card_ids):
                new_card_ids = all_new
            else:
                new_card_ids[-n:] = all_new
            print(f"     Replaced last {n} deck slot(s) with challenge cards")

        # Skip setDeckCards if nothing changed at all
        cmdr_changed  = str(new_cmdr_id) != str(orig_cmdr)
        cards_changed = new_card_ids != orig_card_ids
        if not cmdr_changed and not cards_changed:
            print(f"  ✓ Deck already correct for step {step}")
            return (orig_card_ids, str(orig_cmdr))

        # ── PHASE 6: setDeckCards ─────────────────────────────────────────
        try:
            from collections import Counter as _Counter
            import json as _json2
            cards_json = _json2.dumps(
                {str(c): str(cnt) for c, cnt in _Counter(str(c) for c in new_card_ids).items()}
            )
            result = self.api.call(
                'setDeckCards',
                deck_id=str(deck_slot),
                commander_id=str(new_cmdr_id),
                dominion_id=dom_id,
                cards=cards_json,
                activeYN='1',
            )
            ok = result and (
                result.get('result') in (True, 1, '1', 'true')
                or 'user_decks' in result
                or 'user_data' in result
            )
            if ok:
                print(f"  ✓ Deck slot {deck_slot} updated for step {step}")
            else:
                reason = f"setDeckCards failed: {result}"
                print(f"  ✗ {reason}")
                self._loyal_log_issue(nick, step, reason)
                return None, None
        except Exception as ex:
            reason = f"setDeckCards exception: {ex}"
            print(f"  ✗ {reason}")
            self._loyal_log_issue(nick, step, reason)
            return None, None

        return (orig_card_ids, str(orig_cmdr_snap))

    def _restore_loyal_deck(self, orig_card_ids, orig_cmdr_id, deck_slot=1):
        """Restore original deck after Loyal challenge battles."""
        if not orig_card_ids:
            return
        try:
            from collections import Counter as _Counter
            import json as _json2
            cards_json = _json2.dumps(
                {str(c): str(cnt) for c, cnt in _Counter(str(c) for c in orig_card_ids).items()}
            )
            # Retrieve dominion from current init_data
            dom_id = str((self.init_data.get('user_decks', {}).get(str(deck_slot), {}) or {}).get('dominion_id') or '')
            result = self.api.call(
                'setDeckCards',
                deck_id=str(deck_slot),
                commander_id=str(orig_cmdr_id),
                dominion_id=dom_id,
                cards=cards_json,
                activeYN='1',
            )
            ok = result and (
                result.get('result') in (True, 1, '1', 'true')
                or 'user_decks' in result
                or 'user_data' in result
            )
            if ok:
                print(f"  ✓ Deck slot {deck_slot} restored to original")
            else:
                print(f"  ✗ Restore setDeckCards failed: {result}")
        except Exception as ex:
            print(f"  ✗ Restore exception: {ex}")

    def loyal_challenge_overview(self):
        """Lists all active accounts with their current PvP Challenge step
        and the progress of the current sub-challenge. Works for any active type-12 challenge.
        Press Enter to refresh, ESC to exit."""
        import glob as _glob
        import datetime as _dt
        import time as _time

        settings_dirs  = [SCRIPT_DIR, os.path.join(SCRIPT_DIR, 'settings')]
        settings_files = []
        for sd in settings_dirs:
            settings_files += _glob.glob(os.path.join(sd, 'settings_*.json'))
        settings_files = [f for f in settings_files
                          if not os.path.basename(f).startswith('settings_TEMPLATE')]
        settings_files = sorted({os.path.normpath(f): f for f in settings_files}.values())

        if not settings_files:
            print("  \u2717 No settings files found.")
            return

        prev_state = {}   # nick \u2192 {'step': int, 'prog': int}

        while True:
            print("\n" + "="*100)
            print("  PVP CHALLENGE OVERVIEW \u2013 ALL ACCOUNTS")
            print("="*100)
            print(f"  {'Account':<22}  {'Step':>8}  {'Challenge':<22}  {'Sub-Challenge':<22}  {'Progress':>14}  {'Ends':>10}")
            print(f"  {'\u2500'*22}  {'\u2500'*8}  {'\u2500'*22}  {'\u2500'*22}  {'\u2500'*14}  {'\u2500'*10}")

            for sf in settings_files:
                tmp = TyrantCommander(sf)
                if not tmp.initialize(verbose=False):
                    nick = tmp.api.settings.get('kong_name', sf)
                    print(f"  {nick:<22}  {'\u2013':>8}  {'Login failed':<22}  {'\u2013':<22}  {'\u2013':>14}  {'\u2013':>10}")
                    continue
                if not tmp.api.settings.get('play_enabled', True):
                    continue

                nick = (tmp.api.settings.get('request_data', {}).get('kong_name', '')
                        or tmp.api.settings.get('kong_name', sf))

                achievements = tmp.init_data.get('user_achievements', {})

                _now = int(_time.time())
                meta = None
                meta_fallback = None
                for a in achievements.values():
                    if int(a.get('type', 0)) == 12:
                        end_t = int(a.get('end_time', 0))
                        if end_t > _now:
                            meta = a
                            break
                        elif meta_fallback is None:
                            meta_fallback = a
                if not meta:
                    meta = meta_fallback

                if not meta:
                    print(f"  {nick:<22}  {'\u2013':>8}  {'No challenge active':<22}  {'\u2013':<22}  {'\u2013':>14}  {'\u2013':>10}")
                    continue

                meta_name = meta.get('name', 'PvP Challenge')
                meta_prog = int(meta.get('progress', 0))
                meta_max  = int(meta.get('max_progress', 1))
                meta_end  = int(meta.get('end_time', 0))
                end_str   = _dt.datetime.fromtimestamp(meta_end).strftime('%d.%m.%y') if meta_end else '\u2013'

                if meta_prog >= meta_max:
                    print(f"  {nick:<22}  {'\u2713':>8}  {meta_name[:22]:<22}  {'All complete!':<22}  {'\u2013':>14}  {end_str:>10}")
                    prev_state[nick] = {'step': meta_prog, 'prog': meta_prog}
                    continue

                step = meta_prog + 1

                sub_name = sub_prog = sub_max = None
                for a in achievements.values():
                    if int(a.get('type', 0)) == 9:
                        if meta_end and int(a.get('end_time', 0)) != meta_end:
                            continue
                        sp = int(a.get('progress', 0))
                        sm = int(a.get('max_progress', 1))
                        if sp < sm:
                            sub_name = a.get('name', '')
                            sub_prog = sp
                            sub_max  = sm
                            break

                prev      = prev_state.get(nick, {})
                prev_step = prev.get('step')
                prev_prog = prev.get('prog')

                if prev_step is not None and step > prev_step:
                    step_str = f"{step} (+{step - prev_step})"
                    prog_delta = ''
                else:
                    step_str = str(step)
                    if prev_prog is not None and sub_prog is not None and sub_prog > prev_prog:
                        prog_delta = f" (+{sub_prog - prev_prog})"
                    else:
                        prog_delta = ''

                if sub_prog is not None:
                    prog_str = f"{sub_prog}/{sub_max}{prog_delta}"
                    sub_disp = sub_name[:22] if sub_name else '\u2013'
                else:
                    prog_str = '\u2013'
                    sub_disp = '\u2013'

                print(f"  {nick:<22}  {step_str:>8}  {meta_name[:22]:<22}  {sub_disp:<22}  {prog_str:>14}  {end_str:>10}")
                prev_state[nick] = {'step': step, 'prog': sub_prog if sub_prog is not None else 0}

            print("="*100)
            key = input_with_esc("\n  [ENTER] Refresh  |  [ESC] Exit: ", allow_empty=True)
            if key is None:
                break

    def pvp_challenge_loyal(self):
        """Automates the 'Forever Loyal' PvP Challenge.
        Detects current step via user_achievements (type-12 meta, progress counter),
        adjusts deck slot 1 accordingly, and integrates with multi-account arena pipeline."""
        print("\n" + "="*65)
        print("  FOREVER LOYAL – PVP CHALLENGE STATUS")
        print("="*65)

        self.initialize(verbose=False)
        card_data = self._load_card_data_with_rarity() or {}

        step, meta, _ch_table = self._detect_loyal_challenge_step()
        if not step:
            ach = self.init_data.get('user_achievements', {})
            has_any = any(
                any(kw in a.get('name', '').lower() for kw in ('loyal', 'forever', 'extreme'))
                for a in ach.values()
                if int(a.get('type', 0)) == 12
            )
            if has_any:
                print("  ✓ Active challenge already complete!")
            else:
                print("  ✗ No active PvP challenge found in achievements.")
            return

        prog = int(meta.get('progress', 0))
        mx   = int(meta.get('max_progress', len(_ch_table)))
        ch   = _ch_table[step - 1]

        print(f"\n  Meta:     {meta.get('name')}  [{prog}/{mx}]")
        print(f"  Current:  Step {step} — {ch['name']}")
        if ch['commander']:
            print(f"  Commander: {ch['commander']}")
        if ch['required']:
            print(f"  Required:  {', '.join(ch['required'])}")
        if ch['pool_min'] > 0:
            print(f"  Pool ({ch['pool_min']}x): {', '.join(set(ch['pool']))}")

        print()
        orig_ids, orig_cmdr = self._apply_loyal_deck_adjustments(step, card_data, challenge_table=_ch_table)
        if orig_ids:
            input("\n  Deck updated. Press ENTER to start arena battles, Ctrl+C to abort.")
            try:
                self.multi_account_live_sim(mode='arena')
            finally:
                self._restore_loyal_deck(orig_ids, orig_cmdr)

    def _export_arena_opponent_deck(self, enemy_name, winner, battle_data, enemy_guild='', silent=False, brawl_mode=False, live_deck_str=None):
        """
        Exports opponent deck to arenagauntlet.txt
        Format: WIN_Name_Guild or LOSS_Name_Guild: Commander, Card1, Card2, ...
        (Card names instead of IDs)
        
        Args:
            enemy_name: Name of the opponent
            enemy_guild: Guild name of the opponent (empty string if none)
            winner: 1 = Victory, 0 = Defeat
            battle_data: Battle data containing card_map
            silent: If True, suppress success message
        """
        try:
            output_file = os.path.join(SCRIPT_DIR, 'arenagauntlet.txt')
            
            # Check if file needs to be created with header
            file_exists = os.path.exists(output_file)
            
            # Load card data for name translation
            card_data = self._load_card_data()
            if not card_data:
                if not silent:
                    print(f"\n⚠ Failed to load card data - exporting with IDs only")
                card_data = {}
            
            # Determine prefix
            prefix = "WIN" if winner == 1 else "LOSS"
            
            # Build entry key: Name_Guild (if guild known)
            guild_suffix = f"_{enemy_guild}" if enemy_guild else ""
            entry_key = f"{enemy_name}{guild_suffix}"
            
            # Extract opponent deck from battle_data and card_map
            card_map = battle_data.get('card_map', {})

            # If a complete live deck string was fetched before battle, write it
            # as GUILD_ (authoritative full deck, equivalent to guild sync).
            if live_deck_str:
                # Use GUILD_ prefix — live fetch = full defense deck
                _live_guild_key = f"GUILD_{entry_key}"
                if not silent:
                    n_cards = len(live_deck_str.split(','))
                    print(f"  ✓ {_live_guild_key}: live deck written ({n_cards} cards)")
                from datetime import datetime as _dts
                _comment = f"//Last seen on: {_dts.now().strftime('%Y-%m-%d %H:%M')}\n"
                _new_line = f"{_live_guild_key}: {live_deck_str}\n"
                with _GAUNTLET_LOCK:
                    try:
                        with open(output_file, 'r', encoding='utf-8') as _gf:
                            _lines = _gf.readlines()
                    except FileNotFoundError:
                        _lines = []
                    # Replace existing GUILD_/WIN_/LOSS_ entry for this player,
                    # then append the new GUILD_ entry
                    _new_lines = []
                    _i = 0
                    while _i < len(_lines):
                        _s = _lines[_i].strip()
                        if _s.startswith(('GUILD_', 'WIN_', 'LOSS_')):
                            _key = _s.split(': ')[0]
                            # Match any prefix for this player+guild key
                            _inner = _key.split('_', 1)[1] if '_' in _key else ''
                            if _inner == entry_key:
                                # Remove preceding comment line too
                                if _new_lines and _new_lines[-1].strip().startswith('//Last seen on:'):
                                    _new_lines.pop()
                                _i += 1
                                continue
                        _new_lines.append(_lines[_i])
                        _i += 1
                    _new_lines.append(_comment)
                    _new_lines.append(_new_line)
                    import tempfile as _tfe2, os as _ose2
                    _dir2 = os.path.dirname(output_file)
                    with _tfe2.NamedTemporaryFile('w', encoding='utf-8', dir=_dir2,
                                                  delete=False, suffix='.tmp') as _tmp2:
                        _tmp2.writelines(_new_lines)
                        _tmp2_name = _tmp2.name
                    _ose2.replace(_tmp2_name, output_file)
                return

            # In Arena:  enemy = DEFENDER -> defend_commander, UID 151 (dom), UIDs 101-110 (cards)
            # In Brawl:  enemy = ATTACKER -> attack_commander, UID  51 (dom), UIDs   1-10  (cards)
            if brawl_mode:
                enemy_commander_id  = battle_data.get('attack_commander', '0')
                enemy_dominion_uid  = '51'
                uid_range           = range(1, 11)
                enemy_deck_dict     = battle_data.get('attack_deck', {})
            else:
                enemy_commander_id  = battle_data.get('defend_commander', '0')
                enemy_dominion_uid  = '151'
                uid_range           = range(101, 111)
                enemy_deck_dict     = battle_data.get('defend_deck', {})


            # Translate commander
            try:
                commander_info = card_data.get(int(enemy_commander_id), {})
            except (ValueError, TypeError):
                commander_info = {}
            if isinstance(commander_info, dict):
                commander_name = commander_info.get('name', str(enemy_commander_id))
            elif isinstance(commander_info, str):
                commander_name = commander_info
            else:
                commander_name = str(enemy_commander_id)

            # Dominion
            enemy_dominion_id   = card_map.get(enemy_dominion_uid)
            enemy_dominion_name = None
            if enemy_dominion_id:
                try:
                    dom_info = card_data.get(int(enemy_dominion_id), {})
                except (ValueError, TypeError):
                    dom_info = {}
                if isinstance(dom_info, dict):
                    enemy_dominion_name = dom_info.get('name', str(enemy_dominion_id))
                elif isinstance(dom_info, str):
                    enemy_dominion_name = dom_info

            # Enemy cards: prefer full deck dict over card_map (card_map only has revealed cards)
            defender_cards = []
            # Build a UID->card_id map from the deck dict if available
            deck_uid_map = {}
            if isinstance(enemy_deck_dict, dict):
                for k, v in enemy_deck_dict.items():
                    try:
                        deck_uid_map[int(k)] = v
                    except (ValueError, TypeError):
                        pass

            if deck_uid_map:
                # Use full deck from battle_data (all cards, not just revealed)
                for uid in sorted(deck_uid_map.keys()):
                    card_id = deck_uid_map[uid]
                    try:
                        card_info = card_data.get(int(card_id), {})
                    except (ValueError, TypeError):
                        card_info = {}
                    if isinstance(card_info, dict):
                        card_name = card_info.get('name', str(card_id))
                    elif isinstance(card_info, str):
                        card_name = card_info
                    else:
                        card_name = str(card_id)
                    defender_cards.append(card_name)
            else:
                # Fallback: only revealed cards from card_map
                for uid in uid_range:
                    uid_str = str(uid)
                    if uid_str in card_map:
                        card_id = card_map[uid_str]
                        try:
                            card_info = card_data.get(int(card_id), {})
                        except (ValueError, TypeError):
                            card_info = {}
                        if isinstance(card_info, dict):
                            card_name = card_info.get('name', str(card_id))
                        elif isinstance(card_info, str):
                            card_name = card_info
                        else:
                            card_name = str(card_id)
                        defender_cards.append(card_name)
            
            # ── 2/3 visibility check ─────────────────────────────────
            # 'eds' = enemy deck size (cards only, excl. commander+dominion).
            # Confirmed valid in both Arena and Brawl via API inspection.
            visible = len(defender_cards)
            eds = battle_data.get('eds', 0)
            try:
                eds = int(eds)
            except (ValueError, TypeError):
                eds = 0
            if eds > 0 and visible < (eds * 2 / 3):
                if not silent:
                    print(f"\n⚠ Only {visible}/{eds} enemy cards visible (<2/3) – skipping gauntlet export")
                return

            # Build deck string: Commander, [Dominion,] Card1, Card2, ...
            deck_str = commander_name

            # Add Dominion if present
            if enemy_dominion_name:
                deck_str += f", {enemy_dominion_name}"
            
            # Add cards
            for card_name in defender_cards:
                deck_str += f", {card_name}"
            
            from datetime import datetime as _dt
            timestamp = _dt.now().strftime("%Y-%m-%d %H:%M")
            comment_line = f"//Last seen on: {timestamp}\n"
            new_line = f"{prefix}_{entry_key}: {deck_str}\n"
            
            with _GAUNTLET_LOCK:
              # re-check file_exists inside lock (another process may have created it)
              file_exists = os.path.exists(output_file)
              if not file_exists:
                # New file: write header + entry
                with open(output_file, 'w', encoding='utf-8') as f:
                    f.write(f"WIN: /^WIN_.*$/\n")
                    f.write(f"LOSS: /LOSS_.*$/\n\n")
                    f.write(comment_line)
                    f.write(new_line)
                if not silent:
                    print(f"\n💾 Known cards: {visible}/{eds}  │  Opponent deck exported to: {output_file}")
              else:
                # Existing file: check if WIN_key or LOSS_key already exists
                with open(output_file, 'r', encoding='utf-8') as f:
                    lines = f.readlines()
                
                # Search for existing entry for this player.
                # Match by player name regardless of guild suffix:
                #   WIN_PlayerName:          (no guild)
                #   WIN_PlayerName_Guild:    (with guild)
                # Also accept if only the WIN/LOSS prefix differs.
                # Strategy: if no guild in new entry but existing line has one -> keep existing guild.
                # Skip export if a GUILD_ entry already exists for this player
                # (GUILD entries come from sync and are more reliable than battle observations)
                _has_guild = any(
                    l.lower().startswith(f"guild_{enemy_name.lower()}_") or
                    l.lower().startswith(f"guild_{enemy_name.lower()}:")
                    for l in lines
                )
                if _has_guild:
                    if not silent:
                        print(f"  ↷ Export skipped – GUILD entry exists for {enemy_name}")
                    return

                replaced = False
                for i, line in enumerate(lines):
                    for pfx in ("WIN_", "LOSS_"):
                        if not line.startswith(pfx):
                            continue
                        rest = line[len(pfx):]           # "PlayerName_Guild: deck\n"
                        # Extract key part (before first ': ')
                        colon_pos = rest.find(': ')
                        if colon_pos < 0:
                            continue
                        existing_key_part = rest[:colon_pos]  # "PlayerName_Guild" or "PlayerName"
                        # Normalize: strip guild suffix for comparison
                        existing_name = existing_key_part.split('_')[0] if '_' in existing_key_part else existing_key_part
                        if existing_name != enemy_name:
                            # Try full prefix match in case name itself contains underscores
                            if not existing_key_part.startswith(enemy_name):
                                continue
                        # Matched. If new entry has no guild but existing one does, keep existing guild.
                        if not enemy_guild and '_' in existing_key_part:
                            # Preserve the guild from the existing entry
                            preserved_guild = existing_key_part[len(enemy_name)+1:]  # strip "Name_"
                            new_line_write = f"{prefix}_{enemy_name}_{preserved_guild}: {deck_str}\n"
                        else:
                            new_line_write = new_line
                        old_prefix = pfx.rstrip('_')
                        lines[i] = new_line_write
                        if i > 0 and lines[i-1].startswith("//Last seen on:"):
                            lines[i-1] = comment_line
                        else:
                            lines.insert(i, comment_line)
                        replaced = True
                        if not silent:
                            if old_prefix != prefix:
                                print(f"\n💾 Known cards: {visible}/{eds}  │  {existing_key_part}: {old_prefix} -> {prefix} (updated)")
                            else:
                                print(f"\n💾 Known cards: {visible}/{eds}  │  {existing_key_part}: deck updated")
                        break
                    if replaced:
                        break
                
                if not replaced:
                    lines.append(comment_line)
                    lines.append(new_line)
                    if not silent:
                        print(f"\n💾 Known cards: {visible}/{eds}  │  Opponent deck exported to: {output_file}")

                # Trim WIN_/LOSS_ entries per guild to max 50
                lines, _trimmed = self._trim_win_loss_per_guild(lines, max_per_guild=50)
                if _trimmed and not silent:
                    print(f"  🗑  Trimmed {_trimmed} oldest WIN_/LOSS_ entries (guild cap 50)")

                import tempfile as _tf4, os as _os4
                _dir4 = os.path.dirname(output_file)
                with _tf4.NamedTemporaryFile('w', encoding='utf-8', dir=_dir4, delete=False, suffix='.tmp') as _tmp4:
                    _tmp4.writelines(lines)
                    _tmp4_name = _tmp4.name
                _os4.replace(_tmp4_name, output_file)
            
        except Exception as e:
            if not silent:
                print(f"\n⚠ Failed to export opponent deck: {e}")
    

    # ==================== GAUNTLET MANAGEMENT ====================

    def _trim_win_loss_per_guild(self, lines, max_per_guild=50):
        """
        Limit WIN_/LOSS_ entries per guild to max_per_guild, removing oldest first.
        Guild is determined by the suffix after the player name in the key
        (e.g. WIN_Player_Russia → guild = Russia).
        For guildless entries (WIN_Player) they share a virtual guild bucket ''.
        Returns (new_lines, removed_count).
        """
        from datetime import datetime as _dt

        # Parse all WIN_/LOSS_ entries with position and timestamp
        wl_entries = []  # (line_idx, comment_idx_or_None, guild, ts)
        i = 0
        while i < len(lines):
            s = lines[i].strip()
            ts = None
            comment_idx = None
            if s.startswith('//Last seen on:'):
                try:
                    ts = _dt.strptime(s[len('//Last seen on:'):].strip(), '%Y-%m-%d %H:%M')
                except ValueError:
                    pass
                if i+1 < len(lines):
                    nxt = lines[i+1].strip()
                    if nxt.startswith(('WIN_', 'LOSS_')) and ': ' in nxt:
                        comment_idx = i
                        i += 1
                        s = lines[i].strip()
            if s.startswith(('WIN_', 'LOSS_')) and ': ' in s:
                pfx = 'WIN_' if s.startswith('WIN_') else 'LOSS_'
                inner = s.split(': ')[0][len(pfx):]
                # Extract guild: last underscore-delimited segment if present
                # Guildless entries use the full inner key as bucket (not shared '')
                parts = inner.split('_')
                guild = parts[-1] if len(parts) > 1 else inner  # own bucket per guildless player
                wl_entries.append((i, comment_idx, guild, ts))
            i += 1

        # Group by guild, sort by ts (oldest first)
        from collections import defaultdict
        by_guild = defaultdict(list)
        for entry in wl_entries:
            by_guild[entry[2]].append(entry)

        to_remove = set()
        removed = 0
        for guild, entries in by_guild.items():
            if len(entries) <= max_per_guild:
                continue
            # Sort oldest first, mark excess for removal
            entries.sort(key=lambda e: e[3] or _dt.min)
            for line_idx, comment_idx, _, _ in entries[:len(entries) - max_per_guild]:
                to_remove.add(line_idx)
                if comment_idx is not None:
                    to_remove.add(comment_idx)
                removed += 1

        if not to_remove:
            return lines, 0
        return [line for i, line in enumerate(lines) if i not in to_remove], removed

    def clear_old_gauntlet_entries(self, days=7):
        """Remove arenagauntlet.txt entries older than `days` days (based on //Last seen on: comments)."""
        from datetime import datetime as _dt, timedelta as _td

        gauntlet_file = os.path.join(SCRIPT_DIR, 'arenagauntlet.txt')
        if not os.path.isfile(gauntlet_file):
            print("  ✗ arenagauntlet.txt not found")
            return

        with open(gauntlet_file, 'r', encoding='utf-8') as f:
            lines = f.readlines()

        cutoff = _dt.now() - _td(days=days)
        kept = []
        removed = 0
        i = 0
        while i < len(lines):
            line = lines[i]
            # Comment line followed by an entry line
            if line.strip().startswith('//Last seen on:'):
                try:
                    ts_str = line.strip().replace('//Last seen on:', '').strip()
                    ts = _dt.strptime(ts_str, '%Y-%m-%d %H:%M')
                    if ts < cutoff:
                        # Skip this comment and the entry line after it
                        i += 1  # skip entry line
                        removed += 1
                        i += 1
                        continue
                except ValueError:
                    pass  # malformed date -> keep
            kept.append(line)
            i += 1

        if removed == 0:
            print(f"  ✓ No entries older than {days} days found")
            return

        with _GAUNTLET_LOCK:
            import tempfile as _tf3, os as _os3
            _dir3 = os.path.dirname(gauntlet_file)
            with _tf3.NamedTemporaryFile('w', encoding='utf-8', dir=_dir3, delete=False, suffix='.tmp') as _tmp3:
                _tmp3.writelines(kept)
                _tmp3_name = _tmp3.name
            _os3.replace(_tmp3_name, gauntlet_file)
        print(f"  ✓ Removed {removed} entries older than {days} days from arenagauntlet.txt")

    # ==================== DECK OPTIMIZATION ====================

    def optimize_deck_vs_guild(self):
        """Optimize own attack deck vs own guild defense decks via TUO anneal.
        Fixed settings: anneal, keep-commander, dom-owned.
        User chooses: deck slot, BGE (optional), ordered or flexible.
        """
        import subprocess

        print("\n" + "="*65)
        print("  DECK OPTIMIZATION vs GUILD DEFENSE")
        print("="*65)

        if not self._tuo_available():
            input("\n[ENTER] to continue...")
            return

        # ── Init ────────────────────────────────────────────────────
        self.initialize(verbose=False)
        card_data = self._load_card_data_with_rarity()
        if not card_data:
            print("✗ Card data unavailable")
            return

        # ── Deck slot selection (full display) ──────────────────────
        user_decks = self.init_data.get('user_decks', {})
        deck_slots = {str(k): v for k, v in user_decks.items()
                      if isinstance(v, dict) and 'commander_id' in v}
        if not deck_slots:
            print("✗ No decks found in account")
            return

        active_deck = str(self.init_data.get('user_data', {}).get('active_deck', ''))

        print("\nDeck slot:")
        for slot, dk in sorted(deck_slots.items(), key=lambda x: int(x[0])):
            cmd_id  = dk.get('commander_id', 0)
            dom_id  = dk.get('dominion_id')
            cmd_info = card_data.get(int(cmd_id), {})
            cmd_name = cmd_info.get('name', str(cmd_id)) if isinstance(cmd_info, dict) else str(cmd_id)
            if cmd_name.endswith('-6'):
                cmd_name = cmd_name[:-2]

            dom_str = ''
            if dom_id and str(dom_id) not in ('0', 'None', ''):
                di = card_data.get(int(dom_id), {})
                dn = di.get('name', '') if isinstance(di, dict) else ''
                if dn.endswith('-6'):
                    dn = dn[:-2]
                if dn:
                    dom_str = f"  [{dn}]"

            cards_raw = dk.get('cards', {})
            card_names = []
            if isinstance(cards_raw, dict):
                for cid, cnt in cards_raw.items():
                    ci = card_data.get(int(cid), {})
                    cn = ci.get('name', str(cid)) if isinstance(ci, dict) else str(cid)
                    if cn.endswith('-6'):
                        cn = cn[:-2]
                    n = int(cnt)
                    card_names.append(f"{cn} x{n}" if n > 1 else cn)

            marker = " [A]" if slot == active_deck else "    "
            print(f"  {slot}.{marker} {cmd_name}{dom_str}")
            print(f"         {', '.join(card_names[:5])}{'...' if len(card_names) > 5 else ''}")

        print("─"*65)
        slot_in = input_with_esc("Slot (ESC=Cancel): ")
        if slot_in is None:
            return
        slot_in = slot_in.strip()
        if slot_in not in deck_slots:
            print("✗ Invalid slot")
            return

        dk = deck_slots[slot_in]
        _cards_raw = dk.get('cards', {})
        _cards_expanded = []
        if isinstance(_cards_raw, dict):
            for _cid, _cnt in _cards_raw.items():
                _cards_expanded.extend([_cid] * int(_cnt))
        else:
            _cards_expanded = list(_cards_raw)
        my_deck_str = self._build_tuo_deck_string(
            dk.get('commander_id'), dk.get('dominion_id'),
            _cards_expanded, card_data)
        if not my_deck_str:
            print("✗ Could not build deck string")
            return
        print(f"  -> {my_deck_str[:80]}{'...' if len(my_deck_str) > 80 else ''}")

        # ── GUILD_ entries – only own guild members ──────────────────
        gauntlet_file = os.path.join(SCRIPT_DIR, 'arenagauntlet.txt')
        if not os.path.isfile(gauntlet_file):
            print("✗ arenagauntlet.txt not found")
            return

        with open(gauntlet_file, 'r', encoding='utf-8') as f:
            gauntlet_lines = f.readlines()

        # Determine own guild name from faction data
        own_guild = ''
        faction = self.init_data.get('faction', {}) or {}
        if faction:
            own_guild = faction.get('name', '')

        # Filter: only GUILD_ entries matching own guild suffix (GUILD_name_GUILD)
        guild_entries = []
        for line in gauntlet_lines:
            stripped = line.strip()
            if not stripped.startswith('GUILD_') or ':' not in stripped:
                continue
            # Entry format: GUILD_PlayerName_GuildName: deck
            entry_key = stripped.split(': ')[0].strip()  # e.g. GUILD_Foo_MyGuild  (": " avoids splitting on names like :Ghost:)
            if own_guild:
                # Match entries ending with _<own_guild>
                suffix = f"_{own_guild}"
                if entry_key.endswith(suffix):
                    guild_entries.append(stripped)
            else:
                guild_entries.append(stripped)

        if not guild_entries:
            # Fallback: all GUILD_ entries
            guild_entries = [l.strip() for l in gauntlet_lines
                             if l.strip().startswith('GUILD_') and ':' in l.strip()]
            if guild_entries:
                print(f"  ⚠ Could not determine own guild – using all {len(guild_entries)} GUILD_ entries")
            else:
                print("✗ No GUILD_ entries in arenagauntlet.txt (run option 10 first)")
                return
        else:
            print(f"  Guild: {own_guild}  ->  {len(guild_entries)} defense deck(s)")

        # Write guild decks to data/customdecks_guild_opt.txt in TUO data dir.
        # TUO loads this automatically when '_guild_opt' is passed as suffix argument.
        tuo_data_dir = os.path.join(self._tuo_dir, 'data')
        os.makedirs(tuo_data_dir, exist_ok=True)
        customdecks_tmp = os.path.join(tuo_data_dir, 'customdecks_guild_opt.txt')
        with open(customdecks_tmp, 'w', encoding='utf-8') as _gtf:
            _gtf.write('// Auto-generated by TyrantAPICommander – guild defense decks\n\n')
            _gtf.write('GUILD_ALL: /^GUILD_.*$/\n\n')
            for gl in guild_entries:
                name_part, deck_part = gl.split(':', 1)
                _gtf.write(f"{name_part.strip()}: {deck_part.strip()}\n")

        # ── Owned cards file ─────────────────────────────────────────
        # TUO expects: -o=data/ownedcards/ownedcards_<n>.txt  (relative to _tuo_dir)
        # We look in <tuo_dir>/data/ownedcards/ first, then fall back to SCRIPT_DIR/ownedcards/.
        account_name = self.api.settings.get('request_data', {}).get('kong_name', '')                       or self.init_data.get('user_data', {}).get('name', 'unknown')
        safe_name = "".join(c if c.isalnum() or c in ('-', '_') else '_' for c in account_name)
        owned_fname = f"{safe_name}.txt"
        owned_in_tuo  = os.path.join(self._tuo_dir, 'data', 'ownedcards', owned_fname)
        owned_in_script = os.path.join(SCRIPT_DIR, 'ownedcards', owned_fname)
        if os.path.isfile(owned_in_tuo):
            owned_flag = f'-o=data/ownedcards/{owned_fname}'
            use_owned = True
            print(f"  Inventory: data/ownedcards/{owned_fname}")
        elif os.path.isfile(owned_in_script):
            # Pass absolute path – TUO prepends prefix='' so absolute works fine
            owned_flag = f'-o={owned_in_script}'
            use_owned = True
            print(f"  Inventory: {owned_fname} (from script dir)")
        else:
            owned_flag = None
            use_owned = False
            print(f"  ⚠ {owned_fname} not found – optimizing without inventory filter")

        # ── BGE (optional) ───────────────────────────────────────────
        bge_in = input_with_esc("BGE (optional, Enter=none, ESC=Cancel): ", allow_empty=True)
        if bge_in is None:
            os.unlink(gauntlet_tmp)
            return
        bge_in = bge_in.strip()

        # Fixed: random order (optimal for anneal)
        oflags = ['random']
        mode_label = 'random'

        # ── Build TUO command ─────────────────────────────────────────
        # Fixed: anneal 1000, keep-commander, dom-owned
        algo_args = ['anneal', '500', '100', '0.001']

        # 'GUILD_ALL' = regex group defined in customdecks_guild_opt.txt
        # '_guild_opt' = suffix argument: TUO auto-loads data/customdecks_guild_opt.txt
        cmd = ([self._tuo_path, my_deck_str, 'GUILD_ALL',
                'surge', 'no-db', 'no-ml', '_guild_opt']
               + oflags
               + ['keep-commander', 'dom-owned'])
        if use_owned and owned_flag:
            cmd += [owned_flag]
        if bge_in:
            tuo_bge = self._api_bge_to_tuo(bge_in)
            cmd += ['-e', tuo_bge]
        cmd += ['-t', str(self.tuo_threads)]
        cmd += algo_args

        print(f"\n⏳ Running TUO anneal ({mode_label}) vs {len(guild_entries)} guild defense decks...")
        print(f"   customdecks_guild_opt.txt written ({len(guild_entries)} decks)")
        print(f"   {' '.join(cmd[:7])}...\n")

        try:
            proc = subprocess.run(cmd, capture_output=True, text=True, timeout=900, cwd=self._tuo_dir)
            output = proc.stdout + proc.stderr
            print(output)
        except subprocess.TimeoutExpired:
            print("⚠ TUO timed out after 15 minutes")
            return
        except Exception as e:
            print(f"✗ TUO error: {e}")
            return
        finally:
            try:
                os.unlink(customdecks_tmp)
            except Exception:
                pass

        # ── Parse optimized deck from TUO output ─────────────────────
        import re as _re2
        opt_m = _re2.search(r'Optimized Deck:.*?:\s*[\d.]+:\s*(.+)', output)
        if not opt_m:
            print("\n⚠ Could not parse optimized deck from TUO output")
            return

        opt_deck_str = opt_m.group(1).strip()
        opt_cards = [_re2.sub(r'\s*#\d+$', '', c).strip() for c in opt_deck_str.split(',')]

        # Build name->id lookup
        name_to_id = {}
        name_to_id_lower = {}
        for _cid2, _cinfo2 in card_data.items():
            _cname2 = _cinfo2.get('name', '') if isinstance(_cinfo2, dict) else str(_cinfo2)
            if _cname2:
                name_to_id[_cname2] = _cid2
                name_to_id_lower[_cname2.lower()] = _cid2

        def _resolve_name(n):
            return (str(name_to_id[n]) if n in name_to_id
                    else str(name_to_id_lower[n.lower()]) if n.lower() in name_to_id_lower
                    else None)

        resolved_cmd_id = _resolve_name(opt_cards[0]) if opt_cards else str(dk.get('commander_id', '0'))
        if resolved_cmd_id is None:
            print(f"  ✗ Commander not found: '{opt_cards[0]}'")
            resolved_cmd_id = str(dk.get('commander_id', '0'))

        # Detect dominion in position [1] from known user dominions
        _known_dom_names = set()
        _known_dom_name_to_id = {}
        for _ds in self.init_data.get('user_decks', {}).values():
            _did = _ds.get('dominion_id') if isinstance(_ds, dict) else None
            if _did and str(_did) not in ('0', 'None', ''):
                _di = card_data.get(int(_did), {})
                _dn = _di.get('name', '') if isinstance(_di, dict) else ''
                if _dn:
                    _known_dom_names.add(_dn.lower())
                    _known_dom_name_to_id[_dn.lower()] = str(_did)

        resolved_dom_id = '0'
        card_start = 1
        if len(opt_cards) > 1:
            _pos1_lower = opt_cards[1].lower()
            if _pos1_lower in _known_dom_names:
                resolved_dom_id = _known_dom_name_to_id.get(_pos1_lower, '0')
                card_start = 2

        card_names_opt = opt_cards[card_start:]
        print(f"\n✓ Optimized deck:")
        print(f"  Commander: {opt_cards[0]}")
        if resolved_dom_id != '0' and card_start == 2:
            print(f"  Dominion:  {opt_cards[1]}")
        print(f"  Cards ({len(card_names_opt)}): {', '.join(card_names_opt)}")

        save_in = input_with_esc(f"\nWrite to deck slot? (1-6, Enter=slot {slot_in}, ESC=skip): ", allow_empty=True)
        if save_in is None:
            return
        target_slot = save_in.strip() if save_in.strip() else slot_in
        if target_slot not in user_decks:
            print(f"✗ Slot {target_slot} not found")
            return

        card_ids_opt = []
        ok = True
        for cn in card_names_opt:
            _rid = _resolve_name(cn)
            if _rid:
                card_ids_opt.append(_rid)
            else:
                print(f"  ✗ Card not found: '{cn}'")
                ok = False
        if not ok:
            print("✗ Could not resolve all card names – deck not saved")
            return

        from collections import Counter
        import json as _json2
        cards_dict = {cid: str(cnt) for cid, cnt in Counter(card_ids_opt).items()}
        cards_json = _json2.dumps(cards_dict)

        print(f"\n⏳ Saving optimized deck to slot {target_slot}...")
        result = self.api.call('setDeckCards',
                               deck_id=target_slot,
                               commander_id=str(resolved_cmd_id),
                               dominion_id=str(resolved_dom_id),
                               cards=cards_json,
                               activeYN='0')
        if result and result.get('result') in (True, 1, '1', 'true'):
            print(f"✓ Optimized deck saved to slot {target_slot}")
            self.initialize(verbose=False)
        else:
            print("✗ Failed to save deck")
            self._print_api_error(result, 'setDeckCards')
    # ==================== MULTI-ACCOUNT LIVE SIM ====================

    def energy_tracker_loop(self):
        """
        Runs in the background alongside multi_account_combined (or standalone).
        Every 60 minutes: fetches Brawl/Mission/Arena energy for all play_enabled
        accounts, compares to the previous snapshot, and logs a summary table to
        data/energy_log_YYYYMMDD.txt.
        """
        import glob as _glob, json as _json, threading as _threading

        LOG_DIR     = os.path.join(SCRIPT_DIR, 'energylog')
        os.makedirs(LOG_DIR, exist_ok=True)
        LOG_FILE    = os.path.join(LOG_DIR, f"energy_log_{time.strftime('%Y%m%d')}.txt")
        INTERVAL    = 3600   # seconds between snapshots

        _settings_dirs = [SCRIPT_DIR, os.path.join(SCRIPT_DIR, 'settings')]
        settings_files = []
        for _sd in _settings_dirs:
            settings_files += _glob.glob(os.path.join(_sd, 'settings_*.json'))
        settings_files = [f for f in settings_files
                          if not os.path.basename(f).startswith('settings_TEMPLATE')]
        settings_files = sorted({os.path.normpath(f): f for f in settings_files}.values())

        playable = []
        for sf in settings_files:
            nick = os.path.basename(sf).replace('settings_', '').replace('.json', '')
            try:
                with open(sf, 'r', encoding='utf-8') as fh:
                    cfg = _json.load(fh)
                if cfg.get('play_enabled', True):
                    playable.append((nick, sf))
            except Exception:
                pass

        if not playable:
            return

        def _fetch_snapshot():
            """Returns (snap_dict, event_label) where event_label is 'Brawl', 'Raid', etc."""
            snap = {}
            event_label = None   # set from first successful account; None = no active event
            event_detected = False
            total = len(playable)
            for idx, (nick, sf) in enumerate(playable, 1):
                print(f"\r  ⏳ [{idx}/{total}]  {nick:<20}", end='', flush=True)
                try:
                    tmp = TyrantCommander(sf)
                    if not tmp.initialize(verbose=False):
                        snap[nick] = None
                        continue
                    ud = tmp.init_data.get('user_data', {})
                    if not isinstance(ud, dict): ud = {}

                    # ── Detect active event type (first successful account sets label) ──
                    if not event_detected:
                        import time as _time2
                        _now = int(_time2.time())
                        # Raid active? Check raid_info for entries with remaining health
                        _ri_map = tmp.init_data.get('raid_info') or {}
                        if not isinstance(_ri_map, dict): _ri_map = {}
                        _raid_active = False
                        for _rid, _rdata in _ri_map.items():
                            if not isinstance(_rdata, dict): continue
                            _re = _rdata.get('energy', {})
                            if not isinstance(_re, dict): _re = {}
                            _rstop = int(_re.get('battle_energy_recharge_stop_time', 0))
                            if _rstop > _now:
                                _raid_active = True
                                break
                        # Guild War active?
                        _fw = tmp.init_data.get('faction_war', {}) or {}
                        _awe = tmp.init_data.get('active_war_event', {}) or {}
                        _gw_energy = int(_fw.get('battle_energy', 0)) if isinstance(_fw, dict) else 0
                        _gw_active = bool(_awe and isinstance(_fw, dict) and _fw.get('battle_energy') is not None)
                        # Brawl active (end_time in future, not a guild brawl)?
                        _brawl = tmp.init_data.get('active_brawl_data', {}) or {}
                        if not isinstance(_brawl, dict): _brawl = {}
                        _brawl_end  = int(_brawl.get('end_time', 0))
                        _brawl_name = _brawl.get('name', '')
                        _is_guild_brawl = any(w in _brawl_name.lower() for w in ('guild', 'guildbrawl'))
                        _brawl_live = _brawl_end > _now and not _is_guild_brawl
                        if _raid_active:
                            event_label = 'Raid'
                            event_detected = True
                        elif _gw_active:
                            event_label = (_awe.get('name', 'Guild War') if isinstance(_awe, dict) else 'Guild War')
                            event_detected = True
                        elif _brawl_live:
                            event_label = _brawl_name or 'Brawl'
                            event_detected = True
                        # else: no active event — don't set event_detected

                    # ── Event energy ──
                    _fw2 = tmp.init_data.get('faction_war', {}) or {}
                    _awe2 = tmp.init_data.get('active_war_event', {}) or {}
                    _gw_active2 = bool(_awe2 and isinstance(_fw2, dict) and _fw2.get('battle_energy') is not None)
                    pbd = tmp.init_data.get('player_brawl_data', {})
                    if not isinstance(pbd, dict): pbd = {}
                    _pbd_energy = pbd.get('energy', {})
                    if not isinstance(_pbd_energy, dict): _pbd_energy = {}
                    if _gw_active2:
                        # GW: read energy from faction_war
                        be_raw = int(_fw2.get('battle_energy', 0))
                        max_event = int(_fw2.get('max_battle_energy', 20))
                    else:
                        be_raw = _pbd_energy.get('battle_energy')
                        if be_raw is None:
                            be_raw = ud.get('battle_energy', 0)

                    # If Raid is active, read raid energy from raid_info in init_data
                    if not _gw_active2:
                        max_event = 25
                    if event_label == 'Raid':
                        try:
                            _ri_map = tmp.init_data.get('raid_info') or {}
                            if not isinstance(_ri_map, dict): _ri_map = {}
                            if not _ri_map:
                                # fallback: explicit getRaidInfo call
                                _ri_result = tmp.api.call('getRaidInfo')
                                _ri_map = (_ri_result or {}).get('raid_info', {})
                                if not isinstance(_ri_map, dict): _ri_map = {}
                            for _rid, _rdata in _ri_map.items():
                                if not isinstance(_rdata, dict): continue
                                _re = _rdata.get('energy', {})
                                if isinstance(_re, dict) and 'battle_energy' in _re:
                                    be_raw = int(_re['battle_energy'])
                                    break
                        except Exception:
                            pass

                    # ── Max energy values ──
                    max_mission = (int(ud.get('max_energy',  0))
                                   or int(tmp.init_data.get('max_energy',  0))
                                   or 156)
                    max_arena   = (int(ud.get('max_stamina', 0))
                                   or int(tmp.init_data.get('max_stamina', 0))
                                   or 15)
                    snap[nick] = {
                        'event':       int(be_raw or 0),
                        'mission':     int(ud.get('energy',  0)),
                        'arena':       int(ud.get('stamina', 0)),
                        'max_event':   max_event,
                        'max_mission': max_mission,
                        'max_arena':   max_arena,
                        'skip_event':  bool(
                            (_gw_active2 and tmp.api.settings.get('skip_guildwar')) or
                            (not _gw_active2 and _brawl_live and tmp.api.settings.get('skip_brawl'))
                        ),
                    }
                except Exception as _e:
                    snap[nick] = None
                    print(f"\r  ✗ {nick}: {_e}{' '*30}")
            ok = sum(1 for v in snap.values() if v is not None)
            print(f"\r  ✓ {ok}/{total} account(s) fetched{' '*30}")
            return snap, event_label

        def _pct(val, mx):
            if mx and mx > 0:
                return int(val * 100 / mx)
            return 0

        def _write_log(ts_label, prev, curr, event_label):
            _max_ev = next((v['max_event'] for v in curr.values() if v and 'max_event' in v), 25)
            ev_hdr = f"{event_label} /{_max_ev}" if event_label else None
            # Header
            lines = [
                f"\n{'='*90}",
                f"  ENERGY SNAPSHOT  {ts_label}  [{event_label or 'No Event'}]",
                f"{'='*90}",
            ]
            if ev_hdr:
                lines.append(f"  {'Account':<20}  {ev_hdr:>14}  {'Δ':>5}  {'Mission':>14}  {'Δ':>5}  {'Arena':>12}  {'Δ':>5}  {'!':>2}")
                lines.append(f"  {'─'*20}  {'─'*14}  {'─'*5}  {'─'*14}  {'─'*5}  {'─'*12}  {'─'*5}  {'─'*2}")
            else:
                lines.append(f"  {'Account':<20}  {'Mission':>14}  {'Δ':>5}  {'Arena':>12}  {'Δ':>5}  {'!':>2}")
                lines.append(f"  {'─'*20}  {'─'*14}  {'─'*5}  {'─'*12}  {'─'*5}  {'─'*2}")
            warnings = []
            for nick, _ in playable:
                c = curr.get(nick)
                p = prev.get(nick) if prev else None
                if c is None:
                    if ev_hdr:
                        lines.append(f"  {nick:<20}  {'–':>14}  {'–':>5}  {'–':>14}  {'–':>5}  {'–':>12}  {'–':>5}  {'–':>2}")
                    else:
                        lines.append(f"  {nick:<20}  {'–':>14}  {'–':>5}  {'–':>12}  {'–':>5}  {'–':>2}")
                    continue

                def _delta(key):
                    if p is None or p.get(key) is None:
                        return '–'
                    d = c[key] - p[key]
                    return f"{d:+d}"

                event_pct   = _pct(c['event'],   c['max_event'])
                mission_pct = _pct(c['mission'],  c['max_mission'])
                arena_pct   = _pct(c['arena'],    c['max_arena'])

                # Cap warnings (GW energy doesn't regenerate — skip event cap warning)
                caps_hit = []
                if not c.get('skip_event'):
                    if event_pct >= 100 and _max_ev != 20 and event_label: caps_hit.append(event_label)
                if mission_pct >= 100: caps_hit.append('Mission')
                if arena_pct   >= 100: caps_hit.append('Arena')
                warn_flag = '!!' if caps_hit else ''
                if caps_hit:
                    warnings.append(f"  !! {nick}: {', '.join(caps_hit)} at 100% cap")

                # Skipped accounts: show 'skipped' in event column, but still show mission/arena
                if c.get('skip_event') and ev_hdr:
                    event_str = 'skipped'
                else:
                    event_str = f"{c['event']}/{c['max_event']} ({event_pct}%)"
                mission_str = f"{c['mission']}/{c['max_mission']} ({mission_pct}%)"
                arena_str   = f"{c['arena']}/{c['max_arena']} ({arena_pct}%)"

                lines.append(
                    f"  {nick:<20}"
                    + (f"  {event_str:>14}  {_delta('event'):>5}" if ev_hdr else "")
                    + f"  {mission_str:>14}  {_delta('mission'):>5}"
                    + f"  {arena_str:>12}  {_delta('arena'):>5}"
                    f"  {warn_flag:>2}"
                )

            lines.append(f"  {'─'*20}  {'─'*12}  {'─'*5}  {'─'*14}  {'─'*5}  {'─'*12}  {'─'*5}  {'─'*2}")
            if warnings:
                lines.append(f"\n  WARNINGS - CAP AT 100%:")
                lines.extend(warnings)

            block = "\n".join(lines) + "\n"
            with open(LOG_FILE, 'a', encoding='utf-8') as f:
                f.write(block)
            print(block)

        print(f"\n  ⏱  Energy tracker started - logging every 60 min to {os.path.basename(LOG_FILE)}")

        prev_snap  = None
        prev_label = 'Event'
        try:
            while True:
                ts = time.strftime('%Y-%m-%d %H:%M')
                print(f"\n  ⏱  [{ts}] Fetching energy snapshot...")
                curr_snap, event_label = _fetch_snapshot()
                _write_log(ts, prev_snap, curr_snap, event_label)
                prev_snap  = curr_snap
                prev_label = event_label
                # Wait INTERVAL seconds, wake every 5s to allow KeyboardInterrupt
                for _ in range(INTERVAL // 5):
                    sleep(5)
        except KeyboardInterrupt:
            print("\n  ↩ Energy tracker stopped")

    def list_energy_all_accounts(self):
        """
        Lists Arena Energy and Mission Energy for all accounts with play_enabled=true,
        sorted by Arena Energy (highest first).
        """
        import glob as _glob, json as _json

        print(f"\n{'='*65}")
        print(f"  ENERGY OVERVIEW – ALL ACCOUNTS")
        print(f"{'='*65}")

        _settings_dirs = [SCRIPT_DIR, os.path.join(SCRIPT_DIR, 'settings')]
        settings_files = []
        for _sd in _settings_dirs:
            settings_files += _glob.glob(os.path.join(_sd, 'settings_*.json'))
        settings_files = [f for f in settings_files
                          if not os.path.basename(f).startswith('settings_TEMPLATE')]
        settings_files = sorted({os.path.normpath(f): f for f in settings_files}.values())

        if not settings_files:
            print("  ✗ No settings_*.json files found")
            return

        playable = []
        skipped  = []
        for sf in settings_files:
            nick = os.path.basename(sf).replace('settings_', '').replace('.json', '')
            try:
                with open(sf, 'r', encoding='utf-8') as fh:
                    cfg = _json.load(fh)
                if cfg.get('play_enabled', True):
                    playable.append((nick, sf))
                else:
                    skipped.append(nick)
            except Exception:
                skipped.append(nick)

        if skipped:
            print(f"  ⏭  Skipped (play_enabled=false): {', '.join(skipped)}")
        if not playable:
            print("  ✗ No eligible accounts found")
            return

        rows = []
        total = len(playable)
        for idx, (nick, sf) in enumerate(playable, 1):
            # Progress indicator – overwritten each iteration
            bar_filled = int(16 * idx / total)
            bar = '█' * bar_filled + '░' * (16 - bar_filled)
            print(f"\r  ⏳ [{bar}] {idx}/{total}  {nick:<20}", end='', flush=True)
            try:
                tmp = TyrantCommander(sf)
                if not tmp.initialize(verbose=False):
                    rows.append((nick, None, None, None, None, '✗ login failed'))
                    continue
                ud        = tmp.init_data.get('user_data', {})
                arena     = int(ud.get('stamina', 0))
                mission   = int(ud.get('energy',  0))
                max_arena   = int(tmp.init_data.get('max_stamina', 0)) or None
                max_mission = int(tmp.init_data.get('max_energy',  0)) or None
                rows.append((nick, arena, mission, max_arena, max_mission, None))
            except PleaseWaitError as e:
                rows.append((nick, None, None, None, None, 'API busy'))
            except Exception as e:
                rows.append((nick, None, None, None, None, str(e)[:40]))
            sleep(0.3)
        print(f"\r  ✓ {total} account(s) fetched{' '*30}")  # clear progress line

        # Sort by arena energy descending (None = errors go last)
        rows.sort(key=lambda r: r[1] if r[1] is not None else -1, reverse=True)

        def pct(val, mx):
            if val is None or not mx:
                return ''
            return f" ({val*100//mx:>3}%)"

        # Column widths
        name_w = max(len(r[0]) for r in rows)
        name_w = max(name_w, 7)

        print()
        print(f"  {'Account':<{name_w}}  {'Arena':>14}  {'Mission':>14}")
        print(f"  {'─'*name_w}  {'─'*14}  {'─'*14}")
        for nick, arena, mission, max_arena, max_mission, err in rows:
            if err:
                print(f"  {nick:<{name_w}}  {'–':>14}  {'–':>14}  ⚠ {err}")
            else:
                arena_str   = f"{arena:,}{pct(arena, max_arena)}"
                mission_str = f"{mission:,}{pct(mission, max_mission)}"
                print(f"  {nick:<{name_w}}  {arena_str:>14}  {mission_str:>14}")
        print(f"  {'─'*name_w}  {'─'*14}  {'─'*14}")
        print(f"{'='*65}")

    def claim_event_rewards_all_accounts(self):
        """
        Claims event rewards for all accounts that have play_enabled=true
        (same filter as multi-account arena/brawl).
        """
        import glob as _glob, json as _json

        print(f"\n{'='*65}")
        print(f"  CLAIM EVENT REWARDS – ALL ACCOUNTS")
        print(f"{'='*65}")

        _settings_dirs = [SCRIPT_DIR, os.path.join(SCRIPT_DIR, 'settings')]
        settings_files = []
        for _sd in _settings_dirs:
            settings_files += _glob.glob(os.path.join(_sd, 'settings_*.json'))
        settings_files = [f for f in settings_files
                          if not os.path.basename(f).startswith('settings_TEMPLATE')]
        settings_files = sorted({os.path.normpath(f): f for f in settings_files}.values())

        if not settings_files:
            print("  ✗ No settings_*.json files found")
            return

        # Filter to play_enabled accounts
        playable = []
        skipped  = []
        for sf in settings_files:
            nick = os.path.basename(sf).replace('settings_', '').replace('.json', '')
            try:
                with open(sf, 'r', encoding='utf-8') as fh:
                    cfg = _json.load(fh)
                if cfg.get('play_enabled', True):
                    playable.append((nick, sf))
                else:
                    skipped.append(nick)
            except Exception:
                skipped.append(nick)

        if skipped:
            print(f"  ⏭  Skipped (play_enabled=false): {', '.join(skipped)}")
        if not playable:
            print("  ✗ No eligible accounts found")
            return

        print(f"  Accounts: {', '.join(n for n, _ in playable)}\n")

        bar_width = 40
        total     = len(playable)
        ok = 0; failed = 0

        for idx, (nick, sf) in enumerate(playable, 1):
            filled = int(bar_width * (idx - 1) / total)
            bar    = '█' * filled + '░' * (bar_width - filled)
            print(f"  [{bar}] {nick}")

            try:
                tmp = TyrantCommander(sf)
                if not tmp.initialize(verbose=False):
                    print(f"    ✗ Login failed")
                    failed += 1
                    continue
                tmp.claim_event_rewards()
                ok += 1
            except PleaseWaitError as e:
                print(f"    ✗ API busy: {e}")
                failed += 1
            except Exception as e:
                print(f"    ✗ Error: {e}")
                failed += 1
            sleep(1)

        filled = bar_width
        bar    = '█' * filled
        print(f"  [{bar}] done")
        print(f"{'─'*65}")
        status = '✓' if not failed else '⚠'
        print(f"  {status}  {ok}/{total} accounts processed"
              + (f"  |  {failed} failed" if failed else ''))
        print(f"{'='*65}")

    def multi_account_live_sim(self, mode='arena'):
        """
        Runs live sim (arena or brawl) for all accounts with play_enabled=true.
        mode: 'arena' or 'brawl'
        """
        import glob as _glob, json as _json

        mode_label = "ARENA" if mode == 'arena' else ("BRAWL" if mode == 'brawl' else "GUILD WAR")
        print(f"\n{'='*65}")
        print(f"  MULTI-ACCOUNT LIVE SIM – {mode_label}")
        print(f"{'='*65}")

        _settings_dirs = [SCRIPT_DIR, os.path.join(SCRIPT_DIR, 'settings')]
        settings_files = []
        for _sd in _settings_dirs:
            settings_files += _glob.glob(os.path.join(_sd, 'settings_*.json'))
        settings_files = [f for f in settings_files
                          if not os.path.basename(f).startswith('settings_TEMPLATE')]
        settings_files = sorted({os.path.normpath(f): f for f in settings_files}.values())

        if not settings_files:
            print("  ✗ No settings_*.json files found")
            return

        # Filter to play_enabled accounts only
        playable = []
        skipped = []
        for sf in settings_files:
            nick = os.path.basename(sf).replace('settings_', '').replace('.json', '')
            try:
                with open(sf, 'r', encoding='utf-8') as fh:
                    cfg = _json.load(fh)
                # play_enabled defaults to True if not set
                enabled = cfg.get('play_enabled', True)
                if enabled:
                    playable.append((nick, sf))
                else:
                    skipped.append(nick)
            except Exception:
                skipped.append(nick)

        if skipped:
            print(f"  ⏭  Skipped (play_enabled=false): {', '.join(skipped)}")
        if not playable:
            print("  ✗ No playable accounts found")
            return

        print(f"  Accounts to run: {', '.join(n for n, _ in playable)}")

        # ── One-time setup prompts ────────────────────────────────────
        t_in = input_with_esc(f"TUO threads (-t), current={self.tuo_threads} (Enter=keep, ESC=Cancel): ", allow_empty=True)
        if t_in is None:
            return
        if t_in.strip():
            try:
                t_val = int(t_in.strip())
                if 1 <= t_val <= 128:
                    self.tuo_threads = t_val
                    print(f"  ✓ TUO threads set to {t_val}")
            except ValueError:
                pass

        # Multi-account always uses flexible (pre-sim/pre-battle stays ordered)
        self.tuo_order_mode = 'flexible'
        print(f"  ✓ Play mode: flexible (auto)")

        log_inp = input_with_esc("Combat log [y=yes / Enter=no]: ", allow_empty=True)
        if log_inp is None:
            return
        _ma_combat_log = log_inp.strip().lower().startswith('y')
        if _ma_combat_log:
            print("  ✓ Combat logs -> combatlog/<account>/")

        # ── Target selection mode (Arena only) ───────────────────────
        if mode == 'arena':
            print("\n  Target selection mode:")
            print("  [1]  Default  (known deck ≥30% -> unknown -> best known)")
            print("  [2]  Focus on unknown decks  (unknown first, then default)")
            _tm_inp = input_with_esc("  Selection (Enter=default): ", allow_empty=True)
            if _tm_inp is None:
                return
            _ma_focus_unknown = _tm_inp.strip() == '2'
            if _ma_focus_unknown:
                print("  ✓ Mode: Focus on unknown decks")
            else:
                print("  ✓ Mode: Default")
        else:
            _ma_focus_unknown = False

        # ── Account range / loop selection ───────────────────────────
        active_accounts, loop_mode = _select_account_range(playable, mode_label)
        if active_accounts is None:
            return

        all_stats = []  # (nick, stats_dict)
        _loop_count = 0
        while True:
            _loop_count += 1
            if loop_mode:
                print(f"\n{'═'*65}")
                print(f"  LOOP #{_loop_count}")
                print(f"{'═'*65}")
            for nick, sf in active_accounts:
                print(f"\n{'─'*65}")
                print(f"  ▶  Account: {nick}")
                print(f"{'─'*65}")

                _account_attempts  = 0
                _MAX_NET_RETRIES   = 3   # max network-recovery retries per account
                _net_retries       = 0
                while True:   # retry loop for network recovery
                    _account_attempts += 1
                    if _account_attempts > 1:
                        print(f"\n  🔄  Retrying {nick} (attempt {_account_attempts}/{_MAX_NET_RETRIES + 1})...")
                    try:
                        tmp_cmd = TyrantCommander(sf)
                        tmp_cmd.tuo_threads   = self.tuo_threads
                        tmp_cmd.tuo_order_mode = getattr(self, 'tuo_order_mode', 'ordered')
                        tmp_cmd.initialize(verbose=False)
                        active_slot = str(tmp_cmd.init_data.get('user_data', {}).get('active_deck', ''))
                        if active_slot:
                            print(f"  ✓ Using active deck slot {active_slot}")
                        else:
                            print("  ⚠ Could not determine active deck slot")
                        if mode == 'arena':
                            # ── Loyal Challenge deck adjustment ───────────────
                            _loyal_step, _, _loyal_table = tmp_cmd._detect_loyal_challenge_step()
                            _loyal_orig_ids = _loyal_orig_cmdr = None
                            if _loyal_step:
                                _loyal_cd = tmp_cmd._load_card_data_with_rarity() or {}
                                _loyal_orig_ids, _loyal_orig_cmdr = tmp_cmd._apply_loyal_deck_adjustments(_loyal_step, _loyal_cd, challenge_table=_loyal_table)
                                if _loyal_orig_ids:
                                    tmp_cmd.initialize(verbose=False)
                            try:
                                stats = tmp_cmd.live_sim_battle(skip_deck_select=True, combat_log=_ma_combat_log, focus_unknown=_ma_focus_unknown)
                            finally:
                                if _loyal_orig_ids:
                                    tmp_cmd._restore_loyal_deck(_loyal_orig_ids, _loyal_orig_cmdr)
                            # Restore original active deck if changed
                            if active_slot:
                                try:
                                    tmp_cmd.initialize(verbose=False)
                                    _slot_now = str(tmp_cmd.init_data.get('user_data', {}).get('active_deck', ''))
                                    if _slot_now and _slot_now != active_slot:
                                        tmp_cmd.api.call('setActiveDeck', deck_id=active_slot)
                                        print(f"  ↩  Restored active deck -> Slot {active_slot}")
                                except Exception:
                                    pass
                        elif mode == 'brawl':
                            if tmp_cmd.api.settings.get('skip_brawl'):
                                print(f"  ⏭  {nick}: skip_brawl=true — skipping")
                            else:
                                stats = tmp_cmd.live_sim_brawl(skip_deck_select=True, combat_log=_ma_combat_log)
                        else:  # gwar
                            if tmp_cmd.api.settings.get('skip_guildwar'):
                                print(f"  ⏭  {nick}: skip_guildwar=true — skipping")
                            else:
                                stats = tmp_cmd.live_sim_guildwar(skip_deck_select=True, combat_log=_ma_combat_log)
                        if stats:
                            all_stats.append((nick, stats))
                        break  # success -> next account

                    except PleaseWaitError as e:
                        print(f"  ⏭  {nick}: API busy ({e}) – skipping to next account")
                        break

                    except (URLError, OSError, ConnectionError, TimeoutError) as e:
                        _net_retries += 1
                        print(f"\n  ✗  {nick}: network error ({_net_retries}/{_MAX_NET_RETRIES}) – {type(e).__name__}: {e}")
                        if _net_retries > _MAX_NET_RETRIES:
                            print(f"  ✗  {nick}: max network retries reached – skipping to next account")
                            break
                        recovered = _wait_for_network()
                        if not recovered:
                            print(f"  ✗  {nick}: skipped (network did not recover in time)")
                            break

                    except Exception as e:
                        print(f"  ✗ Error on {nick}: {e}")
                        import traceback
                        traceback.print_exc()
                        break

            # ── End of one pass through accounts ─────────────────
            if not loop_mode:
                break
            try:
                print(f"\n  Loop {_loop_count} complete – press Ctrl+C to stop, or wait for next loop...")
                import time as _t; _t.sleep(2)
            except KeyboardInterrupt:
                print("\n  ↩ Loop stopped by user")
                break

        # ── Final summary across all accounts ──────────────────────
        if all_stats:
            print(f"\n{'═'*65}")
            print(f"  MULTI-ACCOUNT SUMMARY – {mode_label}")
            print(f"{'═'*65}")
            tot_w = tot_l = 0
            if mode == 'arena':
                tot_gold = tot_rating = tot_lp = 0
                for nick, s in all_stats:
                    w, l = s['wins'], s['losses']
                    tot_w += w; tot_l += l
                    tot_gold += s['gold']; tot_rating += s['rating']; tot_lp += s['lp']
                    t = w + l
                    wr = f"{w/t*100:.0f}%" if t else "–"
                    print(f"  {nick:<20}  {w}W/{l}L ({wr})  Gold {s['gold']:+,}  Rating {s['rating']:+d}  LP {s['lp']:+d}")
                print(f"{'─'*65}")
                tot_t = tot_w + tot_l
                tot_wr = f"{tot_w/tot_t*100:.0f}%" if tot_t else "–"
                print(f"  {'TOTAL':<20}  {tot_w}W/{tot_l}L ({tot_wr})  Gold {tot_gold:+,}  Rating {tot_rating:+d}  LP {tot_lp:+d}")
            else:
                # brawl or gwar
                tot_gold = tot_pts = 0
                for nick, s in all_stats:
                    w, l = s['wins'], s['losses']
                    tot_w += w; tot_l += l
                    gold = s.get('gold', 0); pts = s.get('points', 0)
                    tot_gold += gold; tot_pts += pts
                    t = w + l
                    wr = f"{w/t*100:.0f}%" if t else "–"
                    wasted = s.get('wasted', 0)
                    line = f"  {nick:<20}  {w}W/{l}L ({wr})"
                    if gold:  line += f"  Gold {gold:+,}"
                    if pts:   line += f"  Points {pts:+,}"
                    if wasted: line += f"  ⚠ {wasted} wasted"
                    print(line)
                print(f"{'─'*65}")
                tot_t = tot_w + tot_l
                tot_wr = f"{tot_w/tot_t*100:.0f}%" if tot_t else "–"
                line = f"  {'TOTAL':<20}  {tot_w}W/{tot_l}L ({tot_wr})"
                if tot_gold: line += f"  Gold {tot_gold:+,}"
                if tot_pts:  line += f"  Points {tot_pts:+,}"
                print(line)
            print(f"{'═'*65}")

        print(f"\n✓ Multi-account {mode_label} run complete")


    def multi_account_combined(self):
        """
        Combined multi-account loop: for each account runs in sequence:
          1. Brawl Live Sim (until battle_energy = 0)
          2. First Quest Mission loop (Deck 1, first available quest, until energy = 0)
          3. Arena Live Sim (focus unknown decks, until stamina = 0)
        No per-run logs - minimal output focused on unknowns.
        """
        import glob as _glob, json as _json

        print(f"\n{'='*65}")
        print(f"  MULTI-ACCOUNT: BRAWL + QUEST MISSION + ARENA")
        print(f"{'='*65}")

        if not self._tuo_available():
            print("✗ TUO not available")
            return

        # ── Load accounts ─────────────────────────────────────────────
        _settings_dirs = [SCRIPT_DIR, os.path.join(SCRIPT_DIR, 'settings')]
        settings_files = []
        for _sd in _settings_dirs:
            settings_files += _glob.glob(os.path.join(_sd, 'settings_*.json'))
        settings_files = [f for f in settings_files
                          if not os.path.basename(f).startswith('settings_TEMPLATE')]
        settings_files = sorted({os.path.normpath(f): f for f in settings_files}.values())

        if not settings_files:
            print("  ✗ No settings_*.json files found")
            return

        playable = []
        skipped  = []
        for sf in settings_files:
            nick = os.path.basename(sf).replace('settings_', '').replace('.json', '')
            try:
                with open(sf, 'r', encoding='utf-8') as fh:
                    cfg = _json.load(fh)
                if cfg.get('play_enabled', True):
                    playable.append((nick, sf))
                else:
                    skipped.append(nick)
            except Exception:
                skipped.append(nick)

        if skipped:
            print(f"  ⏭  Skipped (play_enabled=false): {', '.join(skipped)}")
        if not playable:
            print("  ✗ No playable accounts found")
            return

        # ── TUO threads prompt ────────────────────────────────────────
        t_in = input_with_esc(
            f"\n  TUO threads (-t), current={self.tuo_threads} (Enter=keep, ESC=Cancel): ",
            allow_empty=True)
        if t_in is None:
            return
        if t_in.strip():
            try:
                t_val = int(t_in.strip())
                if 1 <= t_val <= 128:
                    self.tuo_threads = t_val
                    print(f"  ✓ TUO threads set to {t_val}")
            except ValueError:
                pass

        # ── Account range / loop selection ────────────────────────────
        active_accounts, loop_mode = _select_account_range(playable, 'COMBINED')
        if active_accounts is None:
            return


        # ── Combat log prompt ─────────────────────────────────────────
        _cl_inp = input_with_esc("  Enable combat log? [N=no / b=Brawl only / a=Brawl+Arena]: ", allow_empty=True)
        _cl_val = _cl_inp.strip().lower() if _cl_inp else ''
        _ma_combat_log_brawl = _cl_val in ('b', 'a')
        _ma_combat_log_arena = _cl_val == 'a'
        if _ma_combat_log_arena:
            print("  ✓ Combat log enabled for Brawl + Arena")
        elif _ma_combat_log_brawl:
            print("  ✓ Combat log enabled for Brawl only")
        _loop_count = 0
        try:
            while True:
                _loop_count += 1
                if loop_mode:
                    print(f"\n{'═'*65}")
                    print(f"  LOOP #{_loop_count}")
                    print(f"{'═'*65}")

                for nick, sf in active_accounts:
                    print(f"\n{'─'*65}")
                    print(f"  ▶  {nick}")
                    print(f"{'─'*65}")

                    try:
                        tmp = TyrantCommander(sf)
                        tmp.tuo_threads    = self.tuo_threads
                        tmp.tuo_order_mode = 'flexible'   # flex sim for both Brawl and Arena
                        if not tmp.initialize(verbose=False):
                            print(f"  ✗ Login failed")
                            continue

                        # Save active deck BEFORE any phase modifies it
                        _active_deck_before = str(tmp.init_data.get('user_data', {}).get('active_deck', '1'))

                        # ── 0. DAILY REWARD ──────────────────────────
                        print(f"  [DAILY]")
                        tmp.auto_claim_daily_bonus()

                        # ── 1. BRAWL ─────────────────────────────────
                        if tmp.api.settings.get('skip_brawl'):
                            print(f"  [BRAWL]  skipped (skip_brawl=true)")
                        else:
                            be = int(tmp.init_data.get('user_data', {}).get('battle_energy', 0))
                            if be > 0:
                                print(f"\n  [BRAWL]")
                                tmp.live_sim_brawl(skip_deck_select=True, combat_log=_ma_combat_log_brawl)
                            else:
                                print(f"  [BRAWL]  skipped (battle_energy=0)")

                        # ── 2. QUEST MISSION ─────────────────────────
                        tmp.initialize(verbose=False)
                        energy = int(tmp.init_data.get('user_data', {}).get('energy', 0))
                        if energy > 0:
                            print(f"\n  [QUEST]")
                            tmp.play_first_quest_mission_loop()
                        else:
                            print(f"  [QUEST]  skipped (energy=0)")

                        # ── 3. ARENA ─────────────────────────────────
                        tmp.initialize(verbose=False)
                        stamina = int(tmp.init_data.get('user_data', {}).get('stamina', 0))
                        if stamina > 0:
                            print(f"\n  [ARENA]")
                            # Loyal Challenge deck adjustment
                            _loyal_step_x, _, _loyal_table_x = tmp._detect_loyal_challenge_step()
                            _loyal_orig_x = _loyal_cmdr_x = None
                            if _loyal_step_x:
                                _lcd_x = tmp._load_card_data_with_rarity() or {}
                                _loyal_orig_x, _loyal_cmdr_x = tmp._apply_loyal_deck_adjustments(_loyal_step_x, _lcd_x, challenge_table=_loyal_table_x)
                                if _loyal_orig_x:
                                    tmp.initialize(verbose=False)
                            try:
                                tmp.live_sim_battle(skip_deck_select=True,
                                                combat_log=_ma_combat_log_arena,
                                                focus_unknown=True)
                            finally:
                                if _loyal_orig_x:
                                    tmp._restore_loyal_deck(_loyal_orig_x, _loyal_cmdr_x)
                            # Restore original active deck if changed
                            tmp.initialize(verbose=False)
                            _active_deck_after = str(tmp.init_data.get('user_data', {}).get('active_deck', '1'))
                            if _active_deck_after != _active_deck_before:
                                try:
                                    tmp.api.call('setActiveDeck', deck_id=_active_deck_before)
                                    print(f"  ↩  Restored active deck -> Slot {_active_deck_before}")
                                except Exception:
                                    pass
                        else:
                            print(f"  [ARENA]  skipped (stamina=0)")

                    except PleaseWaitError as e:
                        print(f"  ⏭  {nick}: API busy ({e}) – skipping")
                    except (URLError, OSError, ConnectionError, TimeoutError) as e:
                        print(f"  ✗  {nick}: network error – {e}")
                    except Exception as e:
                        print(f"  ✗  {nick}: {e}")
                        import traceback; traceback.print_exc()

                    sleep(1)

                if not loop_mode:
                    break
                print(f"\n  Loop {_loop_count} complete – Ctrl+C to stop...")
                sleep(2)

        except KeyboardInterrupt:
            print("\n\n  ↩ Stopped by user")

        print(f"\n{'='*65}")
        print(f"  COMBINED RUN COMPLETE  |  {_loop_count} loop(s)")
        print(f"{'='*65}")


