    def optimize_mission_deck(self, instance=None):
        """
        Finds the first active Quest Mission (same logic as play_first_quest_mission_loop),
        runs TUO climb with the current Slot 6 deck as seed, then saves the
        optimized result back to Slot 6.

        TUO command pattern:
          tuo.exe "<slot6_deck>" "<mission_name>" pvp random -t N endgame 2
                  target 99 timeout 1 -o="data\\ownedcards\\NAME.txt" climb 10000 dom-owned

        If `instance` is provided (a TyrantCommander already initialized),
        uses it directly - useful when called from multi-account context.
        """
        import subprocess as _sp, re as _re, json as _json, os as _os

        _self = instance or self
        if instance is None:
            _self.initialize(verbose=False)

        if not _self._tuo_available():
            print("  ✗ tuo.exe not found")
            return False

        card_data = _self._load_card_data()
        mission_data = _self._load_mission_data()

        # ── Find active quest mission (same logic as play_first_quest_mission_loop) ──
        achievements   = _self.init_data.get('user_achievements', {})
        faction_quests = _self.init_data.get('faction_quests', {})

        missions = []
        for aid, a in achievements.items():
            req = a.get('req', {})
            if 'mission' in req and int(a.get('type', 0)) == 4:
                progress = int(a.get('progress', 0))
                max_prog = int(a.get('max_progress', 1))
                if progress < max_prog:
                    missions.append({
                        'label':      a.get('name', f"Quest #{aid}"),
                        'mission_id': int(req['mission']),
                        'level':      int(req.get('level', 1)),
                        'progress':   progress,
                        'max':        max_prog,
                    })
        for qid, q in faction_quests.items():
            if 'mission' in q:
                progress = int(q.get('progress', 0))
                req_num  = int(q.get('req', {}).get('num_to_complete', 0))
                if progress < req_num:
                    missions.append({
                        'label':      q.get('name', f"Guild Quest #{qid}"),
                        'mission_id': int(q['mission']),
                        'level':      None,
                        'progress':   progress,
                        'max':        req_num,
                    })

        if not missions:
            print("  ✗ No active quest missions found")
            return False

        selected    = missions[0]
        mission_id  = selected['mission_id']
        level       = selected.get('level')
        _label      = selected['label']
        _lv_str     = f" Lv.{level}" if level and f"Lv.{level}" not in _label and f"Lv. {level}" not in _label else ""

        import re as _re_tgt

        # Load achievements.xml to know which missions are level-based
        _mission_ach   = _self._load_mission_achievements()  # mid -> [sorted levels]
        # Use unfiltered name lookup (includes mission_type=4 Mutant missions
        # that are excluded from mission_data to protect the 3-star grind)
        _all_names     = _self._load_all_mission_names()     # mid -> name

        # ── Build TUO target name ─────────────────────────────────────────────
        # TUO uses exact mission names from missions.xml (no numeric prefix).
        # Level-based missions always simulate at -10 (hardest TUO variant).
        _raw_name = _all_names.get(mission_id)

        if _raw_name:
            target_name = _raw_name  # already clean, no numeric prefix in missions.xml
            # Always simulate at level 10 for level-based missions (hardest TUO variant)
            if mission_id in _mission_ach:
                target_name = f"{target_name}-10"
        else:
            # Fallback: derive from quest label when mission is not in missions.xml
            _fallback = _re_tgt.sub(r'\s+Lv\.?\s*\d+$', '', _label).strip()
            if _fallback:
                _tuo_level = level or 1
                target_name = f"{_fallback}-{_tuo_level}"
                print(f"  ⚠ Mission ID {mission_id} not in missions.xml — using: {target_name!r}")
            else:
                print(f"  ⚠ Mission ID {mission_id} not found in missions.xml — skipping TUO sim")
                return False

        print(f"  🎯 Quest mission: {_label}{_lv_str}  ({selected['progress']}/{selected['max']})")
        print(f"  📌 TUO target:    {target_name}")

        # ── Read Slot 6 deck ──────────────────────────────────────────────────
        user_decks = _self.init_data.get('user_decks', {})
        slot6 = user_decks.get('6') or user_decks.get(6) or {}
        if not isinstance(slot6, dict) or not slot6.get('commander_id'):
            print("  ✗ Slot 6 (Mission) not found or empty")
            return False

        # Build flat card ID list from cards dict (repeat for counts > 1)
        _cards_dict = slot6.get('cards', {})
        _card_id_list = []
        for _cid, _cnt in _cards_dict.items():
            _card_id_list.extend([_cid] * int(_cnt))

        seed_str = _self._build_tuo_deck_string(
            slot6['commander_id'],
            slot6.get('dominion_id', 0),
            _card_id_list,
            card_data
        )
        print(f"  📋 Seed deck: {seed_str[:90]}{'...' if len(seed_str) > 90 else ''}")

        # ── Account name for ownedcards file ──────────────────────────────────
        account_name = (_self.api.settings.get('request_data', {}).get('kong_name', '')
                        or _self.init_data.get('user_data', {}).get('name', 'player'))
        safe = "".join(c if c.isalnum() or c in '-_' else '_' for c in account_name)
        owned_candidates = [
            os.path.join(_self._tuo_dir, 'data', 'ownedcards', f'{safe}.txt'),
            os.path.join(SCRIPT_DIR, 'ownedcards', f'{safe}.txt'),
        ]
        owned_flag = next((f'-o={p}' for p in owned_candidates if os.path.isfile(p)), None)

        # ── Hardcoded enemy decks for missions TUO can't handle ──────────────────
        # Key: target_name.lower(); Value: enemy deck string to pass as 2nd argument
        _HARDCODED_ENEMY = {
            'infested relay - delirium': (
                'Delirious Dreamer, Razogoth\'s Blood, Loathe Abysswing, Loathe Abysswing, '
                'Baron\'s Experiment, Intestine Inhaler, Intestine Inhaler, Hurkol Bloodvessel, '
                'Groskrathun, Umgrel Everlasting, Fatal Injector, Dream Drinker'
            ),
        }
        _enemy_override = _HARDCODED_ENEMY.get(target_name.lower())
        if _enemy_override:
            print(f"  ⚠ Using hardcoded enemy deck (TUO mission hang workaround)")

        # ── Build TUO climb command ───────────────────────────────────────────
        # Some missions have TUO multi-threading issues — force -t 1 and lower climb
        _SINGLE_THREAD_MISSIONS = {'gore typhon enraged', 'excelsitus emerged'}
        _target_base      = _re_tgt.sub(r'-\d+$', '', target_name).lower()
        _is_single_thread = _target_base in _SINGLE_THREAD_MISSIONS
        _threads = '1' if _is_single_thread else str(_self.tuo_threads)
        _climb   = '10000' if _is_single_thread else '50000'
        if _is_single_thread:
            print(f"  ⚠ Known TUO threading issue — using -t 1, climb {_climb}")

        _tuo_target = _enemy_override if _enemy_override else (
            f'"{target_name}"' if _re_tgt.search(r'-\d+$', target_name) else target_name
        )

        # ── Read global BGE — fetch via getHuntingTargets ────────────────────
        # ── Ask for global BGE (not in init data; only appears during battles) ──
        _gbge = _self.init_data.get('_current_bge', '')
        if not _gbge and instance is None:
            _gbge_in = input_with_esc("  🌐 Global BGE active? (Enter name or leave empty): ", allow_empty=True)
            _gbge = (_gbge_in or '').strip() if _gbge_in is not None else ''
        if not _gbge:
            _gbge = getattr(_self, '_gbge_override', '')
        if _gbge:
            print(f"  🌐 Global BGE: {_gbge}")

        cmd = [
            _self._tuo_path,
            seed_str,
            _tuo_target,
            'pvp', 'random',
            '-t', _threads,
            'endgame', '2',
            'target', '99',
            'timeout', '1',
        ]
        if _gbge:
            cmd += ['effect', _self._api_bge_to_tuo(_gbge)]
        if owned_flag:
            cmd.append(owned_flag)
        cmd += ['climb', _climb, 'dom-owned', 'no-db', 'no-ml']

        print(f"  ⚙  Running TUO climb (target 99%, endgame 2, timeout 1h)...")
        print(f"  CMD: {' '.join(repr(c) if ' ' in c else c for c in cmd)}")
        print()

        try:
            proc = _sp.run(cmd, capture_output=True, text=True,
                           timeout=3700, cwd=_self._tuo_dir)
            output = proc.stdout + proc.stderr
        except _sp.TimeoutExpired:
            print("  ✗ TUO timed out (1h)")
            return False
        except Exception as e:
            print(f"  ✗ TUO error: {e}")
            return False

        # ── Parse optimized deck from TUO output ──────────────────────────────
        # TUO climb prints lines like:
        #   "24 units: 84.07: Commander, Card1, ..."   (climb format)
        #   "0.9843 Commander, Card1, ..."              (anneal format)
        # Take the LAST matching line (= best result found so far)
        import re as _re_out
        optimized_str = None
        for line in output.splitlines():
            s = line.strip()
            # climb format: "N units: WIN%: deck"  or "units: WIN%: deck"
            m = _re_out.search(r'units:\s*[\d.]+:\s*(.+)', s)
            if m:
                candidate = m.group(1).strip()
                if ',' in candidate:
                    optimized_str = candidate
                continue
            # anneal/fallback format: "0.9843 deck"
            parts = s.split(' ', 1)
            if len(parts) == 2 and parts[0].replace('.', '', 1).isdigit():
                candidate = parts[1].strip()
                if ',' in candidate and not candidate.startswith('units:'):
                    optimized_str = candidate

        # Also try "Optimized Deck: N units: WIN%: Commander, ..." pattern
        if not optimized_str:
            m2 = _re.search(r'Optimized Deck:.*?:\s*[\d.]+:\s*(.+)', output)
            if m2:
                optimized_str = m2.group(1).strip()

        if not optimized_str:
            _err_lines = [l.strip() for l in output.splitlines() if l.strip().startswith('Error:')]
            if _err_lines:
                print(f"  ✗ TUO error: {_err_lines[0]}")
            else:
                print(f"  ✗ Could not parse optimized deck from TUO output")
            print(f"    TUO output (last 5 lines):")
            for ln in output.splitlines()[-5:]:
                print(f"    {ln}")
            return False

        # Extract win rate from the matched line
        _win_rate = ''
        for line in output.splitlines():
            s = line.strip()
            m = _re_out.search(r'units:\s*([\d.]+):\s*(.+)', s)
            if m and ',' in m.group(2):
                _win_rate = m.group(1)
        if _win_rate:
            print(f"  📊 Win rate:  {_win_rate}%")
        print(f"  ✓ Optimized: {optimized_str}")

        # ── Translate card names back to IDs ──────────────────────────────────
        import re as _re_names
        name_to_id        = {}
        name_to_id_lower  = {}
        # Also build base-name map: "Yurich the Honorable" -> highest-level ID
        # TUO outputs names without level suffixes; database stores "Name-1", "Name-6" etc.
        basename_to_id    = {}   # base_lower -> (level, card_id)
        for cid, info in card_data.items():
            if isinstance(info, dict):
                nm = info.get('name', '')
                name_to_id[nm] = cid
                name_to_id_lower[nm.lower()] = cid
                # Build base-name entry (strip trailing "-N")
                _base = _re_names.sub(r'-\d+$', '', nm, count=1).strip()
                _lv   = 0
                _lv_m = _re_names.search(r'-(\d+)$', nm)
                if _lv_m:
                    _lv = int(_lv_m.group(1))
                _bkey = _base.lower()
                if _bkey not in basename_to_id or _lv > basename_to_id[_bkey][0]:
                    basename_to_id[_bkey] = (_lv, cid)

        from collections import Counter as _Counter
        parts_list = [p.strip() for p in optimized_str.split(',')]
        commander_id = dominion_id = None
        resolved = []

        for i, part in enumerate(parts_list):
            # Handle #N count notation
            _count = 1
            if ' #' in part:
                _name_part, _c = part.rsplit(' #', 1)
                if _c.isdigit():
                    part = _name_part.strip()
                    _count = int(_c)

            # Resolve to ID - exact, case-insensitive, strip level suffix, base-name
            cid = None
            if part.isdigit():
                cid = int(part)
            elif part in name_to_id:
                cid = name_to_id[part]
            elif part.lower() in name_to_id_lower:
                cid = name_to_id_lower[part.lower()]
            else:
                _stripped = _re.sub(r'-\d+$', '', part).strip()
                if _stripped != part:
                    if _stripped in name_to_id:
                        cid = name_to_id[_stripped]
                    elif _stripped.lower() in name_to_id_lower:
                        cid = name_to_id_lower[_stripped.lower()]
                # Base-name map: TUO outputs "Yurich the Honorable", DB has "Yurich the Honorable-1"
                if cid is None:
                    _bkey = part.lower()
                    if _bkey in basename_to_id:
                        cid = basename_to_id[_bkey][1]
                if cid is None and _stripped != part:
                    _bkey = _stripped.lower()
                    if _bkey in basename_to_id:
                        cid = basename_to_id[_bkey][1]

            if cid is None:
                print(f"  ⚠ Could not resolve card: {part}")
                continue

            if i == 0:
                commander_id = cid
            elif i == 1:
                dominion_id = cid
            else:
                for _ in range(_count):
                    resolved.append(cid)

        if not commander_id:
            print("  ✗ Could not resolve commander from optimized deck")
            return False

        # ── Save optimized deck to Slot 6 ─────────────────────────────────────
        import json as _json2
        cards_json = _json2.dumps({str(c): str(cnt) for c, cnt in _Counter(resolved).items()})
        result = _self.api.call('setDeckCards',
                                deck_id='6',
                                commander_id=str(commander_id),
                                dominion_id=str(dominion_id or 0),
                                cards=cards_json,
                                activeYN='0')

        if result and result.get('result') in (True, 1, '1', 'true'):
            print(f"  ✓ Optimized deck saved to Slot 6 (Mission)")
            _self.initialize(verbose=False)
            return True
        else:
            print(f"  ✗ Failed to save deck to Slot 6")
            return False
    def optimize_mission_deck_all_accounts(self):
        """
        Runs optimize_mission_deck for all play_enabled accounts.
        """
        import glob as _glob, json as _json

        print(f"\n{'='*65}")
        print(f"  OPTIMIZE MISSION DECK – ALL ACCOUNTS")
        print(f"{'='*65}")

        # Ask for GBGE once for all accounts
        _gbge_all = input_with_esc("  🌐 Global BGE active? (Enter name or leave empty): ", allow_empty=True)
        _gbge_all = (_gbge_all or '').strip() if _gbge_all is not None else ''

        _settings_dirs = [SCRIPT_DIR, os.path.join(SCRIPT_DIR, 'settings')]
        settings_files = []
        for _sd in _settings_dirs:
            settings_files += _glob.glob(os.path.join(_sd, 'settings_*.json'))
        settings_files = [f for f in settings_files
                          if not os.path.basename(f).startswith('settings_TEMPLATE')]
        settings_files = sorted({os.path.normpath(f): f for f in settings_files}.values())

        ok = 0; failed = 0; skipped = 0
        for sf in settings_files:
            nick = os.path.basename(sf).replace('settings_', '').replace('.json', '')
            try:
                with open(sf, 'r', encoding='utf-8') as fh:
                    cfg = _json.load(fh)
                if not cfg.get('play_enabled', True):
                    skipped += 1
                    continue
            except Exception:
                skipped += 1
                continue

            print(f"\n{'─'*65}")
            print(f"  [{nick}]")
            try:
                tmp = TyrantCommander(sf)
                if not tmp.initialize(verbose=False):
                    print(f"  ✗ Login failed")
                    failed += 1
                    continue
                if _gbge_all:
                    tmp._gbge_override = _gbge_all
                success = self.optimize_mission_deck(instance=tmp)
                if success:
                    ok += 1
                else:
                    failed += 1
            except Exception as e:
                print(f"  ✗ {e}")
                failed += 1

        print(f"\n{'='*65}")
        print(f"  Done - {ok} ✓  {failed} ✗  {skipped} skipped")

    def update_deck_from_import(self):
        """
        Reads a TUO result file from the import folder, lets the user pick the file
        and target slot, then sets the optimized deck for each matched account.

        Expected file format (one block per account):
          AccountName :  Optimized Deck: N units: $COST WIN%: Commander, Dominion, Card1, ...
          Upgraded Cards: ...
        """
        import glob as _glob, json as _json, re as _re_imp, os as _os

        # ── Find import files ─────────────────────────────────────────────────
        import_dirs = [
            os.path.join(SCRIPT_DIR, 'import'),
            os.path.join(SCRIPT_DIR, 'data', 'import'),
        ]
        txt_files = []
        for d in import_dirs:
            if os.path.isdir(d):
                txt_files += _glob.glob(os.path.join(d, '*.txt'))
        txt_files = sorted(set(txt_files))

        if not txt_files:
            print("  ✗ No .txt files found in import/ folder")
            return

        print(f"\n{'='*60}")
        print("  UPDATE DECK FROM IMPORT FILE")
        print(f"{'='*60}")
        print("\n  Available files:")
        for i, f in enumerate(txt_files, 1):
            print(f"  {i:>2}.  {os.path.basename(f)}")

        sel = input_with_esc(f"\n  Select file (1-{len(txt_files)}, ESC=Cancel): ")
        if sel is None:
            return
        if not sel.strip().isdigit() or not (1 <= int(sel.strip()) <= len(txt_files)):
            print("  ✗ Invalid selection")
            return
        chosen_file = txt_files[int(sel.strip()) - 1]
        print(f"\n  ✓ Selected: {os.path.basename(chosen_file)}")

        # ── Parse file ────────────────────────────────────────────────────────
        # Format: "Name :  Optimized Deck: N units: $COST WIN%: deck_str"
        parsed = {}   # norm_name -> (raw_name, deck_str)
        with open(chosen_file, encoding='utf-8', errors='replace') as fh:
            content = fh.read()

        # Match lines: "Name :  Optimized Deck: ... WIN%: deck"
        # Format variations TUO produces:
        #   "Name :  Optimized Deck: N units: $COST WIN%: deck"                           (arena)
        #   "Name :  Optimized Deck: N units: $COST WIN% (extra): deck"                   (arena+stall text)
        #   "Name :  Optimized Deck: N units: $COST (WIN% win) FLOAT: deck"               (raid)
        #   "Name :  Optimized Deck: N units: $COST (WIN% win) FLOAT [pts per win]: deck" (brawl)
        #   "Name :  Optimized Deck: N units: $COST (X% stall) FLOAT: deck"               (defense)
        # Generic: after $COST skip any (...) groups, floats, [...] groups, then grab deck after ':'
        pattern = _re_imp.compile(
            r'^([^\n:]+?)\s*:\s+Optimized Deck:.*?\$[\d.]+'  # account + header + cost
            r'(?:\s*[\d.]+)?'                                  # optional leading float (WIN%)
            r'(?:\s*\([^)]*\))*'                              # zero or more (...) groups
            r'(?:\s*[\d.]+)?'                                  # optional trailing float (score)
            r'(?:\s*\[[^\]]*\])?'                             # optional [...]
            r'\s*:\s*(.+)$',                                  # : deck_str
            _re_imp.MULTILINE
        )
        for m in pattern.finditer(content):
            raw_name  = m.group(1).strip()
            deck_str  = m.group(2).strip()
            norm_name = ''.join(c if c.isalnum() or c in '-_' else '' for c in raw_name).lower()
            if norm_name and deck_str and ',' in deck_str:
                parsed[norm_name] = (raw_name, deck_str)

        if not parsed:
            print("  ✗ No deck entries found in file")
            return

        print(f"  ✓ Parsed {len(parsed)} deck(s) from file")

        # ── Slot selection ────────────────────────────────────────────────────
        print("\n  Target deck slot:")
        print("  1  Arena     2  Brawl     3  Arena Defense")
        print("  4  Brawl Defense     5  Raid     6  Mission")
        slot_in = input_with_esc("\n  Slot (1-6, ESC=Cancel): ")
        if slot_in is None:
            return
        slot = slot_in.strip()
        if slot not in ('1', '2', '3', '4', '5', '6'):
            print("  ✗ Invalid slot")
            return

        # ── Load card data for name→ID resolution ─────────────────────────────
        card_data = self._load_card_data()

        name_to_id       = {}
        name_to_id_lower = {}
        basename_to_id   = {}   # base_lower -> (level, cid)
        for cid, info in card_data.items():
            if isinstance(info, dict):
                nm = info.get('name', '')
                name_to_id[nm] = cid
                name_to_id_lower[nm.lower()] = cid
                _base = _re_imp.sub(r'-\d+$', '', nm, count=1).strip()
                _lv_m = _re_imp.search(r'-(\d+)$', nm)
                _lv   = int(_lv_m.group(1)) if _lv_m else 0
                _bkey = _base.lower()
                if _bkey not in basename_to_id or _lv > basename_to_id[_bkey][0]:
                    basename_to_id[_bkey] = (_lv, cid)

        def resolve_name(part):
            part = part.strip()
            if part.isdigit():
                return int(part)
            if part in name_to_id:
                return name_to_id[part]
            if part.lower() in name_to_id_lower:
                return name_to_id_lower[part.lower()]
            _stripped = _re_imp.sub(r'-\d+$', '', part, count=1).strip()
            if _stripped != part:
                if _stripped in name_to_id:
                    return name_to_id[_stripped]
                if _stripped.lower() in name_to_id_lower:
                    return name_to_id_lower[_stripped.lower()]
            if part.lower() in basename_to_id:
                return basename_to_id[part.lower()][1]
            if _stripped.lower() in basename_to_id:
                return basename_to_id[_stripped.lower()][1]
            return None

        # ── Load settings files ───────────────────────────────────────────────
        settings_dirs = [SCRIPT_DIR, os.path.join(SCRIPT_DIR, 'settings')]
        settings_files = []
        for sd in settings_dirs:
            settings_files += _glob.glob(os.path.join(sd, 'settings_*.json'))
        settings_files = [f for f in settings_files
                          if not os.path.basename(f).startswith('settings_TEMPLATE')]
        settings_files = sorted({os.path.normpath(f): f for f in settings_files}.values())

        print(f"\n{'='*60}")
        print(f"  Updating Slot {slot} for matched accounts...")
        print(f"{'='*60}")

        ok = 0; failed = 0; skipped = 0; no_match = 0
        incomplete = []   # accounts that failed due to insufficient SP
        for sf in settings_files:
            nick = os.path.basename(sf).replace('settings_', '').replace('.json', '')
            try:
                with open(sf, 'r', encoding='utf-8') as fh:
                    cfg = _json.load(fh)
                if not cfg.get('play_enabled', True):
                    skipped += 1
                    continue
            except Exception:
                skipped += 1
                continue

            # Match kong_name against parsed accounts
            kong = (cfg.get('kong_name')
                    or cfg.get('request_data', {}).get('kong_name')
                    or nick)
            norm_kong = ''.join(c if c.isalnum() or c in '-_' else '' for c in kong).lower()

            if norm_kong not in parsed:
                no_match += 1
                continue

            raw_name, deck_str = parsed[norm_kong]

            # Resolve deck string → IDs
            from collections import Counter as _Counter
            parts_list = [p.strip() for p in deck_str.split(',')]
            commander_id = dominion_id = None
            card_ids = []
            unresolved = []

            for i, part in enumerate(parts_list):
                _count = 1
                if ' #' in part:
                    _np, _c = part.rsplit(' #', 1)
                    if _c.isdigit():
                        part = _np.strip()
                        _count = int(_c)
                cid = resolve_name(part)
                if cid is None:
                    unresolved.append(part)
                    continue
                if i == 0:
                    commander_id = cid
                elif i == 1:
                    dominion_id = cid
                else:
                    card_ids.extend([cid] * _count)

            if not commander_id:
                print(f"  ✗  {kong} [{raw_name}]: could not resolve commander")
                failed += 1
                continue
            if unresolved:
                print(f"  ⚠  {kong}: unresolved — {', '.join(unresolved)}")

            # Login, check inventory, resolve missing, then save
            try:
                tmp = TyrantCommander(sf)
                if not tmp.initialize(verbose=False):
                    print(f"  ✗  {kong}: login failed")
                    failed += 1
                    continue

                # ── Inventory check ───────────────────────────────────────────
                user_cards = tmp.init_data.get('user_cards', {})
                from collections import Counter as _Counter
                needed = _Counter()
                if commander_id:
                    needed[commander_id] += 1
                if dominion_id:
                    needed[dominion_id] += 1
                for cid in card_ids:
                    needed[cid] += 1

                missing_cards = []
                for cid, cnt in needed.items():
                    owned = int((user_cards.get(str(cid)) or {}).get('num_owned', 0))
                    if owned < cnt:
                        _info  = card_data.get(int(cid), card_data.get(cid, {}))
                        _cname = _info.get('name', f'ID_{cid}') if isinstance(_info, dict) else f'ID_{cid}'
                        missing_cards.append({
                            'card_id': cid,
                            'name':    _cname,
                            'needed':  cnt,
                            'owned':   owned,
                            'deficit': cnt - owned,
                        })

                if missing_cards:
                    print(f"  ⚠  {kong}: {len(missing_cards)} missing card type(s) — running Resolution Assistant")
                    resolved = tmp._resolve_missing_cards(
                        missing_cards, card_data, str(slot),
                        commander_id, dominion_id, card_ids,
                        auto_confirm=True
                    )
                    if not resolved:
                        print(f"  ✗  {kong}: incomplete (insufficient SP or build error)")
                        incomplete.append(kong)
                        failed += 1
                        continue
                    ok += 1
                    continue  # _resolve_missing_cards already saved the deck

                cards_json = _json.dumps(
                    {str(c): str(cnt) for c, cnt in _Counter(card_ids).items()})
                result = tmp.api.call('setDeckCards',
                                     deck_id=str(slot),
                                     commander_id=str(commander_id),
                                     dominion_id=str(dominion_id or 0),
                                     cards=cards_json,
                                     activeYN='0')
                if result and result.get('result') in (True, 1, '1', 'true'):
                    print(f"  ✓  {kong}: Slot {slot} updated")
                    ok += 1
                else:
                    print(f"  ✗  {kong}: API error")
                    failed += 1
            except Exception as e:
                print(f"  ✗  {kong}: {e}")
                failed += 1

        print(f"\n{'─'*60}")
        print(f"  Done — {ok} ✓  {failed} ✗  {skipped} skipped  {no_match} no match in file")
        if incomplete:
            print(f"\n  ⚠ Incomplete (insufficient SP after 10 workflow loops):")
            for _acc in incomplete:
                print(f"     • {_acc}")

    def set_attack_defense_all_accounts(self):
        """
        Sets attack or defense deck to a chosen slot for all play_enabled accounts.
        Prompts: slot number -> attack or defense.
        Accounts that don't have the slot unlocked are skipped with a warning.
        """
        import glob as _glob, json as _json

        print(f"\n{'='*65}")
        print(f"  CHANGE ATTACK / DEFENSE DECK – ALL ACCOUNTS")
        print(f"{'='*65}")

        # ── Slot selection ────────────────────────────────────────
        print("\n  Which deck slot?")
        print("  1  Arena (Slot 1)")
        print("  2  Brawl (Slot 2)")
        print("  3  Arena Defense (Slot 3)")
        print("  4  Brawl Defense (Slot 4)")
        print("  5  Raid (Slot 5)   - unlock costs 200 WB")
        print("  6  Mission (Slot 6) - unlock costs 250 WB")
        slot_in = input_with_esc("\n  Slot (1–6, ESC=Cancel): ")
        if slot_in is None:
            return
        slot = slot_in.strip()
        if slot not in ('1', '2', '3', '4', '5', '6'):
            print("  ✗ Invalid slot")
            return

        _SLOT_LABELS   = {'1': 'Arena', '2': 'Brawl', '3': 'Arena Defense',
                          '4': 'Brawl Defense', '5': 'Raid', '6': 'Mission'}
        _UNLOCK_IDS    = {'3': '101', '4': '102', '5': '151', '6': '152'}
        _UNLOCK_COSTS  = {'3': 100,   '4': 150,   '5': 200,   '6': 250}
        slot_label     = _SLOT_LABELS.get(slot, f'Slot {slot}')
        unlock_upg_id  = _UNLOCK_IDS.get(slot)
        unlock_wb_cost = _UNLOCK_COSTS.get(slot, 0)

        # ── Attack or Defense ─────────────────────────────────────
        print("\n  Set as:")
        print("  A  Attack deck  (setActiveDeck)")
        print("  D  Defense deck (setDefenseDeck)")
        ad_in = input_with_esc("\n  Selection (A/D, ESC=Cancel): ")
        if ad_in is None:
            return
        ad = ad_in.strip().upper()
        if ad not in ('A', 'D'):
            print("  ✗ Invalid selection")
            return

        api_call  = 'setActiveDeck' if ad == 'A' else 'setDefenseDeck'
        role_name = 'attack' if ad == 'A' else 'defense'
        print(f"\n  -> Setting {slot_label} (Slot {slot}) as {role_name} deck on all accounts...")
        print(f"{'─'*65}")

        # ── Load accounts ─────────────────────────────────────────
        _settings_dirs = [SCRIPT_DIR, os.path.join(SCRIPT_DIR, 'settings')]
        settings_files = []
        for _sd in _settings_dirs:
            settings_files += _glob.glob(os.path.join(_sd, 'settings_*.json'))
        settings_files = [f for f in settings_files
                          if not os.path.basename(f).startswith('settings_TEMPLATE')]
        settings_files = sorted({os.path.normpath(f): f for f in settings_files}.values())

        if not settings_files:
            print("  ✗ No settings_*.json files found")
            return

        # Ask whether to auto-unlock if slot not available (slots 3–6 only)
        _auto_unlock = False
        if unlock_upg_id:
            _ul_in = input_with_esc(
                f"\n  Auto-unlock {slot_label} slot for accounts that don't have it? ({unlock_wb_cost} WB each) [Y/N]: ")
            _auto_unlock = (_ul_in or '').strip().upper() == 'Y'
            print()

        ok = 0
        unlocked = 0
        skipped_disabled = 0
        skipped_noslot = []
        failed = 0
        for sf in settings_files:
            nick = os.path.basename(sf).replace('settings_', '').replace('.json', '')
            try:
                with open(sf, 'r', encoding='utf-8') as fh:
                    cfg = _json.load(fh)
                if not cfg.get('play_enabled', True):
                    skipped_disabled += 1
                    continue
            except Exception:
                skipped_disabled += 1
                continue

            try:
                tmp = TyrantCommander(sf)
                if not tmp.initialize(verbose=False):
                    print(f"  ✗  {nick}: login failed")
                    failed += 1
                    continue

                # Check if slot is unlocked
                user_decks = tmp.init_data.get('user_decks', {})
                slot_exists = (slot in user_decks or int(slot) in user_decks)
                if not slot_exists:
                    if _auto_unlock and unlock_upg_id:
                        # Check WB balance
                        _tokens = int((tmp.init_data.get('user_data') or {}).get('tokens', 0))
                        if _tokens < unlock_wb_cost:
                            print(f"  ⚠  {nick}: Slot {slot} not unlocked - insufficient WB ({_tokens}/{unlock_wb_cost})")
                            skipped_noslot.append(nick)
                            continue
                        _ur = tmp.api.call('buyUpgrade', upgrade_id=str(unlock_upg_id))
                        if _ur and _ur.get('result') in (True, 1, '1', 'true'):
                            print(f"  🔓  {nick}: {slot_label} slot unlocked ({unlock_wb_cost} WB)")
                            unlocked += 1
                            tmp.initialize(verbose=False)  # refresh user_decks
                        else:
                            print(f"  ✗  {nick}: unlock failed")
                            failed += 1
                            continue
                    else:
                        print(f"  ⚠  {nick}: {slot_label} slot not unlocked - skipped")
                        skipped_noslot.append(nick)
                        continue

                result = tmp.api.call(api_call, deck_id=slot)
                if result and result.get('result') in (True, 1, '1', 'true'):
                    print(f"  ✓  {nick}: Slot {slot} ({slot_label}) -> {role_name}")
                    ok += 1
                else:
                    print(f"  ✗  {nick}: API returned error")
                    failed += 1
            except Exception as e:
                print(f"  ✗  {nick}: {e}")
                failed += 1

        print(f"\n{'─'*65}")
        _sum = f"  Done - {ok} ✓  {failed} ✗  {skipped_disabled} skipped (disabled)"
        if unlocked:
            _sum += f"  {unlocked} newly unlocked"
        print(_sum)
        if skipped_noslot:
            print(f"  {slot_label} slot not unlocked on: {', '.join(skipped_noslot)}")

    # ==================== CARDN-MANAGEMENT ====================
    
    # ---------- Card-Data from tyrattonline load ----------

    def _load_mission_data(self):
        """
        Loads missions.xml -> dict: mission_id(int) -> {name, energy, req}.
        First-occurrence-wins for duplicate IDs (metadata at end of XML has
        small IDs 1-10 that collide with real missions).
        Returns empty dict if file not found.
        """
        missions_file = os.path.join(SCRIPT_DIR, 'missions.xml')
        if not os.path.isfile(missions_file):
            return {}
        try:
            import xml.etree.ElementTree as _ET
            tree   = _ET.parse(missions_file)
            root   = tree.getroot()
            result = {}
            for child in root:
                id_el = child.find('id')
                if id_el is None or not id_el.text:
                    continue
                try:
                    mid = int(id_el.text.strip())
                except ValueError:
                    continue
                if mid in result:
                    continue  # first entry wins
                # Skip Mutant missions (mission_type=4) – excluded from 3-star grind
                mt_el = child.find('mission_type')
                if mt_el is not None and mt_el.text and mt_el.text.strip() == '4':
                    continue
                # Skip retired location 109 – area removed from game,
                # missions still appear in mission_completions but are unplayable
                loc_el = child.find('location_id')
                if loc_el is not None and loc_el.text and loc_el.text.strip() == '109':
                    continue
                name_el   = child.find('name')
                energy_el = child.find('energy')
                req_el    = child.find('req')
                energy = None
                if energy_el is not None and energy_el.text and energy_el.text.strip().isdigit():
                    energy = int(energy_el.text.strip())
                req = None
                if req_el is not None and req_el.text:
                    _req_s = req_el.text.strip()
                    try:
                        _req_v = int(_req_s)
                        req = _req_v if _req_v >= 0 else -1  # -1 = never available
                    except ValueError:
                        req = -1
                result[mid] = {
                    'name':   name_el.text.strip() if name_el is not None and name_el.text else f'Mission {mid}',
                    'energy': energy,
                    'req':    req,
                }
            return result
        except Exception:
            return {}

    def _load_mission_achievements(self):
        """
        Loads achievements.xml → dict: mission_id(int) -> sorted list of level ints.
        Only includes type-4 achievements that have a 'level' requirement.
        Used to determine whether a mission needs a '-N' level suffix for TUO.
        Returns empty dict if achievements.xml is not found.
        """
        ach_file = os.path.join(SCRIPT_DIR, 'achievements.xml')
        if not os.path.isfile(ach_file):
            return {}
        try:
            import xml.etree.ElementTree as _ET
            result = {}
            for a in _ET.parse(ach_file).getroot().findall('achievement'):
                t = a.find('type')
                if t is None or t.text != '4':
                    continue
                req = a.find('req')
                if req is None:
                    continue
                m_el  = req.find('mission')
                lv_el = req.find('level')
                if m_el is None or lv_el is None:
                    continue
                try:
                    mid = int(m_el.text)
                    lv  = int(lv_el.text)
                except (ValueError, TypeError):
                    continue
                result.setdefault(mid, set()).add(lv)
            return {mid: sorted(lvs) for mid, lvs in result.items()}
        except Exception:
            return {}

    def _load_all_mission_names(self):
        """
        Loads missions.xml → dict: mission_id(int) -> name (str).
        Unlike _load_mission_data(), this includes ALL missions (including
        mission_type=4 Mutant missions) so optimize_mission_deck can always
        resolve the correct TUO name regardless of mission type.
        Returns empty dict if file not found.
        """
        missions_file = os.path.join(SCRIPT_DIR, 'missions.xml')
        if not os.path.isfile(missions_file):
            return {}
        try:
            import xml.etree.ElementTree as _ET
            result = {}
            for child in _ET.parse(missions_file).getroot():
                id_el   = child.find('id')
                name_el = child.find('name')
                if id_el is None or not id_el.text:
                    continue
                try:
                    mid = int(id_el.text.strip())
                except ValueError:
                    continue
                if mid in result:
                    continue  # first entry wins
                result[mid] = name_el.text.strip() if name_el is not None and name_el.text else f'Mission {mid}'
            return result
        except Exception:
            return {}

    def _load_card_data(self):
        """
        Loads cards_section_1.xml … cards_section_N.xml from
        mobile.tyrantonline.com and builds a mapping
        Resolves card_id -> "Name-Level" string.

        Struktur pro XML:
            <root>
              <unit>
                <id>...</id>          ← Basis-card_id
                <name>CardName</name> ← Name
                <rarity>...</rarity>  ← 1 Common, 2 Rare, 3 Epic, 4 Legendary
                <upgrade>
                  <card_id>...</card_id>
                  <level>...</level>
                </upgrade>
                ...
              </unit>
            </root>

        Base-Card is stored as Level 1.
        Result is cached in _card_data_cache (loaded only once).

        Returns:
            dict: { int(card_id): "Name-Level" }
        """
        if self._card_data_cache:
            return self._card_data_cache

        card_data = {}
        loaded    = 0
        errors    = 0
        error_msgs = []

        # Extended to 22 sections (section 22 optional)
        for section in range(1, 23):
            filename   = f"cards_section_{section}.xml"
            local_path = os.path.join(SCRIPT_DIR, filename)
            url        = f"{CARDS_BASE_URL}{filename}"

            try:
                if os.path.isfile(local_path):
                    with open(local_path, 'rb') as fh:
                        xml_bytes = fh.read()
                else:
                    response  = urlopen(url, timeout=15)
                    xml_bytes = response.read()

                root = ET.fromstring(xml_bytes)

                for unit in root.findall('.//unit'):
                    id_elem   = unit.find('id')
                    name_elem = unit.find('n')  # <n> tag, not <name>
                    if name_elem is None:
                        name_elem = unit.find('name')  # Fallback to <name> if <n> not found
                    if id_elem is None or name_elem is None:
                        continue
                    if id_elem.text is None or name_elem.text is None:
                        continue

                    base_id = int(id_elem.text)
                    name    = name_elem.text

                    card_data[base_id] = {"name": f"{name}-1", "level": 1, "xml_level": 1, "base_id": base_id}

                    # Track label chains for correct visual level calculation
                    # e.g. "Tabitha Exiled" starts at xml_level 4 -> visual level 1
                    _label_xml_offset = 0  # xml_level of the current label start
                    _current_label    = None
                    for upgrade in unit.findall('upgrade'):
                        cid_elem = upgrade.find('card_id')
                        lvl_elem = upgrade.find('level')
                        if cid_elem is None or lvl_elem is None:
                            continue
                        if cid_elem.text is None or lvl_elem.text is None:
                            continue

                        upg_id      = int(cid_elem.text)
                        upg_xml_lvl = int(lvl_elem.text)
                        upg_label_elem = upgrade.find('name')
                        upg_label = upg_label_elem.text.strip() if (upg_label_elem is not None and upg_label_elem.text) else None

                        if upg_label:
                            # New named chain starts here at visual level 1
                            _current_label    = upg_label
                            _label_xml_offset = upg_xml_lvl - 1  # subtract to get visual=1

                        visual_level = upg_xml_lvl - _label_xml_offset
                        display_name = _current_label if _current_label else name
                        card_data[upg_id] = {"name": f"{display_name}-{visual_level}",
                                             "level": visual_level,
                                             "xml_level": upg_xml_lvl,   # raw upgrade step for SP cost lookup
                                             "base_id": base_id,
                                             "label": upg_label,         # set only on the first card of the chain
                                             "label_name": _current_label}  # always set to current chain name

                loaded += 1

            except URLError as e:
                if section == 22 and "404" in str(e):
                    pass  # Section 22 is optional
                else:
                    errors += 1
                    error_msgs.append(f"Section {section}: {e}")
            except Exception as e:
                if section == 22 and "404" in str(e):
                    pass  # Section 22 is optional
                else:
                    errors += 1
                    error_msgs.append(f"Section {section}: {e}")

        self._card_data_cache = card_data

        if errors > 0:
            print(f"⚠ Card data loaded with errors: {len(card_data)} cards from {loaded} Sections ({errors} Error)")
            for msg in error_msgs:
                print(f"   ✗ {msg}")

        return card_data

    def _get_card_info(self, card_data, card_id, default_name=None):
        """Universal function to get card_info (Dict and String compatible)"""
        if default_name is None:
            default_name = f"ID_{card_id}"
        
        info = card_data.get(card_id, None)
        
        if isinstance(info, dict):
            return {
                'name': info.get('name', default_name),
                'level': info.get('level', 1),
                'base_id': info.get('base_id', card_id)
            }
        
        if isinstance(info, str):
            if '-' in info:
                parts = info.rsplit('-', 1)
                try:
                    level = int(parts[1])
                    return {'name': info, 'level': level, 'base_id': card_id}
                except (ValueError, IndexError):
                    pass
            return {'name': info, 'level': 1, 'base_id': card_id}
        
        return {'name': default_name, 'level': 1, 'base_id': card_id}

    def _resolve_card(self, card_id, card_data):
        """
        Resolves a card_id into a readable string.
        Level 6 suffix is stripped (consistent with PS1 script behavior).

        Returns:
            str: e.g. "Tiamat-3" or "Draconian Queen" (Level 6 -> no suffix)
        """
        if card_id is None:
            return ""
        try:
            card_id_int = int(card_id)
        except (TypeError, ValueError):
            return f"ID_{card_id}"
        card_info = card_data.get(card_id_int, f"ID_{card_id}")
        
        # Handle dict format (from XML data)
        if isinstance(card_info, dict):
            name = card_info.get('name', f"ID_{card_id}")
        # Handle string format (legacy)
        elif isinstance(card_info, str):
            name = card_info
        else:
            name = f"ID_{card_id}"
        
        # Level 6 entfernen (PS1: replace("-6",""))
        if isinstance(name, str) and name.endswith("-6"):
            name = name[:-2]
        return name

    def _classify_fusion(self, card_name):
        """
        Classifies a card into a fusion material group.
        Returns the group index, or -1 if no group matches.

        Args:
            card_name: the resolved name (e.g. "Tiamat-3" or "Tiamat")
        """
        # Only the name without Level and without bracket count check
        base = card_name.split("-")[0].split(" (")[0].strip()
        for idx, (group_name, prefixes) in enumerate(FUSION_GROUPS):
            if base in prefixes:
                return idx
        return -1

    def salvage_base_epics_keep_x(self, keep_count=1, silent=False, auto_confirm=False, compact=False):
        """
        Salvages all Base Epics keeping X copies per card.
        
        Base Epics are the 25 Fusion-Material Cards:
        - 5x Bloodthirsty (ohne Malgoth)
        - 5x Imperial (ohne Nimbus)
        - 5x Raider (ohne Omega)
        - 5x Righteous (ohne Benediction)
        - 5x Xeno (ohne Apex)
        
        Args:
            keep_count: Number to keep per card (default: 1)
            silent: If True, minimal output (for use in workflows)
        
        Returns:
            (success: bool, sp_gain: int)
        """
        # Refresh data to get current state
        self.initialize(verbose=False)
        
        if not silent:
            print(f"\n{'='*60}")
            print(f"SALVAGE BASE EPICS (keep {keep_count} per card)")
            print(f"{'='*60}")
        card_data = self._load_card_data_with_rarity()
        if not card_data:
            if not silent:
                print("✗ Cannot continue without card data.")
            return False, 0
        
        # Identify base epics (from Fusion-Gruppen, only Epics)
        base_epic_names = []
        for group_name, card_names in FUSION_GROUPS[1:]:  # Skip Vindicator Reactors
            for card_name in card_names:
                # Check if Epic
                for card_id, info in card_data.items():
                    # Handle both dict and string format
                    if isinstance(info, dict):
                        if info.get('name') == card_name and info.get('level', 1) == 1 and info.get('rarity') == 3:
                            base_epic_names.append(card_name)
                            break
                    elif isinstance(info, str):
                        # String format doesn't have rarity info, skip
                        continue
        
        if not silent:
            print(f"\nBase Epics found: {len(base_epic_names)}")
        
        # Go through inventory
        user_cards = self.init_data.get('user_cards', {})
        
        to_salvage = []
        
        for card_id, info in user_cards.items():
            card_id_int = int(card_id)
            
            # Upgrade materials, Commanders and Dominions skip
            if card_id_int in EXCLUDED_CARD_IDS:
                continue
            
            num_owned = int(info.get('num_owned', 0))
            if num_owned <= 0:
                continue
            
            card_id_int = int(card_id)
            card_info = card_data.get(card_id_int)
            
            if not card_info:
                continue
            
            # Handle both dict and string format
            if isinstance(card_info, dict):
                card_name = card_info.get('name', '')
                card_level = card_info.get('level', 1)
            elif isinstance(card_info, str):
                # String format - parse level from name
                card_name = card_info
                card_level = 1
                if '-' in card_info:
                    parts = card_info.rsplit('-', 1)
                    try:
                        card_level = int(parts[1])
                    except ValueError:
                        pass
            else:
                continue
            
            # Is it a Base Epic?
            if card_name in base_epic_names and card_level == 1:
                if num_owned > keep_count:
                    salvage_amount = num_owned - keep_count
                    to_salvage.append({
                        'card_id': card_id_int,
                        'name': card_name,
                        'owned': num_owned,
                        'keep': keep_count,
                        'salvage': salvage_amount
                    })
        
        if not to_salvage:
            if not silent:
                print("✓ Nothing to salvage - all base epics already at target count or below")
            return True, 0
        
        # Summary
        to_salvage.sort(key=lambda x: x['name'])
        
        total_salvage = 0
        total_sp = 0
        
        for item in to_salvage:
            total_salvage += item['salvage']
            total_sp += item['salvage'] * 20  # Base Epics give 20 SP
        
        # SP LIMIT CHECK BEFORE salvaging
        salvage_before = int(self.init_data.get('user_data', {}).get('salvage', 0))
        
        sp_cap = self.get_sp_cap()
        if salvage_before >= sp_cap:
            if not silent:
                print(f"  ⚠ SP already at cap ({salvage_before:,} / {sp_cap:,}) - skipping")
            return False, 0
        
        # If salvage would exceed cap: trim to_salvage so we only salvage
        # as many cards as fit before hitting the cap (20 SP per epic).
        estimated_sp_after = salvage_before + total_sp
        if estimated_sp_after > sp_cap:
            sp_room = sp_cap - salvage_before          # how much SP we can still receive
            cards_fit = sp_room // 20                  # 20 SP per base epic
            if cards_fit <= 0:
                if not silent:
                    print(f"  ⚠ SP nearly at cap ({salvage_before:,} / {sp_cap:,}, room for 0 cards) - skipping")
                return False, 0
            # Rebuild to_salvage limited to cards_fit total cards
            trimmed = []
            remaining = cards_fit
            for item in to_salvage:
                if remaining <= 0:
                    break
                take = min(item['salvage'], remaining)
                trimmed.append({**item, 'salvage': take})
                remaining -= take
            to_salvage    = trimmed
            total_salvage = sum(i['salvage'] for i in to_salvage)
            total_sp      = total_salvage * 20
            if not silent:
                print(f"  ⚠ SP cap reached after {total_salvage} cards - salvaging partial batch (+{total_sp:,} SP)")
        
        # confirmation (only if not silent and not auto_confirm)
        if not silent and not auto_confirm and not compact:
            if not confirm_action(f"Really salvage {total_salvage} Base Epics?"):
                print("Canceled")
                return False, 0

        if compact:
            # Compact mode: one-line summary + progress bar
            _bar_width = 35
            print(f"  Cards: {total_salvage}  │  SP before: {salvage_before:,}  │  Expected: +{total_sp:,}")
            _done = 0
        elif not silent:
            print(f"\n⏳ Salvage {total_salvage} cards...")
        
        # Unlock locked cards in to_salvage before salvaging
        self._unlock_locked_cards([item['card_id'] for item in to_salvage])

        salvaged_count = 0
        sp_gained = 0
        
        for i, item in enumerate(to_salvage, 1):
            card_id = item['card_id']
            salvage_amount = item['salvage']
            
            if not silent and not compact:
                print(f"  [{i}/{len(to_salvage)}] {item['name']}: -{salvage_amount}...", end=' ', flush=True)
            
            # Salvage each individual card
            for _ in range(salvage_amount):
                try:
                    result = self.api.call('salvageCard', card_id=card_id)
                    if result and result.get('result') in (True, 1, '1', 'true'):
                        salvaged_count += 1
                        sp_gained += 5
                        if compact:
                            _done += 1
                            _filled = int(_bar_width * _done / total_salvage)
                            _bar = '█' * _filled + '░' * (_bar_width - _filled)
                            print(f"\r  [{_bar}] {_done}/{total_salvage}", end='', flush=True)
                    else:
                        if not silent and not compact:
                            print("✗", end='')
                        break
                except Exception as e:
                    if not silent and not compact:
                        print(f"✗ Error: {e}")
                    break
            
            if not silent and not compact:
                print("✓")
            sleep(0.2)  # Rate limiting
        
        self.initialize(verbose=False)
        salvage_after = int(self.init_data.get('user_data', {}).get('salvage', 0))
        sp_actual = salvage_after - salvage_before
        
        if compact:
            print(f"\r  [{'█'*_bar_width}] {salvaged_count}/{total_salvage}  │  SP after: {salvage_after:,}  (+{sp_actual:,})")
        elif not silent:
            print(f"\n{'='*60}")
            print(f"RESULT")
            print(f"{'='*60}")
            print(f"Salvaged         : {salvaged_count}/{total_salvage} cards")
            print(f"SP before        : {salvage_before:,}")
            print(f"SP after       : {salvage_after:,}")
            print(f"SP gewonnen      : +{sp_actual:,}")
            print(f"{'='*60}\n")
        
        return True, sp_actual

    def _load_card_data_with_rarity(self):
        """
        Loads card data including Rarity, Level and Tier from XMLs.
        Uses cache if available.
        
        Returns:
            dict: { card_id: {'name': str, 'level': int, 'rarity': int, 'tier': int} }
        """
        # Use cache if present
        if self._card_data_with_rarity_cache is not None:
            return self._card_data_with_rarity_cache
        
        card_data = {}
        loaded = 0
        errors = 0
        
        # Extended to 22 sections (section 22 optional)
        for section in range(1, 23):
            filename = f"cards_section_{section}.xml"
            local_path = os.path.join(SCRIPT_DIR, filename)
            url = f"{CARDS_BASE_URL}{filename}"
            
            try:
                # Lokal or HTTP
                if os.path.isfile(local_path):
                    with open(local_path, 'rb') as fh:
                        xml_bytes = fh.read()
                else:
                    response = urlopen(url, timeout=15)
                    xml_bytes = response.read()
                
                root = ET.fromstring(xml_bytes)
                
                for unit in root.findall('.//unit'):
                    id_elem = unit.find('id')
                    name_elem = unit.find('n')  # <n> tag, not <n>
                    if name_elem is None:
                        name_elem = unit.find('name')  # Fallback to <n>
                    rarity_elem = unit.find('rarity')
                    tier_elem = unit.find('tier')
                    
                    if id_elem is None or name_elem is None:
                        continue
                    if id_elem.text is None or name_elem.text is None:
                        continue
                    
                    base_id = int(id_elem.text)
                    name = name_elem.text
                    rarity = int(rarity_elem.text) if rarity_elem is not None and rarity_elem.text else 1
                    tier = int(tier_elem.text) if tier_elem is not None and tier_elem.text else 0
                    
                    # Fusion recipe: what is the next upgrade?
                    upgrade_id = None
                    first_upgrade = unit.find('.//upgrade')
                    if first_upgrade is not None:
                        upgrade_cid = first_upgrade.find('card_id')
                        if upgrade_cid is not None and upgrade_cid.text:
                            upgrade_id = int(upgrade_cid.text)
                    
                    # Basis-card: Level 1
                    card_data[base_id] = {
                        'name': name,
                        'level': 1,
                        'rarity': rarity,
                        'tier': tier,
                        'upgrade_id': upgrade_id,
                        'base_id': base_id  # Base points to itself
                    }
                    
                    # Upgrades (levels 2-6)
                    for upgrade in unit.findall('upgrade'):
                        cid_elem = upgrade.find('card_id')
                        lvl_elem = upgrade.find('level')
                        
                        if cid_elem is None or lvl_elem is None:
                            continue
                        if cid_elem.text is None or lvl_elem.text is None:
                            continue
                        
                        upg_id = int(cid_elem.text)
                        upg_level = int(lvl_elem.text)
                        
                        card_data[upg_id] = {
                            'name': name,
                            'level': upg_level,
                            'rarity': rarity,
                            'tier': tier,
                            'base_id': base_id  # Points to Level-1 version
                        }
                
                loaded += 1
                
            except Exception as e:
                # Section 22 is optional - skip at error
                if section == 22:
                    pass  # Ignoriere error for Section 22
                else:
                    errors += 1
        
        # ===== FUSION-TIER CALCULATION WITH REAL RECIPES =====
        
        # Load fusion_recipes_cj2.xml
        fusion_file = os.path.join(SCRIPT_DIR, 'fusion_recipes_cj2.xml')
        fusion_recipes = {}
        
        if os.path.exists(fusion_file):
            try:
                tree = ET.parse(fusion_file)
                for recipe in tree.getroot().findall('fusion_recipe'):
                    card_id_elem = recipe.find('card_id')
                    if card_id_elem is not None and card_id_elem.text:
                        result_id = int(card_id_elem.text)
                        resources = []
                        for res in recipe.findall('resource'):
                            res_id = res.get('card_id')
                            if res_id:
                                resources.append(int(res_id))
                        if resources:
                            fusion_recipes[result_id] = resources
            except Exception as e:
                print(f"⚠ Could not load fusion recipes: {e}")
        else:
            print(f"⚠ fusion_recipes_cj2.xml not found in {SCRIPT_DIR}")
        
        # Calculate tier for each Basis-card (Level 1)
        # IMPORTANT: Must go by names, since recipes can use different IDs!
        
        # Step 1: Build Name->IDs Mapping (only Level 1)
        name_to_ids = {}
        for card_id, info in card_data.items():
            # Handle both dict and string format
            if isinstance(info, dict):
                if info.get('level', 1) == 1:
                    name = info.get('name', '')
                    if name:
                        if name not in name_to_ids:
                            name_to_ids[name] = []
                        name_to_ids[name].append(card_id)
            elif isinstance(info, str):
                # String format: extract level from name (e.g., "Daemon-1")
                if '-' in info:
                    base_name, level_str = info.rsplit('-', 1)
                    try:
                        level = int(level_str)
                        if level == 1:
                            if info not in name_to_ids:
                                name_to_ids[info] = []
                            name_to_ids[info].append(card_id)
                    except ValueError:
                        pass
        
        # Step 2: Build Name->Recipe Mapping
        name_recipes = {}
        for result_id, base_ids in fusion_recipes.items():
            result_name = card_data.get(result_id, {}).get('name', '')
            if result_name:
                base_names = []
                for base_id in base_ids:
                    base_name = card_data.get(base_id, {}).get('name', '')
                    if base_name:
                        base_names.append(base_name)
                if base_names:
                    name_recipes[result_name] = base_names
        
        # Step 3: Find which cards are used as basis
        used_as_base = set()
        for base_names in name_recipes.values():
            for base_name in base_names:
                used_as_base.add(base_name)
        
        # Schritt 4: Bestimme Tier based on Position
        def get_fusion_tier_by_position(name):
            """
            Tier-Logik basierend auf Position in Fusion-Kette:
            - Tier 0: Base only (no recipe, used as ingredient)
            - Tier 1: Middle link (has recipe AND used as ingredient)
            - Tier 2: End result (has recipe, NOT used as ingredient)
            """
            has_recipe = name in name_recipes
            is_used_as_base = name in used_as_base
            
            if not has_recipe and is_used_as_base:
                return 0  # Only Basis
            elif has_recipe and is_used_as_base:
                return 1  # Middle link
            elif has_recipe and not is_used_as_base:
                return 2  # Endglied
            else:
                return 0  # Fallback (none Fusion)
        
        # Schritt 5: Set fusion_tier for all Level-1 cards
        for card_id, info in card_data.items():
            # Handle both dict and string format
            if isinstance(info, dict):
                if info.get('level', 1) == 1:
                    name = info.get('name', '')
                    if name:
                        tier = get_fusion_tier_by_position(name)
                        card_data[card_id]['fusion_tier'] = tier
            # String format catnot be modified, skip
            elif isinstance(info, str):
                continue
        
        # Cache set
        self._card_data_with_rarity_cache = card_data
        
        return card_data

    # ---------- Events & Activities ----------

    def show_events(self):
        """
        Shows detailed information about current events (Brawl, Raids, Conquest, etc.)
        """
        if not self.init_data:
            self.initialize()
        
        player = self.init_data.get('user_data', {})
        active_brawl = self.init_data.get('active_brawl_data')
        player_brawl = self.init_data.get('player_brawl_data')
        current_raids = self.init_data.get('current_raids', {})
        raid_info = self.init_data.get('raid_info', {})
        conquest = self.init_data.get('conquest', {})
        
        print("\n" + "="*70)
        print("🎯 ACTIVE EVENTS & ACTIVITIES")
        print("="*70)
        
        events_found = False
        
        # ===== BRAWL EVENT =====
        if active_brawl and player_brawl:
            events_found = True
            event_name = active_brawl.get('name', 'Brawl Event')
            event_id = active_brawl.get('id', '')

            # Placement Brawl: 1-day pre-GW event, one-time 25 energy, no regen
            # Recognised by "placement" in the event name (e.g. "Wise Placements")
            _is_placement = 'placement' in event_name.lower()

            # Energy
            brawl_energy = player_brawl.get('energy', {})
            current_energy = int(brawl_energy.get('battle_energy', 0))

            # Time
            start_time = int(active_brawl.get('start_time', 0))
            current_time = int(time.time())
            time_elapsed = current_time - start_time
            end_time = int(active_brawl.get('end_time', 0))
            time_remaining = max(0, end_time - current_time)
            days = time_remaining // 86400
            hours = (time_remaining % 86400) // 3600
            minutes = (time_remaining % 3600) // 60
            event_ended = time_remaining == 0

            # Stats
            rank = player_brawl.get('current_rank', '?')
            points = int(player_brawl.get('points', 0))
            wins = int(player_brawl.get('wins', 0))
            losses = int(player_brawl.get('losses', 0))
            total_battles = wins + losses
            win_rate = (wins / total_battles * 100) if total_battles > 0 else 0

            if _is_placement:
                # Placement Brawl: fixed 25 energy pool, no regen, no wasted tracking
                max_energy    = 25
                storage_limit = 25
                energy_used   = max(0, max_energy - current_energy)
                used_bar      = self._make_bar(energy_used, max_energy, 20)
                icon          = '🎯'
            else:
                # Regular Brawl: 156 max, 13 start + 1/30min regen
                max_energy         = 156
                storage_limit      = 25
                regenerated_energy = time_elapsed // 1800
                total_possible_energy = min(max_energy, 13 + regenerated_energy)
                energy_used        = max(0, total_possible_energy - current_energy)
                wasted_energy      = max(0, energy_used - total_battles)
                used_bar           = self._make_bar(energy_used, max_energy, 20)
                current_bar        = self._make_bar(min(current_energy, storage_limit), storage_limit, 20)
                wasted_str         = f"  │  ⚠ {wasted_energy} wasted" if wasted_energy > 0 else ""
                if not event_ended and total_possible_energy < max_energy and current_energy < storage_limit:
                    regen_str = f" │ Regen in: {30 - ((time_elapsed % 1800) // 60)}min"
                else:
                    regen_str = ""
                icon = '🏆'

            print(f"\n┌─ {icon} {event_name} (ID: {event_id})")
            print(f"│")
            if _is_placement:
                print(f"│  ⚡ Energy:  {used_bar} {energy_used}/{max_energy} used")
            else:
                print(f"│  ⚡ Total:   {used_bar} {energy_used}/{max_energy} used{wasted_str}")
                if not event_ended:
                    print(f"│  ⚡ Current: {current_bar} {current_energy}/{storage_limit}{regen_str}")
            print(f"│  🏅 Rank:    #{rank:,}  |  Points: {points:,}")
            print(f"│  📊 Record:  {wins}W - {losses}L  ({win_rate:.1f}% win rate)")
            if _is_placement:
                print(f"│  ℹ️  Placement Brawl – guild score sets GW start position")
            if event_ended:
                print(f"│  ⏰ Event ended – collect your rewards!")
            else:
                print(f"│  ⏰ Ends:    {days}d {hours}h {minutes}m remaining")
            print(f"│")

            # ===== BRAWL LEADERBOARD =====
            # Placement is always guild-based; otherwise check event name
            _is_guild_brawl = _is_placement or any(w in event_name.lower() for w in ('guild', 'guildbrawl'))
            _lb_title = "Guild Leaderboard" if _is_guild_brawl else "Player Leaderboard"
            print(f"│  ┌─ 🏆 {_lb_title}")
            print(f"│  │")

            try:
                if event_ended:
                    result    = self.api.call('getPreviousBrawlTopLeaderboard')
                    leaderboard = result.get('previous_brawl_leaderboard', []) if result else []
                else:
                    result    = self.api.call('getBrawlLeaderboard')
                    leaderboard = result.get('brawl_leaderboard', []) if result else []

                if leaderboard:
                        user_id_str      = str(player.get('user_id', ''))
                        # faction_id: try player dict first, fall back to user_data
                        _ud = self.init_data.get('user_data', {})
                        user_faction_id  = str(player.get('faction_id', '') or
                                               _ud.get('faction_id', '') or '')
                        user_faction_name = (player.get('faction_name', '') or
                                             _ud.get('faction_name', ''))

                        if _is_guild_brawl:
                            # ── Guild Brawl: show top 10, highlight own guild ──
                            for entry in leaderboard[:10]:
                                rank_num   = entry.get('rank', '?')
                                name       = entry.get('name', 'Unknown')
                                pts        = entry.get('points', '0')
                                faction_id = str(entry.get('faction_id', ''))
                                try:    pts_fmt = f"{int(pts):,}"
                                except: pts_fmt = pts
                                if len(name) > 20: name = name[:17] + "..."
                                star = " ⭐" if faction_id == user_faction_id else ""
                                print(f"│  │  {rank_num:>2}. {name:<20} {pts_fmt:>10}{star}")

                            # Own guild outside top 10?
                            if user_faction_name:
                                in_top = any(str(e.get('faction_id','')) == user_faction_id for e in leaderboard[:10])
                                if in_top:
                                    print(f"│  │")
                                    print(f"│  │  ⭐ = Your guild: {user_faction_name}")
                                else:
                                    for entry in leaderboard:
                                        if str(entry.get('faction_id','')) == user_faction_id:
                                            rn = entry.get('rank','?')
                                            try:    pf = f"{int(entry.get('points','0')):,}"
                                            except: pf = entry.get('points','?')
                                            print(f"│  │")
                                            print(f"│  │  Your guild ({user_faction_name}): Rank #{rn} – {pf} pts")
                                            break
                                    else:
                                        print(f"│  │  ℹ️ Your guild not in leaderboard")

                        else:
                            # ── Regular Brawl: show all returned players (~21-30) ──
                            # API returns entries centered around own rank
                            own_idx = None
                            for i, entry in enumerate(leaderboard):
                                if str(entry.get('user_id','')) == user_id_str:
                                    own_idx = i
                                    break

                            for i, entry in enumerate(leaderboard):
                                rank_num = entry.get('rank', '?')
                                name     = entry.get('name', 'Unknown')
                                pts      = entry.get('points', '0')
                                uid      = str(entry.get('user_id',''))
                                try:    pts_fmt = f"{int(pts):,}"
                                except: pts_fmt = pts
                                if len(name) > 22: name = name[:19] + "..."
                                star = " ◀ YOU" if uid == user_id_str else ""
                                print(f"│  │  {rank_num:>3}. {name:<22} {pts_fmt:>8}{star}")

                else:
                    print(f"│  │  ℹ️ No leaderboard data available")
            except Exception as e:
                print(f"│  │  ⚠️ Leaderboard error: {e}")

            print(f"│  └─")
            print(f"└─")
        
        # ===== PREVIOUS BRAWL LEADERBOARD (no active brawl) =====
        # Buffered - printed at the very end (below Raid) so active events appear first
        _prev_brawl_lines = []
        if not active_brawl or not player_brawl:
            try:
                result = self.api.call('getPreviousBrawlTopLeaderboard')
                leaderboard = result.get('previous_brawl_leaderboard', []) if result else []
                if leaderboard:
                    events_found = True
                    _is_guild_brawl = any(isinstance(e.get('faction_id'), str) or 'faction_id' in e
                                          for e in leaderboard[:3])
                    _lb_title = "Guild Leaderboard" if _is_guild_brawl else "Player Leaderboard"
                    _prev_brawl_lines.append(f"\n┌─ 🏆 Previous Brawl – {_lb_title}")
                    _prev_brawl_lines.append(f"│  │")
                    user_faction_id = str(player.get('faction_id', ''))
                    user_id_str     = str(player.get('user_id', ''))
                    if _is_guild_brawl:
                        for entry in leaderboard[:10]:
                            rank_num   = entry.get('rank', entry.get('points_rank', '?'))
                            name       = entry.get('name', 'Unknown')
                            pts        = entry.get('points', '0')
                            faction_id = str(entry.get('faction_id', ''))
                            try:    pts_fmt = f"{int(pts):,}"
                            except: pts_fmt = pts
                            if len(name) > 20: name = name[:17] + "..."
                            star = " ⭐" if faction_id == user_faction_id else ""
                            _prev_brawl_lines.append(f"│  │  {rank_num:>2}. {name:<20} {pts_fmt:>10}{star}")
                        user_faction_name = player.get('faction_name', '')
                        if user_faction_name:
                            in_top = any(str(e.get('faction_id','')) == user_faction_id for e in leaderboard[:10])
                            if not in_top:
                                for entry in leaderboard:
                                    if str(entry.get('faction_id','')) == user_faction_id:
                                        rn = entry.get('rank', entry.get('points_rank','?'))
                                        try:    pf = f"{int(entry.get('points','0')):,}"
                                        except: pf = entry.get('points','?')
                                        _prev_brawl_lines.append(f"│  │")
                                        _prev_brawl_lines.append(f"│  │  Your guild ({user_faction_name}): Rank #{rn} – {pf} pts")
                                        break
                    else:
                        for entry in leaderboard:
                            rank_num = entry.get('rank', '?')
                            name     = entry.get('name', 'Unknown')
                            pts      = entry.get('points', '0')
                            uid      = str(entry.get('user_id',''))
                            try:    pts_fmt = f"{int(pts):,}"
                            except: pts_fmt = pts
                            if len(name) > 22: name = name[:19] + "..."
                            star = " ◀ YOU" if uid == user_id_str else ""
                            _prev_brawl_lines.append(f"│  │  {rank_num:>3}. {name:<22} {pts_fmt:>8}{star}")
                    _prev_brawl_lines.append(f"│  └─")
                    _prev_brawl_lines.append(f"└─")
            except Exception:
                pass  # silently skip if no previous brawl data available

        # ===== RAID EVENT =====
        # Try init_data first; if missing, call getRaidInfo separately
        _raid_info = self.init_data.get('raid_info') or {}
        if not _raid_info:
            try:
                _ri_result = self.api.call('getRaidInfo')
                _raid_info = (_ri_result or {}).get('raid_info', {})
            except Exception:
                _raid_info = {}

        if _raid_info:
            for raid_id, raid_data in _raid_info.items():
                events_found = True
                # Name: try current_raids lookup, else generic
                raid_name = 'Raid'
                if current_raids and raid_id in current_raids:
                    raid_name = current_raids[raid_id].get('name', 'Raid Event')

                raid_level   = raid_data.get('raid_level', '?')
                current_time = int(time.time())

                # ── Boss Health ───────────────────────────────────────────
                current_health = int(raid_data.get('health', 0))
                max_health     = int(raid_data.get('max_health', 1))
                health_pct     = (current_health / max_health * 100) if max_health > 0 else 0
                health_bar     = self._make_bar(current_health, max_health, 20, '█', '░')

                # ── Energy ───────────────────────────────────────────────
                energy_data     = raid_data.get('energy', {})
                current_energy  = int(energy_data.get('battle_energy', 0))
                storage_limit   = int(energy_data.get('max_battle_energy', 25))
                recharge_time   = int(energy_data.get('battle_energy_recharge_time', 1800))
                recharge_start  = int(energy_data.get('battle_energy_recharge_start_time', 0))
                recharge_stop   = int(energy_data.get('battle_energy_recharge_stop_time', 0))
                next_regen_tick = int(energy_data.get('battle_energy_update_time', 0))

                # Total energy pool for the entire event
                if recharge_start and recharge_stop and recharge_time:
                    event_duration    = recharge_stop - recharge_start
                    total_regen_ticks = event_duration // recharge_time
                    max_total_energy  = 13 + total_regen_ticks   # 13 starting energy
                else:
                    max_total_energy = 169  # fallback

                # Energy used since event start
                event_elapsed      = max(0, current_time - recharge_start) if recharge_start else 0
                regen_so_far       = event_elapsed // recharge_time if recharge_time else 0
                total_possible     = min(max_total_energy, 13 + regen_so_far)
                energy_used        = max(0, total_possible - current_energy)

                # ── Level timing ─────────────────────────────────────────
                level_start_time = int(raid_data.get('raid_level_start', 0))
                level_end_time   = int(raid_data.get('raid_level_end', 0))
                time_remaining   = max(0, level_end_time - current_time)
                lvl_hours        = time_remaining // 3600
                lvl_minutes      = (time_remaining % 3600) // 60

                # ── Status ───────────────────────────────────────────────
                status     = str(raid_data.get('status', '0'))
                raid_ended = time_remaining == 0 or status != '0'

                # ── Regen countdown ──────────────────────────────────────
                if (not raid_ended
                        and total_possible < max_total_energy
                        and current_energy < storage_limit):
                    if next_regen_tick > current_time:
                        mins_to_regen = (next_regen_tick - current_time) // 60
                        secs_to_regen = (next_regen_tick - current_time) % 60
                        regen_str = f"  │  Regen in: {mins_to_regen}m {secs_to_regen:02d}s"
                    elif recharge_start and recharge_time:
                        # server tick slightly in the past - compute next expected tick
                        ticks_elapsed = max(0, (current_time - recharge_start) // recharge_time)
                        next_computed = recharge_start + (ticks_elapsed + 1) * recharge_time
                        secs_left = max(0, next_computed - current_time)
                        mins_to_regen = secs_left // 60
                        secs_to_regen = secs_left % 60
                        regen_str = f"  │  Regen in: {mins_to_regen}m {secs_to_regen:02d}s"
                    else:
                        regen_str = "  │  Regen: <1m"
                else:
                    regen_str = ""

                # ── Guild member damage ──────────────────────────────────
                user_id_str  = str(player.get('user_id', ''))
                members      = raid_data.get('members', {})
                own_damage   = 0
                if user_id_str in members:
                    own_damage = int(members[user_id_str].get('damage', 0))
                total_damage = sum(int(m.get('damage', 0)) for m in members.values())

                # Sorted member list (damage desc)
                sorted_members = sorted(
                    members.values(),
                    key=lambda m: int(m.get('damage', 0)),
                    reverse=True
                )

                # ── Bars ─────────────────────────────────────────────────
                current_bar = self._make_bar(min(current_energy, storage_limit), storage_limit, 20)
                used_bar    = self._make_bar(energy_used, max_total_energy, 20)

                # ── Print header ─────────────────────────────────────────
                print(f"\n┌─ 🐉 {raid_name}  –  Level {raid_level}")
                print(f"│")
                print(f"│  ⚡ Total:    {used_bar} {energy_used}/{max_total_energy} used")
                if not raid_ended:
                    print(f"│  ⚡ Current:  {current_bar} {current_energy}/{storage_limit}{regen_str}")
                print(f"│  ❤️ Boss HP:  {health_bar} {health_pct:.1f}%")
                print(f"│              {current_health:,} / {max_health:,}")
                if raid_ended:
                    print(f"│  ⏰ Level ended – collect your rewards!")
                else:
                    print(f"│  ⏰ Level ends: {lvl_hours}h {lvl_minutes}m remaining")
                print(f"│")

                # ── Guild damage leaderboard ──────────────────────────────
                print(f"│  ┌─ ⚔️  Guild Damage – Level {raid_level}")
                print(f"│  │")
                for i, m in enumerate(sorted_members, 1):
                    mid    = str(m.get('member_id', ''))
                    mname  = m.get('member_name', 'Unknown')
                    dmg    = int(m.get('damage', 0))
                    you    = "  ◀ YOU" if mid == user_id_str else ""
                    if len(mname) > 22: mname = mname[:19] + "..."
                    print(f"│  │  {i:>2}. {mname:<22} {dmg:>6,}{you}")
                print(f"│  │")
                dmg_pct = (own_damage / total_damage * 100) if total_damage > 0 else 0
                print(f"│  │  Total: {total_damage:,}  │  Your share: {own_damage:,} ({dmg_pct:.1f}%)  │  Members: {len(members)}")
                print(f"│  └─")
                print(f"└─")
        
        # ===== GUILD WAR =====
        awe = self.init_data.get('active_war_event', {})
        if awe:
            events_found = True
            war_name = awe.get('name', 'Guild War')
            war_id   = awe.get('id', '?')
            war_end  = int(awe.get('end_time', 0))
            now_t    = int(time.time())
            war_remaining = max(0, war_end - now_t)
            wd = war_remaining // 86400
            wh = (war_remaining % 86400) // 3600
            wm = (war_remaining % 3600) // 60

            # Overall event stats from faction_war_event_info
            fwei       = self.init_data.get('faction_war_event_info', {})
            if isinstance(fwei, list):
                fwei = fwei[0] if fwei else {}
            own_fid    = str(fwei.get('faction_id', ''))
            total_pts  = int(fwei.get('faction_war_points', 0))
            our_rank   = fwei.get('our_rank', '?')
            war_wins   = int(fwei.get('wins', 0))
            war_losses = int(fwei.get('losses', 0))
            own_guild  = self.init_data.get('user_data', {}).get('faction_name', '')

            print(f"\n┌─ ⚔️  {war_name} (ID: {war_id})")
            print(f"│")
            if war_remaining > 0:
                print(f"│  ⏰ Ends:     {wd}d {wh}h {wm}m remaining")
            else:
                print(f"│  ⏰ War ended")
            print(f"│  🏅 Rank:     #{our_rank}  │  Total Points: {total_pts:,}")
            print(f"│  📊 Record:   {war_wins}W – {war_losses}L")
            print(f"│")

            # Current match from faction_war
            try:
                fw_result = self.api.call('updateFactionWar')
                fw = (fw_result or {}).get('faction_war') if fw_result else None
            except Exception:
                fw = None

            if fw and isinstance(fw, dict):
                att_id     = str(fw.get('attacker_faction_id', ''))
                i_am_att   = (att_id == own_fid)
                att_name   = fw.get('attacker_faction_name', '?')
                def_name   = fw.get('defender_faction_name', '?')
                att_pts    = int(fw.get('attacker_faction_points', 0))
                def_pts    = int(fw.get('defender_faction_points', 0))
                my_pts_m   = att_pts if i_am_att else def_pts
                en_pts_m   = def_pts if i_am_att else att_pts
                en_name    = def_name if i_am_att else att_name
                m_start    = int(fw.get('start_time', 0))
                m_end      = int(fw.get('end_time', 0))
                m_rem      = max(0, m_end - now_t)
                mh         = m_rem // 3600
                mm2        = (m_rem % 3600) // 60
                prep_end   = m_start + 1800
                in_prep    = now_t < prep_end

                # BGEs
                def _bge_from_section(section):
                    if not isinstance(section, dict): return None
                    for bid, bi in section.items():
                        if bid and isinstance(bi, dict) and bi.get('name'):
                            return bi['name']
                    return None

                bge_effects = fw_result.get('faction_war', {}) if fw_result else {}
                # BGE from battleground_effects in playCard response - use updateFactionWar
                att_bg = fw.get('attacker_faction_battleground', {})
                def_bg = fw.get('defender_faction_battleground', {})
                # resolve via battleground_data
                bd = {}
                try:
                    fr2 = self.api.call('updateFaction')
                    bd  = (fr2 or {}).get('faction', {}).get('battleground_data', {}) if fr2 else {}
                except Exception:
                    pass

                def _resolve_bge(bg_field, bdata):
                    if not isinstance(bg_field, dict): return None
                    bid = str(bg_field.get('id', ''))
                    if not bid or not bdata: return None
                    bi = bdata.get(bid, {})
                    return bi.get('name') if isinstance(bi, dict) else None

                my_bge = _resolve_bge(att_bg if i_am_att else def_bg, bd)
                en_bge = _resolve_bge(def_bg if i_am_att else att_bg, bd)

                # In prep phase BGEs may not be activated yet
                bge_unknown = in_prep and not my_bge and not en_bge
                if bge_unknown:
                    bge_note = ' (preparation phase)'
                else:
                    bge_note = ''

                print(f"│  ┌─ ⚔️  Current Match  vs {en_name}")
                print(f"│  │")
                if in_prep:
                    prep_rem = max(0, prep_end - now_t)
                    print(f"│  │  🔔 Preparation phase - {prep_rem//60}m {prep_rem%60:02d}s remaining")
                else:
                    print(f"│  │  ⏱  {mh:02d}h {mm2:02d}m remaining")
                print(f"│  │  Score: {my_pts_m:,} : {en_pts_m:,}  {'✓ Leading' if my_pts_m > en_pts_m else ('✗ Behind' if my_pts_m < en_pts_m else '= Tied')}")
                print(f"│  │  🟦 Our BGE:   {my_bge if my_bge else ('unknown' + bge_note)}")
                print(f"│  │  🟧 Enemy BGE: {en_bge if en_bge else ('unknown' + bge_note)}")

                # Battle energy
                battle_energy = int(fw.get('battle_energy', 0))
                max_be        = int(fw.get('max_battle_energy', 20))
                be_bar        = self._make_bar(battle_energy, max_be, 15)
                print(f"│  │  ⚡ Energy:  {be_bar} {battle_energy}/{max_be}")
                print(f"│  └─")

            # Overall ranking (top 10)
            try:
                rank_result  = self.api.call('getFactionWarLeaderboard', war_event_id=str(war_id))
                leaderboard  = (rank_result or {}).get('faction_war_leaderboard', []) if rank_result else []
            except Exception:
                leaderboard = []

            if leaderboard:
                print(f"│  ┌─ 🏆 Overall Ranking")
                print(f"│  │")
                for entry in leaderboard[:10]:
                    rn   = entry.get('rank', entry.get('our_rank', '?'))
                    name = entry.get('name', entry.get('faction_name', 'Unknown'))
                    pts  = entry.get('faction_war_points', entry.get('points', 0))
                    fid  = str(entry.get('faction_id', ''))
                    try: pts_fmt = f"{int(pts):,}"
                    except: pts_fmt = str(pts)
                    if len(str(name)) > 20: name = str(name)[:17] + "..."
                    star = " ⭐" if fid == own_fid else ""
                    print(f"│  │  {rn:>3}. {name:<20} {pts_fmt:>10}{star}")
                # Own guild outside top 10?
                if own_fid:
                    in_top = any(str(e.get('faction_id','')) == own_fid for e in leaderboard[:10])
                    if not in_top:
                        for entry in leaderboard:
                            if str(entry.get('faction_id','')) == own_fid:
                                rn  = entry.get('rank', fwei.get('our_rank', '?'))
                                try: pf = f"{int(entry.get('faction_war_points', total_pts)):,}"
                                except: pf = str(total_pts)
                                print(f"│  │")
                                print(f"│  │  Your guild ({own_guild}): Rank #{rn} – {pf} pts")
                                break
                        else:
                            # Use data from faction_war_event_info
                            print(f"│  │")
                            print(f"│  │  Your guild ({own_guild}): Rank #{our_rank} – {total_pts:,} pts")
                print(f"│  └─")
            elif fwei:
                # Fallback: just show own rank from init
                print(f"│  ┌─ 🏆 Your Standing")
                print(f"│  │  Rank #{our_rank}  │  {total_pts:,} pts")
                print(f"│  └─")

            print(f"└─")

        # ===== NO EVENTS =====
        if not events_found:
            print("\n╭───────────────────────────────────────╮")
            print("│  ℹ️  No active events at the moment   │")
            print("│                                       │")
            print("│  Check back later for new events!    │")
            print("╰───────────────────────────────────────╯")

        # ===== PREVIOUS BRAWL (deferred – always last) =====
        for _line in _prev_brawl_lines:
            print(_line)
        
        print("\n" + "="*70)
        input("\n[ENTER] to continue...")
    
    def _make_bar(self, current, maximum, width=20, fill_char='█', empty_char='─'):
        """Helper to create a visual progress bar"""
        if maximum == 0:
            return empty_char * width
        
        filled = int((current / maximum) * width)
        
        # Show at least 1 filled char if current > 0 (for better visibility)
        if current > 0 and filled == 0:
            filled = 1
        
        filled = max(0, min(width, filled))
        empty = width - filled
        
        return fill_char * filled + empty_char * empty

    # ---------- Inventory: ownedcards.txt & currentdecks.txt ----------

    def get_inventory(self):
        """
        Creates ownedcards.txt and currentdecks.txt – analogous to PS1 script,
        but entirely via the API (init data).

        ownedcards.txt:
            - Sorted by fusion groups (Vindicator -> Bloodthirsty -> Imperial
              -> Raider -> Righteous -> Xeno -> Rest)
            - Each group with a //comment-header
            - Per Card: "Name-Level" or "Name-Level (count)" if >1
            - At the end: "//cards from restore" + buyback_data entries

        currentdecks.txt:
            - Per Deck one line:
              "DeckName:Commander,Dominion,Card1,Card2 #count,..."
            - Active deck marked with [A], defense with [D]
        """
        # Refresh data to get current state
        self.initialize(verbose=False)
        
        try:
            print("\n=== EXPORT INVENTORY - START ===")
            

            card_data = self._load_card_data()
            if not card_data:
                print("✗ Cannot continue without card data.")
                return

            print(f"✓ {len(card_data)} cards loaded")
            print("\n⏳ Processing inventory...")

            # ----------------------------------------------------------
            # A) ownedcards.txt
            # ----------------------------------------------------------
            user_cards  = self.init_data.get('user_cards', {})
            buyback     = self.init_data.get('buyback_data', {})

            print(f"   User has {len(user_cards)} card entries")
            
            # Gruppen-Buckets initialize
            buckets = {i: [] for i in range(len(FUSION_GROUPS))}
            buckets[-1] = []   # Rest

            print("   Classifying cards...")
            for card_id, info in user_cards.items():
                card_id_int = int(card_id)
                
                # NO filter anymore - all cards are exported
                # (so Dominion Shards, Dominions and Commanders)
                
                num_owned = int(info.get('num_owned', 0))
                if num_owned <= 0:
                    continue

                name = self._resolve_card(card_id, card_data)

                # count append if >1
                line = name if num_owned == 1 else f"{name} ({num_owned})"

                group_idx = self._classify_fusion(name)
                buckets[group_idx].append(line)

            # assemble file
            print("   Building ownedcards.txt...")
            owned_lines = []
            for idx, (group_name, _) in enumerate(FUSION_GROUPS):
                owned_lines.append(f"//{group_name}")
                owned_lines.extend(buckets[idx])
                owned_lines.append("")          # empty line between groups

            # Rest (no group)
            owned_lines.extend(buckets[-1])

            # Buyback-Anhatg ("cards from restore")
            print("   Processing Buyback data...")
            owned_lines.append("")
            owned_lines.append("//cards from restore")
            for card_id, bb_info in buyback.items():
                number = int(bb_info.get('number', 0))
                if number <= 0:
                    continue
                name = self._resolve_card(card_id, card_data)
                line = name if number == 1 else f"{name} ({number})"
                owned_lines.append(line)

            # Schreiben
            print("   Writing ownedcards.txt...")
            
            # Write in script directory, not in current working directory
            account_name = self.api.settings.get('request_data', {}).get('kong_name', '')                           or self.init_data.get('user_data', {}).get('name', 'unknown')
            # Sanitize for filename
            safe_name = "".join(c if c.isalnum() or c in ('-', '_') else '_' for c in account_name)
            ownedcards_dir = os.path.join(SCRIPT_DIR, "ownedcards")
            os.makedirs(ownedcards_dir, exist_ok=True)
            owned_path = os.path.join(ownedcards_dir, f"{safe_name}.txt")
            print(f"   Target: {owned_path}")
            
            # Delete old file if present
            if os.path.exists(owned_path):
                try:
                    print(f"   Deleting old file...")
                    os.remove(owned_path)
                    print(f"   ✓ Old file deleted")
                except Exception as e:
                    print(f"   ⚠ Could not delete old file: {e}")
                    raise
            
            # Create new file
            try:
                print(f"   Creating new file...")
                with open(owned_path, 'w', encoding='ascii', errors='replace') as f:
                    f.write("\n".join(owned_lines))
                print(f"✓ {os.path.basename(owned_path)} written ({sum(len(b) for b in buckets.values())} cards)")
                    
            except PermissionError as e:
                raise PermissionError(
                    f"Cannot write '{owned_path}'. "
                    f"Check folder permissions for '{SCRIPT_DIR}'"
                ) from e

            # ----------------------------------------------------------
            # B) currentdecks.txt
            # ----------------------------------------------------------
            print("\n⏳ Processing Decks...")
            user_decks   = self.init_data.get('user_decks', {})
            active_deck  = str(self.init_data.get('user_data', {}).get('active_deck', ''))
            defense_deck = str(self.init_data.get('user_data', {}).get('defense_deck', ''))

            print(f"   User has {len(user_decks)} Decks")
            deck_lines = []
            for deck_id, deck in user_decks.items():
                # Deck-Name
                deck_name = deck.get('name') or f"Deck{deck_id}"

                # Marker
                marks = []
                if str(deck_id) == active_deck:  marks.append("A")
                if str(deck_id) == defense_deck: marks.append("D")
                mark_str = f" [{'/'.join(marks)}]" if marks else ""

                # Commander
                commander = self._resolve_card(deck.get('commander_id') or '0', card_data)

                # Dominion (optional)
                dominion_id = deck.get('dominion_id')
                dominion    = self._resolve_card(dominion_id, card_data) if dominion_id else ""

                # Cards with count
                # deck['cards'] can be a dict {card_id: count} or a list [card_id, ...]
                card_parts = []
                raw_cards = deck.get('cards', {})
                if isinstance(raw_cards, dict):
                    cards_iter = raw_cards.items()
                elif isinstance(raw_cards, list):
                    # List format: each entry is a card_id (count=1)
                    cards_iter = [(cid, 1) for cid in raw_cards]
                else:
                    cards_iter = []
                for cid, count in cards_iter:
                    cname = self._resolve_card(str(cid), card_data)
                    count = int(count)
                    card_parts.append(f"{cname} #{count}" if count > 1 else cname)

                # Line assemble / build: Name:Commander,Dominion,Cards...
                parts = [commander]
                if dominion:
                    parts.append(dominion)
                parts.extend(card_parts)

                line = f"{deck_name}{mark_str}:{','.join(parts)}"
                deck_lines.append(line)

            # Schreiben
            print("   Writing currentdecks.txt...")
            
            # Write in script directory
            decks_path = os.path.join(ownedcards_dir, f"currentdecks_{safe_name}.txt")
            print(f"   Target: {decks_path}")
            
            # Delete old file if present
            if os.path.exists(decks_path):
                try:
                    print(f"   Deleting old file...")
                    os.remove(decks_path)
                    print(f"   ✓ Old file deleted")
                except Exception as e:
                    print(f"   ⚠ Could not delete old file: {e}")
                    raise
            
            # Create new file
            try:
                print(f"   Creating new file...")
                with open(decks_path, 'w', encoding='ascii', errors='replace') as f:
                    f.write("\n".join(deck_lines))
                print(f"✓ {os.path.basename(decks_path)} written ({len(deck_lines)} Decks)")
                    
            except PermissionError as e:
                raise PermissionError(
                    f"Cannot write '{decks_path}'. "
                    f"Check folder permissions for '{SCRIPT_DIR}'"
                ) from e

            # Summary
            print(f"\n=== SUMMARY ===")
            print(f"✓ {safe_name}.txt: {len(owned_lines)} lines")
            print(f"✓ currentdecks_{safe_name}.txt: {len(deck_lines)} Decks")
            print(f"\n=== INVENTORY EXPORT - COMPLETE ===")
            
        except Exception as e:
            print(f"\n{'='*60}")
            print(f"CRITICAL ERROR in get_inventory():")
            print(f"{'='*60}")
            print(f"Error type: {type(e).__name__}")
            print(f"Error message: {e}")
            print(f"\nStacktrace:")
            traceback.print_exc()
            print(f"{'='*60}")
            print("\nPress Enter to continue...")
            input()
    
    def get_buyback_info(self):
        """
        Returns information about BuybackCards back
        
        Returns:
            dict: {card_id: {'name': str, 'number': int, 'rarity': int, 'tier': int, 'cost': int}}
        """
        # Refresh data to get current state
        self.initialize(verbose=False)
        
        buyback_data = self.init_data.get('buyback_data', {})
        if not buyback_data:
            print(f"✗ Buyback store is empty or could not be loaded")
            return {}
        
        card_data = self._load_card_data_with_rarity()
        result = {}
        
        for card_id, bb_info in buyback_data.items():
            number = int(bb_info.get('number', 0))
            if number <= 0:
                continue
            
            # Get card information
            card_info = card_data.get(int(card_id), {
                'name': f'ID_{card_id}',
                'level': 1,
                'rarity': 3,
                'tier': 0,
                'fusion_tier': 0
            })
            
            # Costs based on Rarity AND Fusion-Tier calculate
            rarity = card_info.get('rarity', 3)
            fusion_tier = card_info.get('fusion_tier', 0)
            level = card_info.get('level', 1)
            
            # Get costs from BUYBACK_COSTS Dictionary
            cost_per_card = BUYBACK_COSTS.get((rarity, fusion_tier), 0)
            
            # Fallback if Kombination not existiert
            if cost_per_card == 0:
                # Try with Tier 0
                cost_per_card = BUYBACK_COSTS.get((rarity, 0), 20)
            
            result[card_id] = {
                'name': f"{card_info['name']}-1",  # Always Level 1 in Buyback store
                'base_name': card_info['name'],  # Original name for search
                'number': number,
                'rarity': rarity,
                'tier': fusion_tier,  # Now fusion_tier
                'rarity_name': RARITY_NAMES.get(rarity, 'Unknown'),
                'cost_per_card': cost_per_card,
                'total_cost': cost_per_card * number
            }
        
        return result
    
    def buyback_card(self, card_name_or_id, quantity=1):
        """
        Purchases a card back from the buyback store

        Args:
            card_name_or_id: Name or ID of the card (e.g. "Infernal Walker" or 50123)
            quantity: Number of Cards (default: 1)

        Returns:
            API response, or None on error
        """
        try:
            # Resolve name -> ID if necessary
            if isinstance(card_name_or_id, str) and not card_name_or_id.isdigit():
                card_id = self._find_buyback_card_id_by_name(card_name_or_id)
                if card_id is None:
                    print(f"✗ Card '{card_name_or_id}' not found in buyback store")
                    return None
            else:
                card_id = int(card_name_or_id)

            buyback_info = self.get_buyback_info()

            if str(card_id) not in buyback_info:
                print(f"✗ Card ID {card_id} is not in the buyback store")
                return None

            info = buyback_info[str(card_id)]
            available = info['number']

            # Validate quantity
            if quantity == 0:
                quantity = available
            elif quantity > available:
                print(f"✗ Only {available}x {info['name']} available in buyback store (requested: {quantity}x)")
                return None

            # SP check
            cost = info['cost_per_card'] * quantity
            current_sp = self.get_salvage()
            if current_sp < cost:
                print(f"✗ Not enough SP: {cost:,} required, {current_sp:,} available")
                return None

            # API call
            result = self.api.call('buybackCard', card_id=card_id, number=quantity)

            # Success check: API does not return a 'result' field for buybackCard –
            # success is indicated by presence of user_data.salvage or buyback_data
            success = False
            if result and isinstance(result, dict):
                if result.get('result') in [True, 1, "1", "true", "True"]:
                    success = True
                elif 'user_data' in result and 'salvage' in result.get('user_data', {}):
                    success = True
                elif 'buyback_data' in result:
                    success = True

            if success:
                print(f"✓ {quantity}x {info['name']} for {cost:,} SP bought back")
                if 'user_data' in result and 'salvage' in result['user_data']:
                    print(f"  Remaining SP: {int(result['user_data']['salvage']):,}")
                else:
                    print(f"  Remaining SP: {current_sp - cost:,} (estimated)")

                # Update cached init_data so subsequent calls see current values
                if 'user_data' in result:
                    self.init_data['user_data'].update(result['user_data'])
                if 'buyback_data' in result:
                    self.init_data['buyback_data'] = result['buyback_data']

                print(f"\n✓ Restore successful: {quantity}x {info['name']}")
                return result
            else:
                self._print_api_error(result, "Buyback")
                print(f"\n✗ Restore failed: {info['name']}")
                return None

        except Exception as e:
            print(f"✗ Unexpected error during buyback: {e}")
            return None
    
    def _find_buyback_card_id_by_name(self, card_name):
        """
        Finds the card ID in the buyback store by name.
        Buyback cards are ALWAYS Level 1, so any level suffix (-1 to -6)
        is stripped before searching (e.g. "Agayasa-6" -> "Agayasa").
        
        Args:
            card_name: Name of the card, with or without level suffix
                       (e.g. "Agayasa", "Agayasa-6", "Lucifire-1")
        
        Returns:
            card_id as int, or None if not found
        """
        buyback_info = self.get_buyback_info()
        
        # Strip any level suffix "-1" through "-6" (Buyback is always Level 1)
        import re
        card_name_clean = card_name.strip()
        card_name_clean = re.sub(r'-[1-6]$', '', card_name_clean)
        
        card_name_lower = card_name_clean.lower()
        
        # Exact match against base_name
        for card_id, info in buyback_info.items():
            if info['base_name'].lower() == card_name_lower:
                return int(card_id)
        
        # Substring search (if exact match not found)
        matches = []
        for card_id, info in buyback_info.items():
            if card_name_lower in info['base_name'].lower():
                matches.append((card_id, info['name']))  # Show name with -1 suffix
        
        if len(matches) == 1:
            card_id = matches[0][0]
            print(f"✓ Found: {matches[0][1]} (ID: {card_id})")
            return int(card_id)
        elif len(matches) > 1:
            print(f"✗ Multiple cards found for '{card_name}':")
            for card_id, name in matches[:5]:  # Show max 5
                print(f"   [{card_id}] {name}")
            return None
        
        return None
    
    def get_gold(self):
        """Returns current Gold from init_data"""
        # Refresh data to get current state
        self.initialize(verbose=False)
        return int(self.init_data.get('user_data', {}).get('money', 0))
    
    def get_salvage(self):
        """Returns current SP from init_data"""
        # Refresh data to get current state
        self.initialize(verbose=False)
        return int(self.init_data.get('user_data', {}).get('salvage', 0))
    
    def get_sp_cap(self):
        """
        Returns the SP cap (maximum salvage) for this account.
        Reads from already-loaded init_data (no extra API call).
        Field: user_data.caps.max_salvage
        """
        if not self.init_data:
            self.initialize(verbose=False)

        user_data = self.init_data.get('user_data', {})
        caps = user_data.get('caps', {})

        # Primary: caps.max_salvage (confirmed API field)
        try:
            cap = int(caps.get('max_salvage', 0))
            if cap > 0:
                return cap
        except (ValueError, TypeError):
            pass

        # Fallback: direct user_data fields
        for field in ['salvage_max', 'max_salvage', 'salvage_cap', 'salvage_limit', 'sp_max']:
            try:
                cap = int(user_data.get(field, 0))
                if cap > 0:
                    return cap
            except (ValueError, TypeError):
                continue

        return SP_MAX_FALLBACK

    # ---------- Packages ----------

    def buy_pack(self):
        """Buys the 2000-Gold package once (buyStorePromoGold)"""
        try:
            result = self.api.call(
                'buyStorePromoGold',
                expected_cost=PACK_COST,
                item_id=PACK_ITEM_ID,
                item_type=PACK_ITEM_TYPE
            )
            if result and result.get('result') in (True, 1, '1', 'true'):
                return True, result.get('new_cards', [])
            else:
                return False, []
        except Exception as e:
            print(f"✗ Purchase failed: {e}")
            return False, []

    def buy_packs(self, count, silent=False):
        """
        Buys multiple packages in sequence with delay.

        Args:
            count:  Number of packages to buy
            silent: If True, only show progress bar (for use in workflows)

        Returns:
            (purchased: int, all_new_cards: list)
        """
        if not silent:
            print(f"\n{'='*50}")
            print(f" BUYING {count}x 2000-GOLD PACKAGE")
            print(f"{'='*50}")

        gold_before = self.get_gold()
        if not silent:
            print(f" Gold before   : {gold_before:,}")
            print(f" Total cost    : {count * PACK_COST:,}")

        if gold_before < count * PACK_COST:
            if not silent:
                print(f"\n ✗ Not enough Gold!")
                print(f"   Required  : {count * PACK_COST:,}")
                print(f"   Available : {gold_before:,}")
            else:
                print(f"  ✗ Not enough Gold ({gold_before:,} / {count * PACK_COST:,} required)")
            return 0, []

        purchased = 0
        all_cards = []

        bar_length = 40
        print()  # New line for progress bar
        for i in range(1, count + 1):
            filled = int((i / count) * bar_length)
            bar = '█' * filled + '░' * (bar_length - filled)
            label = "  Buying" if silent else " "
            print(f"\r{label} [{bar}] {i}/{count}", end='', flush=True)

            success, new_cards = self.buy_pack()
            if success:
                purchased += 1
                all_cards.extend(new_cards)
            if i < count:
                sleep(DELAY_BETWEEN_BUYS)

        bar = '█' * bar_length
        print(f"\r{'  Buying' if silent else ' '} [{bar}] {count}/{count}")

        self.initialize(verbose=False)
        gold_after = self.get_gold()

        if not silent:
            print(f"\n{'─'*50}")
            print(f" Purchased     : {purchased}/{count}")
            print(f" Gold after    : {gold_after:,}")
            print(f" Gold spent    : {gold_before - gold_after:,}")
            print(f" New cards     : {len(all_cards)}")
            print(f"{'─'*50}")

        return purchased, all_cards

    # ---------- Batch-Salvage ----------

    def salvage_all_commons(self, silent=False):
        """
        Salvages ALL L1 Common Cards at once (salvageL1CommonCards).
        Server calculates everything - no ID list needed.

        Returns:
            (success: bool, sp_gain: int)
        """
        self.initialize(verbose=False)

        if not silent:
            print(f"\n{'='*50}")
            print(f" SALVAGE ALL COMMON CARDS")
            print(f"{'='*50}")

        salvage_before = int(self.init_data.get('user_data', {}).get('salvage', 0))
        if not silent:
            print(f" Salvage before: {salvage_before:,} SP")
        
        # Unlock locked commons before bulk salvage - but skip protected ingredients
        _protected = getattr(self, '_protected_card_ids', set())
        user_cards = self.init_data.get('user_cards', {})
        card_data_uc = self._load_card_data_with_rarity()
        common_locked = [
            int(cid) for cid, info in user_cards.items()
            if isinstance(info, dict) and info.get('is_locked')
            and int(cid) not in _protected
            and card_data_uc.get(int(cid), {}).get('rarity') == 1
            and card_data_uc.get(int(cid), {}).get('level', 1) == 1
        ]
        if common_locked:
            self._unlock_locked_cards(common_locked)

        # SP LIMIT CHECK
        sp_cap = self.get_sp_cap()

        if salvage_before >= sp_cap:
            if not silent:
                print(f"\n ⚠ SP already at maximum ({sp_cap:,}) - salvage aborted")
                print(f"   Cards would be destroyed without giving SP!")
            return False, 0

        try:
            result = self.api.call('salvageL1CommonCards', dummy='data')

            if result and result.get('result') in (True, 1, '1', 'true'):
                salvage_after = int(result.get('user_data', {}).get('salvage', 0))
                sp_gain       = salvage_after - salvage_before

                if not silent:
                    if salvage_after >= sp_cap and sp_gain == 0:
                        print(f" ⚠ SP cap reached - cards salvaged but no SP gained (cap: {sp_cap:,})")
                    print(f" ✓ Salvage done: {salvage_after:,} SP (+{sp_gain:,})")
                    print(f"{'-'*50}")

                self.init_data = result
                return True, sp_gain
            else:
                if not silent:
                    print(" ✗ Salvage failed")
                return False, 0

        except Exception as e:
            if not silent:
                print(f" ✗ Error: {e}")
            return False, 0

