    # ---------- Workflow: Buy + Salvage ----------

    def fill_sp_to_cap(self, silent=False):
        """Fill SP to cap: buy 10 packs + salvage commons/rares/base epics in a loop.
        Stops when SP >= cap - 400 (too close to cap for another round) or Gold runs out."""
        PACKS_PER_ROUND = 10

        self.initialize(verbose=False)
        sp_cap = self.get_sp_cap()
        nick   = (self.api.settings.get('request_data', {}).get('kong_name', '')
                  or self.api.settings.get('kong_name', ''))

        if not silent:
            print(f"\n{'='*60}")
            print(f"  FILL SP TO CAP  —  {nick}")
            print(f"{'='*60}")

        round_num = 0
        initial_salvage_done = False

        while True:
            # Step 1: check SP cap
            self.initialize(verbose=False)
            sp_now = int(self.init_data.get('user_data', {}).get('salvage', 0))

            if sp_now >= sp_cap - 600:
                print(f"  {'✓' if sp_now >= sp_cap else '⚠'} SP at {sp_now:,}/{sp_cap:,} — within 600 of cap, stopping")
                break

            # Step 2: initial salvage (once, before first pack buy) to free inventory
            if not initial_salvage_done:
                print(f"  Initial salvage to free inventory...")
                self.salvage_all_commons(silent=True)
                self.salvage_all_rares(silent=True)
                self.salvage_base_epics_keep_x(keep_count=10, silent=True, auto_confirm=True)
                initial_salvage_done = True
                self.initialize(verbose=False)
                sp_now = int(self.init_data.get('user_data', {}).get('salvage', 0))
                if sp_now >= sp_cap - 600:
                    print(f"  ⚠ SP at {sp_now:,}/{sp_cap:,} — within 600 of cap after initial salvage, stopping")
                    break

            # Step 3: check inventory space (10 packs × 20 cards = 200 slots)
            max_packs, free_slots = self.calculate_max_packs()
            if max_packs < PACKS_PER_ROUND:
                print(f"  ✗ Not enough inventory space ({free_slots} free slots, need {PACKS_PER_ROUND * 20}) — stopping")
                break

            gold = self.get_gold()
            round_num += 1
            print(f"\n  Round {round_num}  │  SP: {sp_now:,}/{sp_cap:,}  │  Gold: {gold:,}")

            bought, _ = self.buy_packs(PACKS_PER_ROUND, silent=True)
            if bought < PACKS_PER_ROUND:
                print(f"  ✗ Only bought {bought}/{PACKS_PER_ROUND} packs (Gold insufficient or inventory full?) — stopping")
                break

            self.salvage_all_commons(silent=True)
            self.salvage_all_rares(silent=True)
            self.salvage_base_epics_keep_x(keep_count=10, silent=True, auto_confirm=True)

            self.initialize(verbose=False)
            sp_after = int(self.init_data.get('user_data', {}).get('salvage', 0))
            print(f"  SP: {sp_now:,} → {sp_after:,} (+{sp_after - sp_now:,})")

        if not silent:
            print(f"\n  Done after {round_num} round(s).")
            print("="*60)

    def fill_sp_to_cap_all_accounts(self):
        """Fill SP to cap for all play_enabled accounts."""
        import glob as _glob
        settings_dirs  = [SCRIPT_DIR, os.path.join(SCRIPT_DIR, 'settings')]
        settings_files = []
        for sd in settings_dirs:
            settings_files += _glob.glob(os.path.join(sd, 'settings_*.json'))
        settings_files = [f for f in settings_files
                          if not os.path.basename(f).startswith('settings_TEMPLATE')]
        settings_files = sorted({os.path.normpath(f): f for f in settings_files}.values())

        print(f"\n{'='*60}")
        print(f"  FILL SP TO CAP – ALL ACCOUNTS")
        print(f"{'='*60}")

        for sf in settings_files:
            tmp = TyrantCommander(sf)
            if not tmp.initialize(verbose=False):
                nick = tmp.api.settings.get('kong_name', sf)
                print(f"  ✗ {nick}: login failed")
                continue
            if not tmp.api.settings.get('play_enabled', True):
                continue
            nick = (tmp.api.settings.get('request_data', {}).get('kong_name', '')
                    or tmp.api.settings.get('kong_name', sf))
            print(f"\n  ── {nick} ──")
            tmp.fill_sp_to_cap(silent=False)

    def shop_salvage_workflow(self, pack_count, salvage_base_epics=False, keep_base_epics=1):
        """
        Kompletter Workflow:
          1. Buy packages
          2. Alle Commons salvage
          3. Alle Rares salvage
          4. Optional: Base Epics salvage (keep X)
          5. Summary ausgeben

        Args:
            pack_count: Number of packages to buy
            salvage_base_epics: Wenn True, auch Base Epics salvage
            keep_base_epics: Number of base epics to keep per card

        Returns:
            True if SP cap was reached (caller should stop looping), False otherwise
        """
        # Refresh data to get current state
        self.initialize(verbose=False)

        # Check SP cap before starting
        sp_cap = self.get_sp_cap()
        current_sp = int(self.init_data.get('user_data', {}).get('salvage', 0))
        if current_sp >= sp_cap:
            print(f"\n⚠ SP already full ({current_sp:,} / {sp_cap:,}) - skipping salvage steps")
            sp_full = True
        else:
            sp_full = False

        start_time = datetime.now()

        print(f"\n{'#'*50}")
        print(f"# SHOP & SALVAGE WORKFLOW")
        print(f"# Start: {start_time.strftime('%H:%M:%S')}")
        print(f"{'#'*50}")

        # Status
        self.initialize(verbose=False)
        gold_start = self.get_gold()
        print(f"\n Gold Start: {gold_start:,}")
        print(f" SP:         {current_sp:,} / {sp_cap:,}")

        # Buy
        purchased, new_cards = self.buy_packs(pack_count)
        if purchased == 0:
            print("\n ✗ None Packages purchased – Workflow canceled")
            return sp_full

        sp_gain_common = 0
        sp_gain_rare   = 0
        sp_gain_epics  = 0

        if not sp_full:
            # Commons salvage
            print("\n Wait 3s before Common salvage...")
            sleep(3)
            self.initialize(verbose=False)
            current_sp = int(self.init_data.get('user_data', {}).get('salvage', 0))
            if current_sp >= sp_cap:
                print(f"⚠ SP full ({current_sp:,}/{sp_cap:,}) - skipping Common salvage")
                sp_full = True
            else:
                success_common, sp_gain_common = self.salvage_all_commons()
                self.initialize(verbose=False)
                current_sp = int(self.init_data.get('user_data', {}).get('salvage', 0))
                if current_sp >= sp_cap:
                    print(f"⚠ SP full after Commons ({current_sp:,}/{sp_cap:,}) - skipping Rare salvage")
                    sp_full = True

        if not sp_full:
            # Rares salvage
            print("\n Wait 2s before Rare salvage...")
            sleep(2)
            success_rare, sp_gain_rare = self.salvage_all_rares()
            self.initialize(verbose=False)
            current_sp = int(self.init_data.get('user_data', {}).get('salvage', 0))
            if current_sp >= sp_cap:
                print(f"⚠ SP full after Rares ({current_sp:,}/{sp_cap:,}) - skipping Epic salvage")
                sp_full = True

        if not sp_full and salvage_base_epics:
            # Base Epics salvage (optional)
            print("\n Wait 2s before Base Epic salvage...")
            sleep(2)
            success_epic, sp_gain_epics = self.salvage_base_epics_keep_x(keep_base_epics, silent=True)
            self.initialize(verbose=False)
            current_sp = int(self.init_data.get('user_data', {}).get('salvage', 0))
            if current_sp >= sp_cap:
                sp_full = True

        # Summary
        self.initialize(verbose=False)
        gold_end      = self.get_gold()
        salvage_final = int(self.init_data.get('user_data', {}).get('salvage', 0))
        duration      = (datetime.now() - start_time).seconds

        print(f"\n{'#'*50}")
        print(f"# SUMMARY")
        print(f"{'#'*50}")
        print(f" Duration          : {duration}s")
        print(f" Packages purchased: {purchased}")
        print(f" New cards         : {len(new_cards)}")
        print()
        print(f" Gold Start        : {gold_start:,}")
        print(f" Gold End          : {gold_end:,}")
        print(f" Gold Net          : {gold_end - gold_start:,}")
        print()
        print(f" Common-Salvage    : +{sp_gain_common:,} SP")
        print(f" Rare-Salvage      : +{sp_gain_rare:,} SP")
        if salvage_base_epics:
            print(f" Epic-Salvage      : +{sp_gain_epics:,} SP (keep {keep_base_epics})")
            print(f" Total-Salvage     : +{sp_gain_common + sp_gain_rare + sp_gain_epics:,} SP")
        else:
            print(f" Total-Salvage     : +{sp_gain_common + sp_gain_rare:,} SP")
        print()
        print(f" SP Balance        : {salvage_final:,} / {sp_cap:,}{' ⚠ FULL' if sp_full else ''}")
        print(f"{'#'*50}\n")

        return sp_full

    # ==================== DAILY BONUS & REWARDS ====================
    
    def claim_daily_reward_all_accounts(self):
        """Claims the daily bonus for all play_enabled accounts."""
        import glob as _glob, json as _json

        settings_dirs  = [SCRIPT_DIR, os.path.join(SCRIPT_DIR, 'settings')]
        settings_files = []
        for sd in settings_dirs:
            settings_files += _glob.glob(os.path.join(sd, 'settings_*.json'))
        settings_files = [f for f in settings_files
                          if not os.path.basename(f).startswith('settings_TEMPLATE')]
        settings_files = sorted({os.path.normpath(f): f for f in settings_files}.values())

        print(f"\n{'='*65}")
        print(f"  CLAIM DAILY REWARD – ALL ACCOUNTS")
        print(f"{'='*65}")

        claimed = 0; already = 0; cooldown = 0; failed = 0; skipped = 0
        for sf in settings_files:
            nick = os.path.basename(sf).replace('settings_', '').replace('.json', '')
            try:
                with open(sf, 'r', encoding='utf-8') as fh:
                    cfg = _json.load(fh)
                if not cfg.get('play_enabled', True):
                    skipped += 1
                    continue
            except Exception:
                skipped += 1
                continue

            print(f"\n{'─'*65}")
            print(f"  [{nick}]")
            try:
                tmp = TyrantCommander(sf)
                if not tmp.initialize(verbose=False):
                    print(f"  ✗ Login failed")
                    failed += 1
                    continue
                result = tmp.auto_claim_daily_bonus()
                if result is True:
                    claimed += 1
                else:
                    failed += 1
            except Exception as e:
                print(f"  ✗ {e}")
                failed += 1

        print(f"\n{'='*65}")
        print(f"  Done — {claimed} ✓  {failed} ✗  {skipped} skipped (disabled)")

    def auto_claim_daily_bonus(self):
        """
        Checks and claims Daily Bonus automatically on startup.
        Shows cooldown if not available.
        
        Returns:
            bool: True if successfully claimed or already claimed, False on error
        """
        try:
            # Refresh data to get current state
            self.initialize(verbose=False)
            
            # Check daily_bonus_time in init_data
            daily_bonus_time = int(self.init_data.get('daily_bonus_time', 0))
            current_time = int(time.time())
            
            # daily_bonus_time in the future = cooldown still active
            if daily_bonus_time > current_time:
                cooldown_seconds = daily_bonus_time - current_time
                hours = cooldown_seconds // 3600
                minutes = (cooldown_seconds % 3600) // 60
                
                print(f"\n{'─'*60}")
                print(f"📅 Daily Reward")
                print(f"{'─'*60}")
                print(f"Status:   ⏳ Cooldown active")
                print(f"Available in: {hours}h {minutes}min")
                print(f"{'─'*60}")
                return True
            
            # Daily Bonus is available - claim
            result = self.api.call('useDailyBonus')
            
            if result and result.get('result') in (True, 1, '1', 'true'):
                print(f"\n{'─'*60}")
                print(f"📅 Daily Reward")
                print(f"{'─'*60}")
                print(f"Status:   ✓ Successfully claimed!")
                
                # Show reward - attempt to resolve card name
                if 'reward' in result:
                    reward = result['reward']
                    print(f"Reward: {reward}")
                elif 'cards' in result:
                    cards = result.get('cards', {})
                    if cards:
                        # Resolve card ID to name
                        card_data = self._load_card_data()
                        
                        # Show first card (Daily Bonus gives only 1 card)
                        card_id = list(cards.keys())[0]
                        card_info = card_data.get(int(card_id), f"card #{card_id}") if card_data else f"card #{card_id}"
                        # Handle both dict and string
                        if isinstance(card_info, dict):
                            card_name = card_info.get('name', f"card #{card_id}")
                        else:
                            card_name = str(card_info)
                        
                        print(f"Reward: {card_name}")
                
                print(f"{'─'*60}")
                

                self.initialize(verbose=False)
                return True
            else:
                # Already claimed or error
                if result and 'message' in result:
                    msg = result['message']
                    if 'already' in msg.lower():
                        print(f"\n{'─'*60}")
                        print(f"📅 Daily Reward")
                        print(f"{'─'*60}")
                        print(f"Status:   ✓ Already claimed today")
                        print(f"{'─'*60}")
                        return True
                
                return False
                
        except Exception as e:
            # Silent error handling - should not block startup
            return False
    
    def _unlock_locked_cards(self, card_ids):
        """
        Unlocks all locked cards from the given card_ids list (silent, with progress).
        Only cards with is_locked=True in user_cards are touched.
        Returns number of cards unlocked.
        """
        user_cards = self.init_data.get('user_cards', {})
        to_unlock = [str(cid) for cid in card_ids
                     if user_cards.get(str(cid), {}).get('is_locked')]
        if not to_unlock:
            return 0
        print(f"  🔓 Unlocking {len(to_unlock)} locked card(s)...", end=' ', flush=True)
        ok = 0
        for cid in to_unlock:
            try:
                r = self.api.call('setCardLock', card_id=cid, locked='0')
                if r and r.get('result') in (True, 1, '1', 'true'):
                    ok += 1
            except Exception:
                pass
            sleep(0.1)
        print(f"✓ ({ok}/{len(to_unlock)} unlocked)")
        return ok

    def unlock_commander(self):
        """
        Unlock a special Commander via the unlockCommander API endpoint.
        Shows a numbered selection list, or accepts a name/ID directly.
        """
        self.initialize(verbose=False)
        card_data = self._load_card_data()

        # Known special commanders: (display_name, base_id, [all other IDs: upgrades + fusion chain])
