# ==================== SETTINGS GENERATOR ====================

def generate_settings_from_response():
    """
    Creates a settings_name.json from API response.
    Supports JSON, URL-encoded, and cURL formats.
    Extracts all required fields for the new format.
    """
    print("="*80)
    print("SETTINGS GENERATOR")
    print("="*80)
    print("\nInsert API data in one of these formats:")
    print("  • JSON from Browser DevTools -> Network -> Response")
    print("  • URL-encoded POST-Body from Request -> Payload")
    print("  • cURL command (Copy as cURL from Chrome/Edge)")
    print()
    
    # Multi-line input support
    print("Paste data and press Enter twice when done (type ESC on empty line to cancel):")
    lines = []
    while True:
        line = input()
        if line.strip().lower() == 'esc':  # ESC keyword on its own line = cancel
            print("↩ Cancelled")
            return
        if not line and lines:  # Empty line after content = done
            break
        if line:
            lines.append(line)

    full_text = '\n'.join(lines).strip()

    if not full_text:
        print("✗ Empty input")
        return
    
    # Initialize all fields
    user_id = None
    password = None
    syncode = None
    kong_id = None
    kong_token = None
    kong_name = None
    
    # FIXED VALUES - These are ALWAYS set to these values
    # DO NOT change these values even if different values come from input!
    unity = "Unity5_4_2"
    client_version = "80"
    device_type = "Firefox 147.0"
    os_version = "Windows 10"
    platform = "Web"
    
    # ===== TRY 1: cURL FORMAT =====
    # Detect cURL (starts with "curl" and contains "--data-raw")
    if full_text.lower().startswith('curl') and '--data-raw' in full_text:
        print("\n⏳ Parsing cURL format...")
        from urllib.parse import parse_qs, unquote
        import re
        
        # Remove Windows cmd line continuation (^)
        full_text = full_text.replace('^', '')
        
        # Remove Unix shell line continuation (\)
        full_text = full_text.replace('\\\n', ' ')
        
        # Extract --data-raw content
        # Pattern: --data-raw "content" or --data-raw 'content'
        data_raw_match = re.search(r'--data-raw\s+["\']([^"\']+)["\']', full_text, re.DOTALL)
        
        if data_raw_match:
            data_raw = data_raw_match.group(1)
            
            # Remove any remaining line breaks
            data_raw = data_raw.replace('\n', '').replace('\r', '')
            
            # Parse as URL-encoded
            params = parse_qs(data_raw)
            
            # Extract values (parse_qs returns lists)
            user_id = params.get('user_id', [None])[0]
            password = params.get('password', [None])[0]
            syncode = params.get('syncode', [None])[0]
            kong_id = params.get('kong_id', [None])[0]
            kong_token = params.get('kong_token', [None])[0]
            kong_name = params.get('kong_name', [None])[0]
            
            # Decode URL-encoded values
            if kong_name:
                kong_name = unquote(kong_name)
            
            print(f"✓ Extracted from cURL --data-raw")
        else:
            print("⚠ Could not find --data-raw in cURL command")
    
    # ===== TRY 2: URL-ENCODED FORMAT =====
    # Try URL-encoded Format (typical for API POST-Body)
    if not all([user_id, password, kong_id, kong_token]) and '=' in full_text and '&' in full_text:
        print("\n⏳ Parsing URL-encoded format...")
        from urllib.parse import parse_qs, unquote
        
        # Remove line breaks
        full_text = full_text.replace('\n', '').replace('\r', '')
        
        # Parse as query string
        params = parse_qs(full_text)
        
        # Extract values (parse_qs returns lists)
        user_id = params.get('user_id', [None])[0]
        password = params.get('password', [None])[0]
        syncode = params.get('syncode', [None])[0]
        kong_id = params.get('kong_id', [None])[0]
        kong_token = params.get('kong_token', [None])[0]
        kong_name = params.get('kong_name', [None])[0]
        # NOTE: unity, client_version, device_type, os_version, platform are FIXED
        # and will NOT be extracted from input!
        
        if kong_name:
            kong_name = unquote(kong_name)
        if device_type:
            device_type = unquote(device_type)
    
    # ===== TRY 3: JSON FORMAT =====
    # If URL-encoded not successful, try JSON
    if not all([user_id, password, kong_id, kong_token]):
        try:
            print("\n⏳ Parsing JSON format...")
            data = json.loads(full_text)
            
            # Extract from verschiedenen possibleen Strukturen
            if 'request' in data:
                request = data['request']
                user_id = request.get('user_id')
                password = request.get('password')
                syncode = request.get('syncode')
                kong_id = request.get('kong_id')
                kong_token = request.get('kong_token')
                kong_name = request.get('kong_name')
            elif 'request_data' in data:
                request_data = data['request_data']
                user_id = request_data.get('user_id')
                password = request_data.get('password')
                syncode = request_data.get('syncode')
                kong_id = request_data.get('kong_id')
                kong_token = request_data.get('kong_token')
                kong_name = request_data.get('kong_name')
            else:
                user_id = data.get('user_id')
                password = data.get('password')
                syncode = data.get('syncode')
                kong_id = data.get('kong_id')
                kong_token = data.get('kong_token')
                kong_name = data.get('kong_name')
        except json.JSONDecodeError:
            pass
    
    # Validate required fields
    if not all([user_id, password, kong_id, kong_token]):
        print("\n✗ Missing required fields!")
        print(f"   user_id:    {user_id or '❌ MISSING'}")
        print(f"   password:   {password or '❌ MISSING'}")
        print(f"   syncode:    {syncode or '⚠️  MISSING (optional but recommended)'}")
        print(f"   kong_id:    {kong_id or '❌ MISSING'}")
        print(f"   kong_token: {kong_token or '❌ MISSING'}")
        print(f"   kong_name:  {kong_name or '(optional)'}")
        print("\nTip: Copy the complete POST-Body or cURL command from Browser DevTools:")
        print("     Chrome: Network -> Right-click -> Copy -> Copy as cURL (cmd)")
        print("     DevTools: Network -> Request -> Payload (view source)")
        return
    
    # Ask for filename
    default_name = kong_name.lower() if kong_name else "user"
    name_input = input(f"\nFilename for settings_<name>.json (empty={default_name}): ").strip()
    name = name_input if name_input else default_name
    
    # Create settings dict in new format
    # NOTE: unity, client_version, device_type, os_version, platform are FIXED!
    settings = {
        "request_data": {
            "user_id": user_id,
            "password": password,
            "syncode": syncode or "0",
            "kong_id": kong_id,
            "kong_token": kong_token,
            "kong_name": kong_name or "",
            "_comment": "=== FIXED VALUES - DO NOT CHANGE ===",
            "unity": unity,
            "client_version": client_version,
            "device_type": device_type,
            "os_version": os_version,
            "platform": platform
        },
        "url": "mobile.tyrantonline.com",
        "user_agent": "Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/85.0.4183.121 Safari/537.36"
    }
    
    # Save file
    filename = f"settings_{name}.json"
    filepath = os.path.join(SCRIPT_DIR, filename)
    
    with open(filepath, 'w') as f:
        json.dump(settings, f, indent=2)
    
    print(f"\n✓ Settings saved: {filepath}\n")
    print(json.dumps(settings, indent=2))
    print(f"\n{'='*80}")
    print("ℹ️  NOTE: Fixed values were automatically set:")
    print(f"   unity: {unity}")
    print(f"   client_version: {client_version}")
    print(f"   device_type: {device_type}")
    print(f"   os_version: {os_version}")
    print(f"   platform: {platform}")
    print(f"\n   These values should NOT be changed!")
    print(f"{'='*80}")







